	@Provides
	PersonalSpaceConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PersonalSpaceConfig.class);
	}

	@Override
	protected void startUp()
	{
		if (config.mode() == PersonalSpaceConfig.Mode.TEST_SHIFT_ME)
		{
			// Test mode has no switch any more: nobody is left stuck in it.
			configManager.setConfiguration(PersonalSpaceConfig.GROUP, PersonalSpaceConfig.KEY_MODE, PersonalSpaceConfig.Mode.SPREAD);
		}
		probe = new StackProbe(client, offsets, stacks);
		renderCallbackManager.register(probe);
		levelFilter = new LevelFilter(client);
		renderCallbackManager.register(levelFilter);
		chatHider = new ChatHider(client, levelFilter);
		alchStyler = new AlchStyler(client);
		idleSitter = new IdleSitter(client);
		alchStyler.sitter = idleSitter;
		namesOverlay = new NamesOverlay(client, config, configManager, offsets, partyService, chatIconManager, levelFilter);
		overlayManager.add(namesOverlay);
		hoverOverlay = new HoverOverlay(client, config, offsets, stacks, tooltipManager, levelFilter);
		overlayManager.add(hoverOverlay);
		chatRangeOverlay = new ChatRangeOverlay(client);
		overlayManager.add(chatRangeOverlay);

		PersonalSpacePanel newPanel = new PersonalSpacePanel(configManager, config);
		newPanel.onTurnOnGpu(this::turnOnGpu);
		BufferedImage icon = ImageUtil.loadImageResource(PersonalSpacePlugin.class, "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Personal Space")
			.icon(icon)
			.priority(7)
			.panel(newPanel)
			.build();
		if (config.showSidebarButton())
		{
			clientToolbar.addNavigation(navButton);
		}
		panel = newPanel;

		clientThread.invoke(() ->
		{
			lastFrameNanos = 0;
			lastPanelNanos = 0;
			warnedNoRenderer = false;
			warnedBadIds = false;
			countedWrapper = null;
			noDrawsStreak = 0;
			nothingMovedStreak = 0;
			resetTickState();
			probe.reset();
			// The shim itself is installed on the next frame, see ensureInstalled().
		});
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(probe);
		if (levelFilter != null)
		{
			renderCallbackManager.unregister(levelFilter);
			levelFilter = null;
		}
		chatHider = null;
		alchStyler = null;
		IdleSitter sitter = idleSitter;
		idleSitter = null;
		clientThread.invoke(() ->
		{
			if (sitter != null)
			{
				sitter.standAll();
			}
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.refreshChat();
			}
		});
		if (namesOverlay != null)
		{
			overlayManager.remove(namesOverlay);
			namesOverlay = null;
		}
		if (hoverOverlay != null)
		{
			overlayManager.remove(hoverOverlay);
			hoverOverlay = null;
		}
		if (chatRangeOverlay != null)
		{
			overlayManager.remove(chatRangeOverlay);
			chatRangeOverlay = null;
		}
		panel = null;
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		clientThread.invoke(() ->
		{
			uninstall();
			resetTickState();
		});
	}

	/** As each chat line is built: drop it if it's from someone the level filter hides, or said too far away. */
	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		ChatHider hider = chatHider;
		int range = config.hideChatFurtherThan();
		if (hider != null && "chatFilterCheck".equals(event.getEventName()) && (config.hideTheirChat() || range > 0))
		{
			hider.check(config.hideTheirChat(), range);
		}
	}

	/** As each chat line arrives: note how far away its speaker is (Hide chat further than). */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatHider hider = chatHider;
		if (hider != null && event.getMessageNode() != null)
		{
			hider.heard(event.getType(), event.getMessageNode().getId(), event.getName());
		}
	}

	/** Someone further away than "Hide chat further than" says nothing over their head either. */
	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		// Someone talking isn't away from the keyboard: they don't sit (Idle players sit).
		IdleSitter sitter = idleSitter;
		if (sitter != null && event.getActor() instanceof Player && event.getActor() != client.getLocalPlayer())
		{
			sitter.busy((Player) event.getActor(), client.getGameCycle());
		}
		ChatHider hider = chatHider;
		int range = config.hideChatFurtherThan();
		if (hider != null && range > 0 && event.getActor() instanceof Player
			&& hider.overheadTooFar((Player) event.getActor(), range))
		{
			// As RuneLite's Chat Filter does: a blank, not nothing.
			event.getActor().setOverheadText(" ");
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!PersonalSpaceConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		ChatRangeOverlay range = chatRangeOverlay;
		if (range != null && PersonalSpaceConfig.KEY_CHAT_RANGE.equals(event.getKey()))
		{
			// Show how far that is, on the ground round you, while the slider moves.
			range.show(config.hideChatFurtherThan());
		}
		if (PersonalSpaceConfig.KEY_HIDE_CHAT.equals(event.getKey()) || PersonalSpaceConfig.KEY_HIDE_BELOW.equals(event.getKey())
			|| PersonalSpaceConfig.KEY_CHAT_RANGE.equals(event.getKey()))
		{
			// Rebuild the chat box, so lines appear or go as the setting changes. The new level
			// goes in first (the tick would only set it later), and who was remembered as hidden
			// is forgotten, or lowering the level would keep hiding them.
			boolean newLevel = PersonalSpaceConfig.KEY_HIDE_BELOW.equals(event.getKey());
			clientThread.invoke(() ->
			{
				LevelFilter filter = levelFilter;
				ChatHider hider = chatHider;
				if (newLevel && filter != null && hider != null)
				{
					filter.below = config.hideBelowLevel();
					hider.clear();
				}
				if (client.getGameState() == GameState.LOGGED_IN)
				{
					client.refreshChat();
				}
			});
		}
		PersonalSpacePanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::refreshControls);
		}
		NavigationButton button = navButton;
		if (PersonalSpaceConfig.KEY_SHOW_SIDEBAR.equals(event.getKey()) && button != null)
		{
			// For anyone who likes a tidy sidebar; the settings stay in the plugin's config.
			boolean show = config.showSidebarButton();
			SwingUtilities.invokeLater(() ->
			{
				if (navButton != button)
				{
					return; // switched off meanwhile
				}
				if (show)
				{
					clientToolbar.addNavigation(button);
				}
				else
				{
					clientToolbar.removeNavigation(button);
				}
			});
		}
		if (PersonalSpaceConfig.KEY_ACTIVE.equals(event.getKey()) && !config.active())
		{
			// Pausing takes effect immediately, not on the next game tick.
			clientThread.invoke(this::resetTickState);
		}
	}

	// ---- per frame ---------------------------------------------------------------------

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		AlchStyler styler = alchStyler;
		LevelFilter filter = levelFilter;
		if (styler != null)
		{
			// Before the scene is drawn: an alch cast never shows for a frame. Only while the
			// effect is on, and not in PvP areas, like the level filter.
			styler.apply(config.otherAlchers(), filter != null && filter.enabled);
		}
		ensureInstalled();
		if (wrapper != null)
		{
			wrapper.drawMeInFront = config.drawMeInFront();
			wrapper.depthBetweenPlayers = config.depthBetweenPlayers();
			wrapper.walkWhileBusy = config.walkWhileBusy();
		}

		long now = System.nanoTime();
		float dt = lastFrameNanos == 0 ? 0f : (now - lastFrameNanos) / 1_000_000_000f;
		lastFrameNanos = now;
		offsets.advance(Math.min(dt, 0.25f));
		keepOffWalls(Math.min(dt, 0.25f));

		if (lastPanelNanos == 0 || now - lastPanelNanos >= PANEL_REFRESH_NANOS)
		{
			pushSnapshot(now);
		}
	}

	/**
	 * Client thread, once a frame, after the offsets have moved: nobody whose offset is running out
	 * is drawn through a wall (see {@link OffsetTable#keepClear}). Only players drawn away from
	 * where they are get looked at, and the walls are only read when someone is.
	 */
	private void keepOffWalls(float dt)
	{
		WorldView top = offsets.anyActive() ? client.getTopLevelWorldView() : null;
		if (top == null)
		{
			return;
		}
		keepOffWalls(top, dt);
		for (WorldView boat : top.worldViews())
		{
			if (boat != null)
			{
				keepOffWalls(boat, dt);
			}
		}
	}

	private void keepOffWalls(WorldView wv, float dt)
	{
		CollisionTerrain terrain = null;
		for (Player p : wv.players())
		{
			int id = p == null ? -1 : p.getId();
			if (!offsets.isOffset(id))
			{
				continue;
			}
			LocalPoint lp = p.getLocalLocation();
			WorldPoint wp = p.getWorldLocation();
			if (lp == null || wp == null)
			{
				continue;
			}
			if (terrain == null)
			{
				terrain = terrain(wv);
			}
			boolean runningOut = offsets.targetIsMiddle(id) || !StillnessTracker.isCentred(lp.getX(), lp.getY());
			offsets.keepClear(id, lp.getX(), lp.getY(), SpreadingDrawCallbacks.reallyMoving(p), dt, runningOut, terrain.walls(wp.getPlane()));
		}
	}

	/**
	 * Keep our shim in front of whichever renderer is active. Renderers install themselves with
	 * setDrawCallbacks when they start and set it to null when they stop, so this is re-checked
	 * every frame rather than once at start-up. Cheap: one getter and a reference compare.
	 * Swapping is instant, except that if it lands while the game is part-way through loading a
	 * new area, the game restarts that load once; so it is only ever done when actually needed.
	 */
	private void ensureInstalled()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			// There is nothing to spread until you are in the world, and a renderer is at its most
			// delicate while it is starting up or shutting down: it creates and destroys its native
			// drawing context around then, and anything standing in front of it at that moment can be
			// handed calls it isn't ready for. So we stay out of the way until the world is up.
			uninstall();
			return;
		}

		DrawCallbacks current = client.getDrawCallbacks();
		if (current == null)
		{
			// No GPU renderer running; the software renderer never calls draw callbacks.
			wrapper = null;
			return;
		}
		if (current == wrapper)
		{
			return;
		}

		DrawCallbacks target = current;
		if (current instanceof SpreadingDrawCallbacks)
		{
			// Never stack shims (e.g. one left behind by an earlier instance of this plugin).
			target = ((SpreadingDrawCallbacks) current).getDelegate();
		}
		wrapper = new SpreadingDrawCallbacks(client, offsets, stacks, probe, renderCallbackManager, target);
		wrapper.hides = hideLog;
		wrapper.busyWalks = !busyWalksOff;
		client.setDrawCallbacks(wrapper);
		shimInstalls++;
		log.debug("Hooked draw callbacks in front of {}", target.getClass().getName());
	}

	private void uninstall()
	{
		if (wrapper != null && client.getDrawCallbacks() == wrapper)
		{
			client.setDrawCallbacks(wrapper.getDelegate());
			log.debug("Restored draw callbacks to {}", wrapper.getDelegate().getClass().getName());
		}
		wrapper = null;
	}

	// ---- per game tick -----------------------------------------------------------------

	/**
	 * Players walking to a spot are drawn with their action swapped for the walk for a moment, which
	 * the client doesn't report to anyone. Should it ever, other plugins (an idle notifier, say) would
	 * hear of animation changes that never happened: action swaps are switched off at once.
	 */
	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		AlchStyler styler = alchStyler;
		if (styler != null)
		{
			styler.noticed(event.getActor());
		}
		SpreadingDrawCallbacks w = wrapper;
		if (w != null && w.fromBusySwap(event.getActor()))
		{
			busyWalksOff = true;
			w.busyWalks = false;
			log.warn("Animation change reported while showing a player walking; busy players glide again, and crowds may, until restart");
		}
	}

	/** An alch's spell effect is taken off before the next frame too (Alchers behavior). */
	@Subscribe
	public void onGraphicChanged(GraphicChanged event)
	{
		AlchStyler styler = alchStyler;
		if (styler != null)
		{
			styler.noticed(event.getActor());
		}
	}

	/**
	 * Using an item or spell, someone drawn away from where they really stand takes the left-click
	 * from what you see there instead: you used raw fish on the campfire, which looked empty, and
	 * traded the people standing in it. Their option is put below the rest; right-click still has it.
	 */
	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.clickPastMoved())
		{
			return;
		}
		net.runelite.api.MenuEntry entry = event.getMenuEntry();
		net.runelite.api.MenuAction type = entry.getType();
		if (type != net.runelite.api.MenuAction.WIDGET_TARGET_ON_PLAYER)
		{
			return;
		}
		// Nor does anyone left undrawn, hidden in the middle of a crowd: the fire looked empty.
		Player player = entry.getPlayer();
		if (player != null && (movedAway(player.getId(), offsets.dx(player.getId()), offsets.dz(player.getId()))
			|| hideLog.notedLately(player.getId(), offsets.frame())))
		{
			entry.setDeprioritized(true);
		}
	}

	/** The walk animations walks were drawn with legs still, most first, each marked if skeletal. */
	private static String topAnimations(Map<Integer, Long> counts, Client client)
	{
		StringBuilder top = new StringBuilder();
		counts.entrySet().stream()
			.sorted((a, b) -> Long.compare(b.getValue(), a.getValue()))
			.limit(4)
			.forEach(e ->
			{
				boolean skeletal = false;
				try
				{
					net.runelite.api.Animation a = client.loadAnimation(e.getKey());
					skeletal = a != null && a.isMayaAnim();
				}
				catch (RuntimeException ignored)
				{
					// left unmarked
				}
				top.append(top.length() == 0 ? "" : ", ").append(e.getKey()).append(skeletal ? " (skeletal)" : "").append(" x").append(e.getValue());
			});
		return top.toString();
	}

	/** Whether a player is drawn away from where they really stand. */
	static boolean movedAway(int id, int dx, int dz)
	{
		return id >= 0 && id < OffsetTable.CAPACITY && (dx != 0 || dz != 0);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			resetTickState();
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			probe.reset();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tick++;
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			resetTickState();
			return;
		}
		Player local = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		if (local == null || wv == null)
		{
			resetTickState();
			return;
		}

		Snapshot.Gate newGate = safetyGate(local);
		if (newGate != Snapshot.Gate.SAFE || !config.active())
		{
			// Hard off: straight back to real positions, no easing, no exceptions.
			resetTickState();
			gate = newGate;
			return;
		}
		gate = newGate;
		levelFilter.below = config.hideBelowLevel();
		levelFilter.enabled = true;
		if (idleSitter != null)
		{
			idleSitter.update(config.idlePlayersSit());
		}

		if (wrapper == null && !warnedNoRenderer && client.getDrawCallbacks() == null)
		{
			warnedNoRenderer = true;
			client.addChatMessage(ChatMessageType.CONSOLE, "",
				"<col=ff8c00>Personal Space</col>: turn on the GPU plugin (or 117 HD) for this plugin to have any effect.", null);
		}

		probe.enabled = config.mode() == PersonalSpaceConfig.Mode.SPREAD;
		if (config.mode() == PersonalSpaceConfig.Mode.TEST_SHIFT_ME)
		{
			offsets.clearTargets();
			stacks.clear();
			offsets.setTarget(local.getId(), config.testOffset(), 0);
			nearby = countPlayers(wv);
			still = 0;
			aboard = 0;
			stackedTiles = 0;
			moving = config.testOffset() > 0 ? 1 : 0;
			skippedIds = 0;
			unseen = 0;
			nearestTile = null;
			yourShape = null;
			return;
		}

		List<StackSpreader.Entry> entries = new ArrayList<>();
		List<StackSpreader.Placement> easingBack = new ArrayList<>();
		int nearbyCount = 0;
		int skipped = 0;
		int cycle = client.getGameCycle();
		int onBoats = 0;
		// The main world, then every boat in view: each is a world of its own, with its own deck.
		List<WorldView> worlds = new ArrayList<>();
		worlds.add(wv);
		for (WorldView boat : wv.worldViews())
		{
			if (boat != null)
			{
				worlds.add(boat);
			}
		}
		for (WorldView world : worlds)
		{
		for (Player p : world.players())
		{
			if (p == null)
			{
				continue;
			}
			nearbyCount++;
			if (world != wv)
			{
				onBoats++;
			}
			int id = p.getId();
			if (id < 0 || id >= OffsetTable.CAPACITY || idSeenTick[id] == tick)
			{
				// Out of range, or a second player with the same id this tick: offsets are keyed
				// by id, so such a player can't be moved safely. Should never happen.
				skipped++;
				if (!warnedBadIds)
				{
					warnedBadIds = true;
					log.warn("Skipping player with unusable id {}", id);
				}
				continue;
			}
			idSeenTick[id] = tick;

			LocalPoint lp = p.getLocalLocation();
			WorldPoint wp = p.getWorldLocation();
			if (lp == null || wp == null)
			{
				continue;
			}
			long tileKey = StackRegistry.key(StackRegistry.layer(world.getId(), wp.getPlane()), lp.getSceneX(), lp.getSceneY());
			boolean centred = StillnessTracker.isCentred(lp.getX(), lp.getY());
			boolean standingStill = stillness.observe(id, tileKey, centred, tick);
			offsets.setWalkingOff(id, !centred);
			if (!standingStill || p.isDead())
			{
				if (centred && offsets.isOffset(id))
				{
					// Dropped out of a ring but still on the tile: keep drawing them while they
					// ease back to the middle, instead of vanishing on the spot.
					easingBack.add(new StackSpreader.Placement(id, tileKey, 0, 0));
				}
				continue;
			}
			if (probe.isShown(id, p, cycle) && probe.othersAllow(renderCallbackManager, p))
			{
				shownTick[id] = tick;
			}
			if (p.getAnimation() != -1)
			{
				busyTick[id] = tick;
				busyAnimation[id] = p.getAnimation();
			}
			boolean busy = busyTick[id] != 0 && tick - busyTick[id] <= BUSY_TICKS;
			entries.add(new StackSpreader.Entry(id, tileKey, p == local, p.getCurrentOrientation(), busy, wearsCape(p.getPlayerComposition())));
		}
		}

		planner.smallGroupsClose = config.smallGroupsClose();
		planner.pose = config.pose();
		planner.cameraX = client.getCameraX();
		planner.cameraY = client.getCameraY();
		if (local.getWorldView() != null && local.getWorldView().getId() != WorldView.TOPLEVEL)
		{
			// Aboard a boat: the deck has coordinates of its own and the camera's are the world's,
			// so which way the camera is from you can't be told. Nobody steps out of your view.
			planner.cameraX = Integer.MIN_VALUE;
			planner.cameraY = Integer.MIN_VALUE;
		}
		planner.arrangement = config.arrangement();
		CrowdPlanner.Plan plan = planner.plan(entries, id -> shownTick[id] == tick, config.spacing(), config.maxStack(),
			config.arrangement() != PersonalSpaceConfig.Arrangement.CIRCLE, config.includeLocalPlayer(), tick, surroundings(wv));
		offsets.clearTargets();
		for (StackSpreader.Placement pl : plan.unplaced)
		{
			if (pl.id >= 0 && pl.id < OffsetTable.CAPACITY && placedTick[pl.id] == tick - 1 && placedTile[pl.id] == pl.tile)
			{
				spotLosses++;
			}
		}
		// Busy people waiting in the middle of their tile for a break: drawn there like anyone else
		// waiting in the middle, so only one of them at a time, and nobody inside you. Drawn as well,
		// two people arriving together at a campfire stood inside each other until they moved.
		Set<Integer> waitingInTheMiddle = new HashSet<>();
		int localId = local.getId();
		// Middles someone else holds, or that aren't drawn: anyone waiting there is hidden.
		Set<Long> middleTaken = new HashSet<>(plan.middleOutOfSight);
		for (StackSpreader.Placement pl : plan.unplaced)
		{
			middleTaken.add(pl.tile);
		}
		for (StackSpreader.Entry e : entries)
		{
			if (e.local)
			{
				middleTaken.add(e.tile);
			}
		}
		for (StackSpreader.Placement pl : plan.placements)
		{
			if (pl.id >= 0 && pl.id < OffsetTable.CAPACITY && placedTick[pl.id] != tick - 1)
			{
				// Not placed last tick: whatever they were waiting for then is over. Left set, it ended
				// their next wait at once, or counted a break that never happened.
				busyWaitSince[pl.id] = 0;
			}
		}
		for (StackSpreader.Placement pl : plan.placements)
		{
			boolean valid = pl.id >= 0 && pl.id < OffsetTable.CAPACITY;
			int nowX = valid ? offsets.dx(pl.id) : 0;
			int nowZ = valid ? offsets.dz(pl.id) : 0;
			boolean fromTheMiddle = valid && nowX == 0 && nowZ == 0 && (pl.dx != 0 || pl.dz != 0);
			boolean aStep = valid && Math.hypot(pl.dx - nowX, pl.dz - nowZ) >= OffsetTable.MIN_WALK_DISTANCE;
			boolean busyStep = valid && aStep && !offsets.isWalking(pl.id) && busyTick[pl.id] == tick;
			boolean waitHere = busyStep && (busyWaitSince[pl.id] != 0
				|| worthWaiting(busyAnimation[pl.id], fromTheMiddle && !middleTaken.contains(pl.tile)));
			if (busyStep && !waitHere)
			{
				waitSkipped++;
			}
			if (waitHere)
			{
				// Mid-action: stay put, in the middle or in their spot, for a break in it, then walk.
				if (busyWaitSince[pl.id] == 0)
				{
					busyWaitSince[pl.id] = tick;
				}
				if (tick - busyWaitSince[pl.id] < (fromTheMiddle ? BUSY_WAIT_TICKS : BUSY_MOVE_WAIT_TICKS))
				{
					if (!fromTheMiddle)
					{
						offsets.setTarget(pl.id, nowX, nowZ);
					}
					else
					{
						middleTaken.add(pl.tile);
						if (pl.id != localId)
						{
							waitingInTheMiddle.add(pl.id);
						}
					}
					placedTile[pl.id] = pl.tile;
					placedTick[pl.id] = tick;
					continue;
				}
				if (fromTheMiddle)
				{
					// Only waits in the middle teach what's worth waiting for: one in a spot runs out
					// sooner, so it said too little about whether the action pauses.
					noteWaitOutcome(busyAnimation[pl.id], false);
				}
			}
			else if (valid && busyWaitSince[pl.id] != 0 && busyTick[pl.id] != tick && fromTheMiddle)
			{
				noteWaitOutcome(busyAnimation[pl.id], true);
			}
			if (pl.id >= 0 && pl.id < OffsetTable.CAPACITY)
			{
				busyWaitSince[pl.id] = 0;
			}
			offsets.setTarget(pl.id, pl.dx, pl.dz);
			if (pl.id >= 0 && pl.id < OffsetTable.CAPACITY)
			{
				placedTile[pl.id] = pl.tile;
				placedTick[pl.id] = tick;
			}
		}
		// Everyone on a crowded tile goes in the table, not just those given a spot: the probe needs
		// them there to find out whether the game is willing to show them.
		List<StackSpreader.Placement> members = new ArrayList<>(plan.placements);
		members.addAll(plan.unplaced);
		members.addAll(easingBack);
		java.util.Set<Integer> unplacedIds = new java.util.HashSet<>();
		for (StackSpreader.Placement pl : plan.unplaced)
		{
			unplacedIds.add(pl.id);
		}
		unplacedIds.addAll(waitingInTheMiddle);
		// Curved rows and counter rows alike: everyone turns towards what they are facing.
		Set<Long> turnIn = new HashSet<>(plan.curvedRows);
		turnIn.addAll(plan.facingIn);
		stacks.rebuild(members, turnIn, unplacedIds, plan.fires, plan.poses, plan.middleOutOfSight);
		stacks.setWaiting(waitingInTheMiddle);
		stacks.setArrivals(stillness::arrivedTick);
		probe.forgetTilesNotIn(stacks);

		nearby = nearbyCount;
		aboard = onBoats;
		still = entries.size();
		stackedTiles = StackSpreader.stackedTiles(entries);
		if (moving >= 6 && plan.placements.size() * 2 < moving)
		{
			planDips++;
		}
		moving = plan.placements.size();
		skippedIds = skipped;
		unseen = plan.unseen;
		nearestTile = nearestTileReport(plan, local);
		yourShape = yourShapeReport(plan, local, config.spacing(), config.smallGroupsClose());
	}

	/** Why the effect must be off right now, or SAFE. */
	private Snapshot.Gate safetyGate(Player local)
	{
		if (client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1)
		{
			return Snapshot.Gate.WILDERNESS;
		}
		if (client.getVarbitValue(VarbitID.PVP_AREA_CLIENT) == 1)
		{
			return Snapshot.Gate.PVP_AREA;
		}
		EnumSet<WorldType> types = client.getWorldType();
		if (WorldType.isPvpWorld(types)
			|| types.contains(WorldType.PVP_ARENA)
			|| types.contains(WorldType.DEADMAN)
			|| types.contains(WorldType.TOURNAMENT_WORLD)
			|| types.contains(WorldType.BOUNTY))
		{
			return Snapshot.Gate.PVP_WORLD;
		}
		if (playersCanFight())
		{
			return Snapshot.Gate.PVP_ACTIVITY;
		}
		Actor target = local.getInteracting();
		boolean attacking = target instanceof NPC || target instanceof Player;
		boolean fighting = combat.update(local.getHealthRatio() != -1, attacking, attacking && target.getHealthRatio() != -1, tick);
		if (fighting && config.pauseInCombat())
		{
			return Snapshot.Gate.IN_COMBAT;
		}
		return Snapshot.Gate.SAFE;
	}

	/**
	 * True when the game offers to attack other players, as in Castle Wars, Soul Wars, Last Man
	 * Standing, Clan Wars or the Fight Pits, even on a normal world outside the Wilderness.
	 */
	private boolean playersCanFight()
	{
		String[] options = client.getPlayerOptions();
		if (options == null)
		{
			return false;
		}
		for (String option : options)
		{
			if (option == null)
			{
				continue;
			}
			String plain = Text.removeTags(option).trim();
			if (plain.equalsIgnoreCase("Attack") || plain.equalsIgnoreCase("Fight"))
			{
				return true;
			}
		}
		return false;
	}

	/** Everyone back to their real spot immediately and forget what the last tick found. Client thread. */
	private void resetTickState()
	{
		if (moving > 0)
		{
			resets++;
		}
		if (probe != null)
		{
			probe.enabled = false;
		}
		if (levelFilter != null)
		{
			levelFilter.enabled = false;
		}
		if (idleSitter != null)
		{
			// Off, unsafe or logged out: everyone stands in their own pose again.
			idleSitter.standAll();
		}
		offsets.snapAllToZero();
		stacks.clear();
		planner.clear();
		stillness.clear();
		gate = client.getGameState() == GameState.LOGGED_IN ? gate : Snapshot.Gate.NOT_LOGGED_IN;
		nearby = 0;
		still = 0;
		aboard = 0;
		stackedTiles = 0;
		moving = 0;
		skippedIds = 0;
		unseen = 0;
		nearestTile = null;
		yourShape = null;
	}

	/**
	 * Client thread. The world around crowded tiles: the main world's, or a boat's for tiles on
	 * its deck. A collision map is only read if a tile on it needs it.
	 */
	/** How far clear of a fire's tile anyone is drawn, in local units. */
	static final int FIRE_CLEARANCE = 20;

	private CrowdPlanner.Surroundings surroundings(WorldView wv)
	{
		return new CrowdPlanner.Surroundings()
		{
			private final Map<Integer, CollisionTerrain> collision = new HashMap<>();

			private WorldView world(long tile)
			{
				int id = StackRegistry.worldViewOf(StackRegistry.plane(tile));
				return id == WorldView.TOPLEVEL ? wv : client.getWorldView(id);
			}

			private CollisionTerrain collision(long tile)
			{
				return collision.computeIfAbsent(StackRegistry.worldViewOf(StackRegistry.plane(tile)), id ->
				{
					WorldView world = world(tile);
					return world == null ? new CollisionTerrain(new int[4][][]) : terrain(world);
				});
			}

			/** Which tiles have a fire on them, looked up once a tick. */
			private final Map<Long, Boolean> fireAt = new HashMap<>();

			private boolean fireOn(WorldView world, int plane, int sceneX, int sceneY)
			{
				long key = ((long) world.getId() << 44) | ((long) (plane & 0xF) << 40) | ((long) (sceneX & 0xFFFFF) << 20) | (sceneY & 0xFFFFF);
				return fireAt.computeIfAbsent(key, k -> hasFire(world, plane, sceneX, sceneY));
			}

			@Override
			public boolean canStand(long tile, int dx, int dz)
			{
				int x = StackRegistry.sceneX(tile) * 128 + 64;
				int z = StackRegistry.sceneY(tile) * 128 + 64;
				int plane = StackRegistry.planeOf(StackRegistry.plane(tile));
				if (!collision(tile).canStand(plane, x, z, x + dx, z + dz))
				{
					return false;
				}
				// Never drawn standing in a fire. Some campfires, like the Forester's Campfire at the
				// Grand Exchange, can be walked over, and a crowd round one was spread right on top
				// of it, hiding the very fire they were gathered at. A little to spare all round, as
				// a body is wider than its feet.
				WorldView world = world(tile);
				if (world == null)
				{
					return true;
				}
				int px = x + dx;
				int pz = z + dz;
				for (int cx : new int[]{px - FIRE_CLEARANCE, px + FIRE_CLEARANCE})
				{
					for (int cz : new int[]{pz - FIRE_CLEARANCE, pz + FIRE_CLEARANCE})
					{
						if (cx >= 0 && cz >= 0 && fireOn(world, plane, cx >> 7, cz >> 7))
						{
							return false;
						}
					}
				}
				return true;
			}

			@Override
			public boolean facesObstacle(long tile, double angle)
			{
				return collision(tile).facesObstacle(StackRegistry.planeOf(StackRegistry.plane(tile)), StackRegistry.sceneX(tile), StackRegistry.sceneY(tile), angle);
			}

			@Override
			public boolean isCounter(long tile, double angle)
			{
				return collision(tile).isCounter(StackRegistry.planeOf(StackRegistry.plane(tile)), StackRegistry.sceneX(tile), StackRegistry.sceneY(tile), angle);
			}

			@Override
			public List<int[]> firesNear(long tile)
			{
				List<int[]> out = new ArrayList<>(1);
				WorldView world = world(tile);
				if (world == null)
				{
					return out;
				}
				for (int east = -1; east <= 1; east++)
				{
					for (int north = -1; north <= 1; north++)
					{
						if (hasFire(world, StackRegistry.planeOf(StackRegistry.plane(tile)), StackRegistry.sceneX(tile) + east, StackRegistry.sceneY(tile) + north))
						{
							out.add(new int[]{east, north});
						}
					}
				}
				return out;
			}

			@Override
			public boolean facesFire(long tile, double angle)
			{
				WorldView world = world(tile);
				return world != null && PersonalSpacePlugin.this.facesFire(world, StackRegistry.planeOf(StackRegistry.plane(tile)), StackRegistry.sceneX(tile), StackRegistry.sceneY(tile), angle);
			}
		};
	}

	/**
	 * Plain words for the shape you are standing in, for the line under the sidebar's title, or null
	 * when your own tile isn't being spread. It also says why people are close when something other
	 * than the slider decided that, which is the question the sidebar can't otherwise answer.
	 */
	private static String yourShapeReport(CrowdPlanner.Plan plan, Player local, int slider, boolean autoSpace)
	{
		LocalPoint lp = local.getLocalLocation();
		WorldPoint wp = local.getWorldLocation();
		if (lp == null || wp == null)
		{
			return null;
		}
		int layer = StackRegistry.layer(local.getWorldView() == null ? WorldView.TOPLEVEL : local.getWorldView().getId(), wp.getPlane());
		CrowdPlanner.TileReport yours = plan.tiles.get(StackRegistry.key(layer, lp.getSceneX(), lp.getSceneY()));
		if (yours == null)
		{
			return null;
		}
		return yourTileLine(yours.shape, autoSpace && yours.spacing < slider);
	}

	/** The report's line about your tile, for a tile of this shape; {@code keptClose} if Auto spacing closed it up. */
	static String yourTileLine(String shape, boolean keptClose)
	{
		String what;
		if (shape.startsWith("counter row"))
		{
			what = "a row along the counter or wall";
		}
		else if (shape.startsWith("line"))
		{
			what = "a line";
		}
		else if (shape.contains("fire"))
		{
			what = "a ring round the fire";
		}
		else if (shape.startsWith(CrowdPlanner.ROUND_OBJECT))
		{
			what = "a crowd round what you're facing";
		}
		else if (shape.startsWith("curved row"))
		{
			what = "a curve round what you're facing";
		}
		else
		{
			what = "a ring";
		}
		String why = "";
		if (shape.contains("squeezed"))
		{
			why = ", squeezed for room";
		}
		else if (keptClose)
		{
			why = ", kept close by Auto spacing";
		}
		return "You're in " + what + why;
	}

	/** What was decided for the spread tile nearest to you, for the report; null if none is near. */
	private static String nearestTileReport(CrowdPlanner.Plan plan, Player local)
	{
		LocalPoint lp = local.getLocalLocation();
		WorldPoint wp = local.getWorldLocation();
		if (lp == null || wp == null)
		{
			return null;
		}
		int layer = StackRegistry.layer(local.getWorldView() == null ? WorldView.TOPLEVEL : local.getWorldView().getId(), wp.getPlane());
		Long nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (long tile : plan.tiles.keySet())
		{
			if (StackRegistry.plane(tile) != layer)
			{
				continue;
			}
			int distance = Math.max(Math.abs(StackRegistry.sceneX(tile) - lp.getSceneX()),
				Math.abs(StackRegistry.sceneY(tile) - lp.getSceneY()));
			if (distance < nearestDistance || (distance == nearestDistance && tile < nearest))
			{
				nearest = tile;
				nearestDistance = distance;
			}
		}
		return nearest == null ? null : plan.tiles.get(nearest) + ", " + nearestDistance + " tiles from you";
	}

	/** Client thread. True if the tile a row is facing has a fire on it. */
	private boolean facesFire(WorldView wv, int plane, int sceneX, int sceneY, double angle)
	{
		return hasFire(wv, plane, sceneX + (int) Math.round(-Math.sin(angle)), sceneY + (int) Math.round(-Math.cos(angle)));
	}

	/** Client thread. True if this scene tile has a fire on it. */
	private boolean hasFire(WorldView wv, int plane, int x, int y)
	{
		Scene scene = wv.getScene();
		if (scene == null)
		{
			return false;
		}
		Tile[][][] tiles = scene.getTiles();
		if (tiles == null || plane < 0 || plane >= tiles.length || x < 0 || x >= tiles[plane].length
			|| y < 0 || y >= tiles[plane][x].length || tiles[plane][x][y] == null)
		{
			return false;
		}
		for (GameObject object : tiles[plane][x][y].getGameObjects())
		{
			if (object == null)
			{
				continue;
			}
			ObjectComposition def = client.getObjectDefinition(object.getId());
			if (def != null && def.getImpostorIds() != null)
			{
				def = def.getImpostor();
			}
			if (def != null && StackSpreader.isFireName(def.getName()))
			{
				return true;
			}
		}
		return false;
	}

	/** The game's walkability map for the current area, so nobody is drawn inside a booth or wall. */
	private static CollisionTerrain terrain(WorldView wv)
	{
		CollisionData[] maps = wv.getCollisionMaps();
		int[][][] flags = new int[4][][];
		if (maps != null)
		{
			for (int plane = 0; plane < Math.min(4, maps.length); plane++)
			{
				flags[plane] = maps[plane] == null ? null : maps[plane].getFlags();
			}
		}
		return new CollisionTerrain(flags);
	}

	private static int countPlayers(WorldView wv)
	{
		int n = 0;
		for (Player p : wv.players())
		{
			if (p != null)
			{
				n++;
			}
		}
		return n;
	}

	// ---- sidebar -----------------------------------------------------------------------

	/** Client thread. Capture the current state and hand it to the sidebar. */
	private void pushSnapshot(long now)
	{
		PersonalSpacePanel p = panel;
		if (p == null)
		{
			return;
		}

		Snapshot s = new Snapshot();
		s.active = config.active();
		s.arrangement = config.arrangement();
		s.mode = config.mode();
		s.spacing = config.spacing();
		s.maxStack = config.maxStack();
		s.includeLocal = config.includeLocalPlayer();
		s.drawMeInFront = config.drawMeInFront();
		s.depthTest = config.depthBetweenPlayers();
		s.walkWhileBusy = config.walkWhileBusy();
		s.idleSit = config.idlePlayersSit();
		s.sitting = idleSitter == null ? 0 : idleSitter.sitting();
		s.clickPast = config.clickPastMoved();
		s.names = config.namesFollowPlayers();
		s.hover = config.hoverShowsWho();
		s.hoverArrow = config.hoverArrow();
		s.hideBelow = config.hideBelowLevel();
		s.hideChat = config.hideTheirChat();
		s.chatRange = config.hideChatFurtherThan();
		s.alchers = config.otherAlchers();
		s.alchersRestyled = alchStyler == null ? 0 : alchStyler.restyled;
		s.smallGroupsClose = config.smallGroupsClose();
		s.pauseInCombat = config.pauseInCombat();
		s.pose = config.pose();
		s.testOffset = config.testOffset();

		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		s.gate = loggedIn ? gate : Snapshot.Gate.NOT_LOGGED_IN;

		DrawCallbacks current = client.getDrawCallbacks();
		SpreadingDrawCallbacks w = wrapper;
		s.hooked = w != null && current == w;
		s.renderer = current == null ? null : rendererName(s.hooked ? w.getDelegate() : current);
		Plugin hd = findPlugin("HdPlugin");
		s.hdEnabled = hd != null && pluginManager.isPluginEnabled(hd);

		double seconds = lastPanelNanos == 0 ? 0 : (now - lastPanelNanos) / 1_000_000_000.0;
		boolean ratesKnown = w != null && w == countedWrapper && seconds > 0;
		if (ratesKnown)
		{
			s.playerDrawsPerSec = perSecond(w.playerDraws - lastPlayerDraws, seconds);
			s.nudgedDrawsPerSec = perSecond(w.nudgedDraws - lastNudgedDraws, seconds);
			s.revealedDrawsPerSec = perSecond(w.revealedDraws - lastRevealedDraws, seconds);
			s.sceneMismatchesPerSec = perSecond(w.sceneMismatches - lastSceneMismatches, seconds);
		}
		s.resets = resets;
		s.driftFrames = offsets.driftFrames;
		s.wallHurries = offsets.wallHurries;
		s.wallHolds = offsets.wallHolds;
		s.wallFollows = offsets.wallFollows;
		s.wallShrinks = offsets.wallShrinks;
		s.insideYouHidden = planner.insideYouHidden;
		s.spotLosses = spotLosses;
		s.longestHidden = hideLog.longest(offsets.frame(), client.getGameCycle());
		s.flickering = hideLog.flickering(offsets.frame(), client.getGameCycle());
		s.sliding = hideLog.sliding(client.getGameCycle());
		s.waitBreaks = waitBreaks;
		s.waitTimeouts = waitTimeouts;
		s.waitSkipped = waitSkipped;
		s.planDips = planDips;
		s.shimInstalls = shimInstalls;
		if (w != null)
		{
			s.playersInOtherCalls = w.playersInOtherCalls;
			s.offThreadDraws = w.offThreadDraws;
			s.revealErrors = w.revealErrors;
			s.walkDraws = w.walkDraws;
			s.orderedDraws = w.orderedDraws;
			s.depthDraws = w.depthDraws;
			s.depthNoSpacer = w.depthNoSpacer;
			s.keptDips = w.keptDips;
			s.probeBlackouts = w.probeBlackouts;
			s.droppedUndrawn = w.droppedUndrawn;
			s.blinkNoMiddle = w.blinkNoMiddle;
			s.blinkUnconfirmed = w.blinkUnconfirmed;
			s.blinkOthersHid = w.blinkOthersHid;
			s.blinkMoved = w.blinkMoved;
			s.blinkOther = w.blinkOther;
			s.keptWithoutModel = w.keptWithoutModel;
			s.skippedUnconfirmed = w.skippedUnconfirmed;
			s.skippedOthersHid = w.skippedOthersHid;
			s.skippedMoved = w.skippedMoved;
			s.fireBlackouts = w.fireBlackouts;
			s.fireUnconfirmed = w.fireUnconfirmed;
			s.middleKeptSteady = w.middleKeptSteady;
			s.refusedDrawn = w.refusedDrawn;
			s.aloneRefusedDrawn = w.aloneRefusedDrawn;
			s.movingRefusedDrawn = w.movingRefusedDrawn;
			s.walksLegsStill = w.walksLegsStill;
			s.walksLegsStillBusy = w.walksLegsStillBusy;
			s.legsStillBy = w.legsStillBy.clone();
			s.legsStillAnims = topAnimations(w.legsStillAnims, client);
			s.legsMatched = w.legsMatched;
			s.movingBusyWalks = w.movingBusyWalks;
			s.swapsCameraMoving = w.swapsCameraMoving;
			s.swapsCameraStill = w.swapsCameraStill;
			s.stillSwapsMoved = w.stillSwapsMoved;
			s.stillSwapsOther = w.stillSwapsOther;
			s.stillSwapsWalking = w.stillSwapsWalking;
			s.stillSwapsStanding = w.stillSwapsStanding;
			s.swapsBack = w.swapsBack;
			s.passMissedFrames = w.passMissedFrames;
			s.hiddenInYourWay = w.hiddenInYourWay;
			s.walkSkippedBusy = w.walkSkippedBusy;
			s.walkBusy = w.walkBusy;
			s.busyWalksOff = busyWalksOff;
			s.slideBusy = w.slideBusy;
			s.slideWalkingOff = w.slideWalkingOff;
			s.slideOther = w.slideOther;
			s.slideBusyArriving = w.slideBusyArriving;
			s.slideBusyBetween = w.slideBusyBetween;
			s.slideBusyToMiddle = w.slideBusyToMiddle;
			StringBuilder top = new StringBuilder();
			w.busyAnimations.entrySet().stream()
				.sorted((a, b) -> Long.compare(b.getValue(), a.getValue()))
				.limit(4)
				.forEach(e -> top.append(top.length() == 0 ? "" : ", ").append(e.getKey()).append(" x").append(e.getValue()));
			s.busyAnimations = top.toString();
			s.walkSkippedNoAnimation = w.walkSkippedNoAnimation;
		}
		countedWrapper = w;
		if (w != null)
		{
			lastPlayerDraws = w.playerDraws;
			lastNudgedDraws = w.nudgedDraws;
			lastRevealedDraws = w.revealedDraws;
			lastSceneMismatches = w.sceneMismatches;
		}
		lastPanelNanos = now;

		StackProbe pr = probe;
		if (pr != null)
		{
			s.probeHeld = pr.heldTotal;
			s.probeGaveUp = pr.gaveUpTotal;
			s.probeBackOffs = pr.backOffs;
		}
		s.shapeChanges = planner.shapeChanges();
		s.spotMoves = planner.spotMoves();
		s.unseenStacked = unseen;
		s.nearestTile = nearestTile;
		s.yourShape = yourShape;
		s.nearby = nearby;
		s.aboard = aboard;
		s.still = still;
		s.stackedTiles = stackedTiles;
		s.moving = moving;
		s.skippedIds = skippedIds;

		boolean effectShouldRun = s.active && loggedIn && s.gate == Snapshot.Gate.SAFE && s.hooked && ratesKnown;
		noDrawsStreak = effectShouldRun && s.playerDrawsPerSec == 0 ? noDrawsStreak + 1 : 0;
		nothingMovedStreak = effectShouldRun && s.moving > 0 && s.nudgedDrawsPerSec + s.revealedDrawsPerSec == 0 ? nothingMovedStreak + 1 : 0;
		s.noPlayerDrawsSustained = noDrawsStreak >= SUSTAINED_REFRESHES;
		s.nothingMovedSustained = nothingMovedStreak >= SUSTAINED_REFRESHES;

		SwingUtilities.invokeLater(() -> p.update(s));
	}

	private static int perSecond(long count, double seconds)
	{
		return count <= 0 ? 0 : (int) Math.round(count / seconds);
	}

	/** RuneLite's GPU plugin, or 117 HD: found by class name, as neither can be referred to directly. */
	private Plugin findPlugin(String simpleName)
	{
		for (Plugin p : pluginManager.getPlugins())
		{
			if (simpleName.equals(p.getClass().getSimpleName()))
			{
				return p;
			}
		}
		return null;
	}

	/**
	 * The sidebar's Turn on GPU button: switches on RuneLite's GPU plugin, just as ticking it in the
	 * plugin list does. Swing thread. Never over 117 HD: the button isn't offered while it's on.
	 */
	private void turnOnGpu()
	{
		Plugin hd = findPlugin("HdPlugin");
		Plugin gpu = findPlugin("GpuPlugin");
		if (gpu == null || (hd != null && pluginManager.isPluginEnabled(hd)) || pluginManager.isPluginActive(gpu))
		{
			return;
		}
		pluginManager.setPluginEnabled(gpu, true);
		try
		{
			pluginManager.startPlugin(gpu);
		}
		catch (PluginInstantiationException e)
		{
			log.warn("Couldn't turn on the GPU plugin", e);
		}
	}

	private static String rendererName(DrawCallbacks callbacks)
	{
		String name = callbacks.getClass().getSimpleName();
		if (name.equals("GpuPlugin"))
		{
			return "GPU plugin";
		}
		if (name.toLowerCase().contains("hd") || callbacks.getClass().getName().startsWith("rs117."))
		{
			return "117 HD";
		}
		return name;
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Remembers whether each crowded tile is laid out as a row (everyone facing the same thing) or a
 * crowd, and which way a row faces, so the layout doesn't change just because someone turns.
 *
 * <p>A player casting spells or skilling keeps turning towards what they're working on. If the tile's
 * shape were worked out from scratch every tick, each turn could flip the tile between a row and a
 * crowd, or swing the row round, and everyone on it would get new spots. So a row is kept for as
 * long as the same players are on the tile. A crowd can still become a row once everyone faces the
 * same way: people walking up to a bank booth only turn to face it after they arrive. That change
 * only goes one way, so it can happen at most once. Someone leaving (or briefly dropping out and
 * coming back) never changes the shape; only a genuinely new arrival does. Even then a row stays a
 * row, facing the same way, unless the facings have clearly changed.
 *
 * <p>Client thread only. Knows nothing about RuneLite; unit tested.
 */
final class ShapeMemory
{
	/** A row's direction is only updated if it has turned by more than this. */
	static final double KEEP_ANGLE = Math.toRadians(30);

	static final class Shape
	{
		final boolean row;
		/** Direction a row faces, radians in game convention; 0 for a crowd. */
		final double angle;

		Shape(boolean row, double angle)
		{
			this.row = row;
			this.angle = angle;
		}
	}

	private static final class Remembered
	{
		final List<Integer> ids;
		final boolean smart;
		final Shape shape;

		Remembered(List<Integer> ids, boolean smart, Shape shape)
		{
			this.ids = ids;
			this.smart = smart;
			this.shape = shape;
		}
	}

	private Map<Long, Remembered> previous = new HashMap<>();
	private Map<Long, Remembered> current = new HashMap<>();

	/** Diagnostics: how many times a tile's shape actually changed. */
	long changes;

	/** Call before deciding this tick's shapes. */
	void startTick()
	{
		previous = current;
		current = new HashMap<>();
	}

	/**
	 * The shape for a tile this tick.
	 *
	 * @param group everyone standing still on the tile, with their facings
	 * @param smart whether rows are allowed at all (the Smart arrangement)
	 */
	Shape decide(long tile, List<StackSpreader.Entry> group, boolean smart)
	{
		List<Integer> ids = new ArrayList<>(group.size());
		for (StackSpreader.Entry e : group)
		{
			ids.add(e.id);
		}
		Collections.sort(ids);

		Remembered old = previous.get(tile);
		if (old != null && old.smart == smart && old.ids.containsAll(ids))
		{
			// Same people, or some of them stepped away: keep the shape, and keep remembering
			// everyone so someone coming straight back doesn't count as a newcomer. The one change
			// allowed is a crowd that has since turned to face the same thing becoming a row.
			Double facing = smart && !old.shape.row && group.size() >= 2 ? StackSpreader.sharedFacing(group, StackSpreader.SAME_FACING) : null;
			if (facing == null)
			{
				current.put(tile, old);
				return old.shape;
			}
			Remembered promoted = new Remembered(old.ids, smart, new Shape(true, facing));
			changes++;
			current.put(tile, promoted);
			return promoted.shape;
		}
		Shape shape;
		if (!smart)
		{
			shape = new Shape(false, 0);
		}
		else
		{
			boolean wasRow = old != null && old.smart && old.shape.row;
			Double facing = StackSpreader.sharedFacing(group,
				wasRow ? StackSpreader.STILL_SAME_FACING : StackSpreader.SAME_FACING);
			if (facing == null)
			{
				shape = new Shape(false, 0);
			}
			else if (wasRow && angleBetween(facing, old.shape.angle) < KEEP_ANGLE)
			{
				shape = old.shape;
			}
			else
			{
				shape = new Shape(true, facing);
			}
		}
		if (old != null && (old.shape.row != shape.row || old.shape.angle != shape.angle))
		{
			changes++;
		}
		List<Integer> remembered = ids;
		if (old != null && old.smart == smart)
		{
			// Keep remembering people who stepped away, so their return isn't a new arrival.
			java.util.Set<Integer> union = new java.util.TreeSet<>(old.ids);
			union.addAll(ids);
			remembered = new ArrayList<>(union);
		}
		current.put(tile, new Remembered(remembered, smart, shape));
		return shape;
	}

	void clear()
	{
		previous.clear();
		current.clear();
	}

	static double angleBetween(double a, double b)
	{
		double d = Math.abs(a - b) % (2 * Math.PI);
		return d > Math.PI ? 2 * Math.PI - d : d;
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.ToIntFunction;

/**
 * Remembers which spot each player has on each crowded tile, so a crowd doesn't reshuffle every
 * time someone arrives or leaves.
 *
 * <p>Spots are numbered from best to worst: 0 is the best (front and centre), higher numbers are
 * further out or further back. The rules:
 * <ul>
 * <li>Anyone who already has a spot keeps it.</li>
 * <li>A newcomer takes the best free spot.</li>
 * <li>When someone leaves, their spot is held for {@link #HOLD_TICKS} ticks. If they come back in
 * that time they get it back; nobody else takes it.</li>
 * <li>Once a hold runs out, the player in the worst spot moves into the gap. Only that one player
 * moves, so the front row stays put and the back fills forward.</li>
 * </ul>
 *
 * <p>Client thread only. Knows nothing about RuneLite; unit tested.
 */
final class SlotBook
{
	/** How long a spot is kept for someone who just left: 8 ticks, about 5 seconds. */
	static final int HOLD_TICKS = 8;

	private static final class Tile
	{
		final Map<Integer, Integer> slotOf = new HashMap<>();
		final Map<Integer, Integer> occupant = new HashMap<>();
		final Map<Integer, Integer> heldFor = new HashMap<>();
		final Map<Integer, Integer> heldUntil = new HashMap<>();

		boolean held(int slot, int tick)
		{
			Integer until = heldUntil.get(slot);
			return until != null && until >= tick;
		}

		boolean anyHeld(int tick)
		{
			for (int until : heldUntil.values())
			{
				if (until >= tick)
				{
					return true;
				}
			}
			return false;
		}

		void vacate(int id, int tick, boolean hold)
		{
			Integer slot = slotOf.remove(id);
			if (slot == null)
			{
				return;
			}
			occupant.remove(slot);
			if (hold)
			{
				heldFor.put(slot, id);
				heldUntil.put(slot, tick + HOLD_TICKS);
			}
		}

		void assign(int id, int slot)
		{
			slotOf.put(id, slot);
			occupant.put(slot, id);
			heldFor.remove(slot);
			heldUntil.remove(slot);
		}
	}

	private final Map<Long, Tile> tiles = new HashMap<>();

	/** Whether this spot is being held for you: the only hold a newcomer doesn't walk into. */
	private boolean heldForYou(Tile t, int slot, int tick)
	{
		return t.held(slot, tick) && yourId >= 0 && Integer.valueOf(yourId).equals(t.heldFor.get(slot));
	}

	/** Diagnostics: how many times a player who already had a spot was given a different one. */
	long moves;

	/**
	 * Your own player's id when your character may be moved, else -1. You get the best spot on your
	 * tile (the front, where what you're doing looks right); whoever had it swaps with you, once.
	 */
	int localId = -1;

	/** Your player id whether or not your character is moved or here now: a spot held for you is never given away. */
	int yourId = -1;



	/**
	 * For the tile you are on, the spots standing between you and the camera. Nobody is put in one
	 * while there is anywhere else, and anyone found in one steps to a free spot if there is one.
	 */
	Map<Long, Set<Integer>> keepClear = new HashMap<>();

	/**
	 * For tiles near you, how many spots at the end of their list are spare: past the players-per-
	 * tile limit, and only for someone stepping out from between you and the camera when every
	 * other spot is taken. In a pile, nobody had anywhere to step to.
	 */
	Map<Long, Integer> spare = new HashMap<>();

	/**
	 * People busy with something (alching, an emote, smithing). When a tile has more people than
	 * spots, they are the ones left without one, rather than whoever came last.
	 */
	Set<Integer> busy = new HashSet<>();

	/**
	 * For the tile you're on, when just you and one other are about to be given spots there: the
	 * spot to take yourself, the one on the camera's side. Take the other and the one left, with
	 * the camera off to their side of you, stood between you and it, and was sent round to your
	 * far side instead of beside you. Chosen once, when the pair forms, and kept while you stay:
	 * turning the camera afterwards doesn't swap you.
	 */
	Map<Long, Integer> pairSideForYou = new HashMap<>();

	/**
	 * For the tile you're on, beside a fire: the spot nearest it, which is yours whoever else is
	 * there. Tending the fire, you were drawn further off than someone just standing about by it.
	 */
	Map<Long, Integer> fireSideForYou = new HashMap<>();
	private long yourPickTile = Long.MIN_VALUE;
	private int yourPick;

	/**
	 * This tick, people who would have stood between you and the camera with nowhere else on
	 * their tile to go: they wait without a spot, like anyone past the players-per-tile limit.
	 */
	final Set<Integer> hiddenForYou = new HashSet<>();

	/**
	 * Whether you've stood still long enough for people in front of you to step aside. Until then
	 * nobody is moved for you, but newcomers and gap-filling still keep out of those spots.
	 */
	boolean stepAside = true;

	/**
	 * For those tiles, the order to try free spots in when someone must go elsewhere: nearest the
	 * tile's middle first, so they step a little back near their own booth rather than along the
	 * counter to the far end of it.
	 */
	Map<Long, List<Integer>> nearestFirst = new HashMap<>();

	/**
	 * People who stepped aside for you, and the spots they stepped out of. They stay put while that
	 * doesn't change: filling a gap next tick would move them a second time, since stepping aside
	 * picks the free spot nearest their booth and gap-filling the best spot on the tile.
	 */
	private final Set<Integer> asideForYou = new HashSet<>();

	/**
	 * Given a tile and a spot on it, the spots on that tile that would stand between someone there
	 * and the camera; empty when the camera isn't known. Whoever you swap places with is sent
	 * straight to a spot out of your way, rather than to yours and then aside again.
	 */
	java.util.function.BiFunction<Long, Integer, Set<Integer>> inFrontOf = (tile, spot) -> Collections.emptySet();
	/** Which way the camera looks, as the planner rounds it. Whoever stepped aside may move again when it changes. */
	int viewKey = -1;
	private int asideView = -2;
	private long asideTile = Long.MIN_VALUE;

	/**
	 * How long you must have been given a spot on a tile before you take the front one: none. You
	 * go straight to it rather than start off to the side and shuffle in a few seconds later.
	 * Walking past never counts: nobody is given a spot until they have stood still for two ticks.
	 */
	static final int LOCAL_SWAP_DELAY = 0;

	private long localTile = Long.MIN_VALUE;
	private int localSince;

	/**
	 * Work out this tick's spots.
	 *
	 * @param present  for each tile, the players standing there who may be moved
	 * @param capacityOf how many spots each tile has
	 * @param tick     this tick's number
	 * @return for each tile, each player's spot; players with no spot (the tile is full) are left out
	 */
	Map<Long, Map<Integer, Integer>> update(Map<Long, List<Integer>> present, ToIntFunction<Long> capacityOf, int tick)
	{
		boolean movedYou = false;
		hiddenForYou.clear();
		if (viewKey != asideView || localTile != asideTile)
		{
			asideForYou.clear();
			asideView = viewKey;
			asideTile = localTile;
		}
		// Tiles nobody is on any more: everyone there has left.
		for (Iterator<Map.Entry<Long, Tile>> it = tiles.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Long, Tile> e = it.next();
			if (present.containsKey(e.getKey()))
			{
				continue;
			}
			Tile t = e.getValue();
			for (int id : new ArrayList<>(t.slotOf.keySet()))
			{
				t.vacate(id, tick, true);
			}
			if (!t.anyHeld(tick))
			{
				it.remove();
			}
		}

		boolean sawLocal = false;
		Map<Long, Map<Integer, Integer>> out = new HashMap<>();
		for (Map.Entry<Long, List<Integer>> e : present.entrySet())
		{
			Tile t = tiles.computeIfAbsent(e.getKey(), k -> new Tile());
			int all = capacityOf.applyAsInt(e.getKey());
			int capacity = all - Math.min(all, spare.getOrDefault(e.getKey(), 0));
			List<Integer> ids = new ArrayList<>(e.getValue());
			Collections.sort(ids);
			Set<Integer> here = new HashSet<>(ids);

			// People who left.
			for (int id : new ArrayList<>(t.slotOf.keySet()))
			{
				if (!here.contains(id))
				{
					t.vacate(id, tick, true);
				}
			}
			// Spots that no longer exist because the tile got smaller.
			for (int id : new ArrayList<>(t.slotOf.keySet()))
			{
				if (t.slotOf.get(id) >= all)
				{
					t.vacate(id, tick, false);
				}
			}
			// Forget holds that have run out or point past the end.
			t.heldUntil.entrySet().removeIf(h -> h.getValue() < tick || h.getKey() >= all);
			t.heldFor.keySet().retainAll(t.heldUntil.keySet());

			// People coming back to a spot held for them.
			for (int id : ids)
			{
				if (t.slotOf.containsKey(id))
				{
					continue;
				}
				for (Map.Entry<Integer, Integer> h : new ArrayList<>(t.heldFor.entrySet()))
				{
					if (h.getValue() == id && !t.occupant.containsKey(h.getKey()))
					{
						t.assign(id, h.getKey());
						break;
					}
				}
			}
			// Newcomers take the best free spot that isn't being held. You go first, so walking in
			// beside someone settles both of you in one step: without that, whoever has the lower
			// player id takes the front spot and you swap with them a few ticks later, which looks
			// like the pair shuffling about once for no reason.
			List<Integer> arriving = new ArrayList<>(ids);
			// Those not busy with anything first, so when there aren't spots for everyone arriving
			// the ones left waiting are the busy ones (a stable sort: otherwise in the order given).
			arriving.sort(Comparator.comparingInt(id -> busy.contains(id) ? 1 : 0));
			if (arriving.remove((Integer) localId))
			{
				arriving.add(0, localId);
			}
			Integer atFire = fireSideForYou.get(e.getKey());
			int yours = atFire != null && atFire < capacity ? atFire : yourPickTile == e.getKey() ? yourPick : 0;
			Set<Integer> inFront = keepClear.getOrDefault(e.getKey(), Collections.emptySet());
			for (int id : arriving)
			{
				if (t.slotOf.containsKey(id))
				{
					continue;
				}
				if (id == localId && yourPickTile != e.getKey())
				{
					Integer side = atFire != null ? atFire : pairSideForYou.get(e.getKey());
					yourPick = side != null && side < capacity ? side : 0;
					yourPickTile = e.getKey();
					yours = yourPick;
				}
				if (id == localId && yours < capacity && !t.occupant.containsKey(yours) && !t.held(yours, tick))
				{
					t.assign(id, yours);
					movedYou = true;
					continue;
				}
				// The best free spot out of your way, or, when there is none, any free spot. A spot
				// held for someone who stepped away counts as free to a newcomer: kept for them, it
				// had a newcomer stand behind (at a bank) for five seconds and then step forward
				// into it, when walking straight into the gap is what anyone would do. A spot held
				// for you is never taken.
				int spot = -1;
				for (int s : order(e.getKey(), capacity))
				{
					if (spot < 0 && s < capacity && !t.occupant.containsKey(s) && !heldForYou(t, s, tick) && !inFront.contains(s))
					{
						spot = s;
					}
				}
				// Once you've settled, someone arriving at a full tile waits rather than stand
				// between you and the camera.
				for (int s = 0; s < capacity && spot < 0; s++)
				{
					spot = !t.occupant.containsKey(s) && !heldForYou(t, s, tick) && !(stepAside && inFront.contains(s)) ? s : -1;
				}
				if (spot >= 0)
				{
					t.assign(id, spot);
					movedYou |= id == localId;
				}
			}
			// You always get a spot. On a full tile you used to be left standing in the middle, with
			// everyone in a ring round you, until someone left. Whoever is busy with something gives
			// theirs up first, else whoever has the spot furthest back.
			if (localId >= 0 && here.contains(localId) && !t.slotOf.containsKey(localId) && !t.occupant.isEmpty())
			{
				int from = -1;
				for (Map.Entry<Integer, Integer> o : t.occupant.entrySet())
				{
					if (o.getKey() >= capacity)
					{
						continue;
					}
					boolean better = from < 0
						|| (busy.contains(o.getValue()) && !busy.contains(t.occupant.get(from)))
						|| (busy.contains(o.getValue()) == busy.contains(t.occupant.get(from)) && o.getKey() > from);
					if (better)
					{
						from = o.getKey();
					}
				}
				if (from >= 0)
				{
					t.vacate(t.occupant.get(from), tick, false);
					t.assign(localId, from);
					movedYou = true;
					moves++;
				}
			}
			// More people than spots: those who aren't busy with anything (alching, an emote) come
			// first in the queue for a free spot, so the ones left waiting are the busy ones. But
			// nobody is turned out of a spot they already have for a newcomer who isn't busy:
			// someone busy can't walk without their spell being cut short, so they slid off to the
			// middle of the tile mid-cast, which at a counter is behind the row.
			// You get the best spot going the moment you have one: a free one if there is one, else
			// whoever has the front spot takes yours. A front spot being held for someone who stepped
			// away is yours too: you'd otherwise stand waiting for their hold to run out, and if they
			// come back they take the next free spot like anyone arriving.
			Integer mine = t.slotOf.get(localId);
			if (mine != null)
			{
				sawLocal = true;
				if (localTile != e.getKey())
				{
					localTile = e.getKey();
					localSince = tick;
				}
				int free = -1;
				for (int s = 0; s < mine; s++)
				{
					if (free < 0 && !t.occupant.containsKey(s) && !t.held(s, tick))
					{
						free = s;
					}
				}
				// Your spot is only yours while it exists: picked when the tile had more spots, it
				// pointed past the end of a smaller one, and the planner failed reading it.
				if (mine != yours && yours < capacity && tick - localSince >= LOCAL_SWAP_DELAY)
				{
					// Straight to your spot in one step. Whoever was there takes the best free spot if
					// there is one, else yours, so neither of you is moved again next tick.
					Integer other = t.occupant.get(yours);
					t.vacate(localId, tick, false);
					if (other != null)
					{
						t.vacate(other, tick, false);
						int to = free >= 0 && free != yours ? free : mine;
						Set<Integer> wouldHide = inFrontOf.apply(e.getKey(), yours);
						if (wouldHide.contains(to))
						{
							for (int s : order(e.getKey(), capacity))
							{
								if (s < capacity && s != yours && !t.occupant.containsKey(s) && !t.held(s, tick)
									&& !wouldHide.contains(s))
								{
									to = s;
									asideForYou.add(other);
									break;
								}
							}
						}
						t.assign(other, to);
					}
					t.assign(localId, yours);
					movedYou = true;
					moves++;
				}
			}
			// Fill gaps from the back: the player in the worst spot moves into the best free one -
			// never one standing between you and the camera.
			for (int s = 0; s < capacity; s++)
			{
				if (t.occupant.containsKey(s) || t.held(s, tick) || inFront.contains(s))
				{
					continue;
				}
				int worst = -1;
				for (int slot : t.occupant.keySet())
				{
					// Never you. Other people filling a gap is what keeps a crowd tidy, but you notice
					// your own character moving far more than anyone else's, so only arriving and
					// settling the camera somewhere new ever move you.
					if (t.occupant.get(slot) == localId || asideForYou.contains(t.occupant.get(slot)))
					{
						continue;
					}
					if (slot > s && slot > worst)
					{
						worst = slot;
					}
				}
				if (worst < 0)
				{
					break;
				}
				int mover = t.occupant.get(worst);
				t.vacate(mover, tick, false);
				t.assign(mover, s);
				moves++;
			}

			out.put(e.getKey(), new HashMap<>(t.slotOf));
		}

		// Anyone standing between you and the camera steps to a free spot out of the way. Only once
		// you're in your place: on a tick you moved, the spots in front of you are about to change,
		// and people stepped aside for where you were only to step again for where you are. Only a
		// spot nobody has is ever used, so nobody is left without one for your sake; someone with
		// nowhere else to go simply stays.
		for (Map.Entry<Long, Set<Integer>> c : movedYou || !stepAside ? Collections.<Long, Set<Integer>>emptyMap().entrySet() : keepClear.entrySet())
		{
			Tile t = tiles.get(c.getKey());
			if (t == null || !present.containsKey(c.getKey()))
			{
				continue;
			}
			int all = capacityOf.applyAsInt(c.getKey());
			int capacity = all - Math.min(all, spare.getOrDefault(c.getKey(), 0));
			Set<Integer> inFront = c.getValue();
			boolean changed = false;
			// An ordinary free spot if there is one, else a spare one past the players-per-tile limit.
			List<Integer> free = new ArrayList<>();
			for (int to : order(c.getKey(), all))
			{
				if (to < capacity)
				{
					free.add(to);
				}
			}
			for (int to : order(c.getKey(), all))
			{
				if (to >= capacity && to < all)
				{
					free.add(to);
				}
			}
			// Those who aren't busy with anything get the free spots first; whoever is left over
			// waits in the middle rather than stand in front of you. In a pile at an anvil or a
			// packed bank there is nowhere else, and you should be the one people can see.
			List<Integer> blocking = new ArrayList<>(inFront);
			blocking.sort(Comparator.comparingInt(s -> busy.contains(t.occupant.getOrDefault(s, -1)) ? 1 : 0));
			for (int s : blocking)
			{
				Integer who = t.occupant.get(s);
				if (who == null || who == localId)
				{
					continue;
				}
				boolean stepped = false;
				for (int to : free)
				{
					if (!stepped && !t.occupant.containsKey(to) && !t.held(to, tick) && !inFront.contains(to))
					{
						stepped = true;
						t.vacate(who, tick, false);
						t.assign(who, to);
						asideForYou.add(who);
						moves++;
						changed = true;
						break;
					}
				}
				if (!stepped)
				{
					t.vacate(who, tick, false);
					hiddenForYou.add(who);
					moves++;
					changed = true;
				}
			}
			if (changed)
			{
				out.put(c.getKey(), new HashMap<>(t.slotOf));
			}
		}
		if (!sawLocal)
		{
			localTile = Long.MIN_VALUE;
			yourPickTile = Long.MIN_VALUE;
		}
		return out;
	}

	/** The spots of a tile in the order to try them: nearest its middle first where that's known. */
	private List<Integer> order(long tile, int capacity)
	{
		List<Integer> known = nearestFirst.get(tile);
		if (known != null)
		{
			return known;
		}
		List<Integer> plain = new ArrayList<>(capacity);
		for (int s = 0; s < capacity; s++)
		{
			plain.add(s);
		}
		return plain;
	}

	void clear()
	{
		tiles.clear();
	}
}

package com.grant9008.personalspace;

/**
 * Everything the sidebar panel shows, captured at one moment on the client thread and then handed
 * to the Swing thread. A fresh instance is built for every update and never changed afterwards.
 */
final class Snapshot
{
	/** Why the effect is switched off by the safety rules, or {@link #SAFE}. */
	enum Gate
	{
		SAFE("Safe area"),
		NOT_LOGGED_IN("Not logged in"),
		WILDERNESS("In the Wilderness"),
		PVP_AREA("In a PvP area"),
		PVP_WORLD("On a PvP-type world"),
		PVP_ACTIVITY("Players can fight here"),
		IN_COMBAT("You are in combat");

		final String label;

		Gate(String label)
		{
			this.label = label;
		}
	}

	String pluginVersion = PersonalSpacePlugin.VERSION;

	// settings
	boolean active;
	PersonalSpaceConfig.Arrangement arrangement = PersonalSpaceConfig.Arrangement.AUTO;
	PersonalSpaceConfig.Mode mode = PersonalSpaceConfig.Mode.SPREAD;
	int spacing = PersonalSpaceConfig.SPACING_WIDE;
	int maxStack;
	boolean includeLocal;
	boolean drawMeInFront;
	boolean depthTest;
	boolean walkWhileBusy;
	/** Idle players sit, and how many are sat down now. */
	boolean idleSit;
	int sitting;
	boolean clickPast;
	boolean names;
	boolean hover;
	boolean hoverArrow;
	int hideBelow;
	boolean hideChat;
	int chatRange;
	PersonalSpaceConfig.Alchers alchers = PersonalSpaceConfig.Alchers.NORMAL;
	/** Other players' alch casts drawn still or as an emote, this session. */
	long alchersRestyled;
	boolean smallGroupsClose = true;
	boolean pauseInCombat = true;
	PersonalSpaceConfig.Pose pose = PersonalSpaceConfig.Pose.NATURAL;
	/** Plain words for the shape you are standing in right now, for the sidebar; null when you aren't in one. */
	String yourShape;
	/** Players drawn mid-step with their walk animation; total. */
	long walkDraws;
	/** Players and NPCs drawn farthest from the camera first, so whoever is nearer is in front; total. */
	long orderedDraws;
	long depthDraws;
	/** Drawn without depth although they overlapped someone, because no depth spacer could be made; expected 0. */
	long depthNoSpacer;
	long keptDips;
	long probeBlackouts;
	long droppedUndrawn;
	long resets;
	long planDips;
	long shimInstalls;
	long blinkNoMiddle;
	long blinkUnconfirmed;
	long blinkOthersHid;
	long blinkMoved;
	long blinkOther;
	long keptWithoutModel;
	long spotLosses;
	long insideYouHidden;
	long swapsCameraMoving;
	long swapsCameraStill;
	long stillSwapsMoved;
	long stillSwapsOther;
	long stillSwapsWalking;
	long stillSwapsStanding;
	long swapsBack;
	long skippedUnconfirmed;
	long skippedOthersHid;
	long skippedMoved;
	/** Of the probe's blackouts and the unconfirmed stackmates left undrawn, those at a fire; totals. */
	long fireBlackouts;
	long fireUnconfirmed;
	/** Frames someone the game drew in the middle of a tile gave way to whoever is shown there; total. */
	long middleKeptSteady;
	/** Waits for a break in someone's action: ended in a break, ran out, or not started (never pauses); totals. */
	long waitBreaks;
	long waitTimeouts;
	long waitSkipped;
	/** Who went longest undrawn lately and why, or null. */
	String longestHidden;
	/** Who flickered most lately (undrawn for under a second, again and again) and why, or null. */
	String flickering;
	/** Players drawn at their spot although the game had no room for them on their tile; frames, total. */
	long refusedDrawn;
	/** ...of which alone on their tile, not moved at all. */
	long aloneRefusedDrawn;
	/** ...and walking across a full tile (a campfire's). */
	long movingRefusedDrawn;
	/** Walks drawn whose body kept the same shape too long to be walking: all, and of busy people. */
	long walksLegsStill;
	long walksLegsStillBusy;
	long[] legsStillBy = new long[4];
	String legsStillAnims = "";
	/** Who slid most lately (drawn moving with no walk to match), how and how far, or null. */
	String sliding;
	/** Frames someone walking off a spot was drawn with legs keeping pace with their body; total. */
	long legsMatched;
	/** Frames someone walking for real while busy was drawn walking (Walk while busy); total. */
	long movingBusyWalks;
	/** Frames where draws were kept back but the renderer never asked for its opaque pass; should stay 0. */
	long passMissedFrames;
	/** Times someone waiting in the middle of a tile in front of you was left undrawn; total. */
	long hiddenInYourWay;
	/** Moving players drawn without a walk animation because they were busy and busy walks were off; total. */
	long walkSkippedBusy;
	/** Moving players shown walking although busy with an emote or action; total. */
	long walkBusy;
	/** Whether busy walks were switched off because the game reported an animation change from one. */
	boolean busyWalksOff;
	String busyAnimations = "";
	long driftFrames;
	/** Frames someone walking off was kept off a wall: their offset ran out faster, they waited at it, they followed their way round it, or it was cut back at once. */
	long wallHurries;
	long wallHolds;
	long wallFollows;
	long wallShrinks;
	long slideBusy;
	long slideWalkingOff;
	long slideOther;
	long slideBusyArriving;
	long slideBusyBetween;
	long slideBusyToMiddle;
	/** Moving players drawn without a walk animation because it couldn't be loaded; total. */
	long walkSkippedNoAnimation;
	int testOffset;

	// safety
	Gate gate = Gate.NOT_LOGGED_IN;

	// renderer hook
	/** Display name of the renderer we sit in front of, or null when no GPU renderer is running. */
	String renderer;
	/** Whether 117 HD is switched on in the plugin list (running or not), so we don't offer the GPU plugin over it. */
	boolean hdEnabled;
	boolean hooked;
	int playerDrawsPerSec;
	/** Draws of players the game showed, drawn at a ring slot. */
	int nudgedDrawsPerSec;
	/** Draws of stackmates the game hid, drawn by Personal Space. */
	int revealedDrawsPerSec;
	int sceneMismatchesPerSec;
	/** Players ever seen in drawDynamic or the legacy draw call. Should always be 0; players are drawn through drawTemp. */
	long playersInOtherCalls;
	/** Player draws ever made off the client thread. Should always be 0. */
	long offThreadDraws;
	/** Errors ever hit while drawing a hidden stackmate. */
	long revealErrors;
	/** Players briefly held back so the game confirms the rest of their tile; total. */
	long probeHeld;
	/** Players never confirmed by the game (e.g. hidden by the server), so never drawn; total. */
	long probeGaveUp;
	long probeBackOffs;
	/** Times a tile switched between a row and a crowd, or a row turned; total. */
	long shapeChanges;
	/** Times a player with a spot was moved to a different spot to fill a gap; total. */
	long spotMoves;
	/** Players standing still on a crowded tile whom the game isn't showing, last tick. */
	int unseenStacked;
	/** What was decided for the spread tile nearest to you, or null if none. */
	String nearestTile;
	/** No player draws at all for over a second while connected and logged in. */
	boolean noPlayerDrawsSustained;
	/** Players (or you, in test mode) should be shifted but nothing was drawn shifted for over a second. */
	boolean nothingMovedSustained;

	// what the last game tick found
	int nearby;
	/** Of those, how many are aboard a boat. */
	int aboard;
	int still;
	int stackedTiles;
	int moving;
	int skippedIds;
}

