	private static String plural(int n, String word)
	{
		return n + " " + word + (n == 1 ? "" : "s");
	}

	private static String yesNo(boolean b)
	{
		return b ? "yes" : "no";
	}
}

package com.grant9008.personalspace;

import java.util.Arrays;

/**
 * Decides whether a player is standing still, without relying on animation ids.
 *
 * <p>A player counts as standing still when, on two game ticks in a row, they were exactly in the
 * middle of the same tile. Someone walking or running is between tiles, or on a different tile,
 * at least one of those ticks, so they never qualify and never get pulled into a group mid-stride.
 *
 * <p>Client thread only. Knows nothing about RuneLite so it can be unit tested.
 */
final class StillnessTracker
{
	private final long[] tile = new long[OffsetTable.CAPACITY];
	/** Tick on which the player was last seen centred on {@link #tile}; 0 means "not centred". */
	private final int[] centredTick = new int[OffsetTable.CAPACITY];
	/** Tick on which the player was first seen centred on {@link #tile}, this time round. */
	private final int[] arrivedTick = new int[OffsetTable.CAPACITY];

	/**
	 * Record where a player is this tick.
	 *
	 * @param id       player id
	 * @param tileKey  the tile they are on
	 * @param centred  whether they are exactly in the middle of that tile right now
	 * @param tick     this tick's number; must go up by one each game tick and start at 1
	 * @return true if they were also centred on this same tile on the previous tick
	 */
	boolean observe(int id, long tileKey, boolean centred, int tick)
	{
		if (id < 0 || id >= OffsetTable.CAPACITY)
		{
			return false;
		}
		if (!centred)
		{
			centredTick[id] = 0;
			return false;
		}
		boolean still = centredTick[id] != 0 && centredTick[id] == tick - 1 && tile[id] == tileKey;
		if (!still)
		{
			arrivedTick[id] = tick;
		}
		tile[id] = tileKey;
		centredTick[id] = tick;
		return still;
	}

	/** The tick this player came to stand where they are now; 0 if unknown. */
	int arrivedTick(int id)
	{
		return id >= 0 && id < OffsetTable.CAPACITY ? arrivedTick[id] : 0;
	}

	void clear()
	{
		Arrays.fill(centredTick, 0);
		Arrays.fill(arrivedTick, 0);
	}

	/** Local coordinates of a size-1 actor standing in the middle of a tile end in exactly half a tile. */
	static boolean isCentred(int localX, int localY)
	{
		return (localX & 127) == 64 && (localY & 127) == 64;
	}
}

package com.grant9008.personalspace;

import java.lang.reflect.Proxy;
import java.util.Arrays;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.AnimationID;
import org.junit.Assert;
import org.junit.Test;

public class AlchStylerTest
{
	/** A player that only knows its animation and frame. */
	private static final class FakePlayer
	{
		int animation;
		int frame = 7;
		int id = 5;
		/** Spell effects on them: slot to spotanim id. */
		final java.util.Map<Integer, Integer> effects = new java.util.LinkedHashMap<>();

		Player proxy()
		{
			return (Player) Proxy.newProxyInstance(Player.class.getClassLoader(), new Class<?>[]{Player.class}, (p, m, args) ->
			{
				switch (m.getName())
				{
					case "getAnimation":
						return animation;
					case "getId":
						return id;
					case "getSpotAnims":
						return spotAnims();
					case "removeSpotAnim":
						effects.remove((Integer) args[0]);
						return null;
					case "createSpotAnim":
						effects.put((Integer) args[0], (Integer) args[1]);
						return null;
					case "setAnimation":
						animation = (Integer) args[0];
						return null;
					case "setAnimationFrame":
						frame = (Integer) args[0];
						return null;
					case "hashCode":
						return System.identityHashCode(p);
					case "equals":
						return p == args[0];
					default:
						return null;
				}
			});
		}

		private net.runelite.api.IterableHashTable<net.runelite.api.ActorSpotAnim> spotAnims()
		{
			java.util.List<net.runelite.api.ActorSpotAnim> list = new java.util.ArrayList<>();
			for (java.util.Map.Entry<Integer, Integer> e : effects.entrySet())
			{
				int slot = e.getKey();
				int spotanim = e.getValue();
				list.add((net.runelite.api.ActorSpotAnim) Proxy.newProxyInstance(Player.class.getClassLoader(),
					new Class<?>[]{net.runelite.api.ActorSpotAnim.class}, (q, m, a) ->
						m.getName().equals("getId") ? (Object) spotanim : m.getName().equals("getHash") ? (Object) (long) slot : null));
			}
			@SuppressWarnings("unchecked")
			net.runelite.api.IterableHashTable<net.runelite.api.ActorSpotAnim> table = (net.runelite.api.IterableHashTable<net.runelite.api.ActorSpotAnim>)
				Proxy.newProxyInstance(Player.class.getClassLoader(), new Class<?>[]{net.runelite.api.IterableHashTable.class},
					(q, m, a) -> m.getName().equals("iterator") ? list.iterator() : null);
			return table;
		}
	}

	/** The game cycle the fake client is on. */
	private static int cycle;

	private static Client client(Player you)
	{
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(p, m, args) -> m.getName().equals("getLocalPlayer") ? you : m.getName().equals("getGameCycle") ? (Object) cycle : null);
	}

	@Test
	public void anAlchGlowArrivingAfterTheCastIsTakenOffToo()
	{
		cycle = 1000;
		FakePlayer alcher = new FakePlayer();
		alcher.animation = AnimationID.HUMAN_CASTHIGHLVLALCHEMY;
		alcher.effects.put(3, 86);
		Player p = alcher.proxy();
		AlchStyler styler = new AlchStyler(client(new FakePlayer().proxy()));
		styler.noticed(p);
		styler.apply(PersonalSpaceConfig.Alchers.STILL, true);
		Assert.assertEquals(-1, alcher.animation);
		// The glow comes a moment later, and nobody says so: it's taken off at the next frame.
		cycle += 30;
		alcher.effects.put(0, 113);
		styler.apply(PersonalSpaceConfig.Alchers.STILL, true);
		Assert.assertFalse("the alch glow is still there", alcher.effects.containsValue(113));
		Assert.assertTrue("another effect was taken off", alcher.effects.containsValue(86));
		// Long after the cast, nobody's effects are touched any more.
		cycle += AlchStyler.EFFECT_WATCH_CYCLES + 1;
		styler.apply(PersonalSpaceConfig.Alchers.STILL, true);
		alcher.effects.put(0, 113);
		styler.apply(PersonalSpaceConfig.Alchers.STILL, true);
		Assert.assertTrue(alcher.effects.containsValue(113));
	}

	@Test
	public void stillAlchersJustStand()
	{
		FakePlayer alcher = new FakePlayer();
		alcher.animation = AnimationID.HUMAN_CASTHIGHLVLALCHEMY;
		Player p = alcher.proxy();
		AlchStyler styler = new AlchStyler(client(new FakePlayer().proxy()));
		styler.noticed(p);
		styler.apply(PersonalSpaceConfig.Alchers.STILL, true);
		Assert.assertEquals(-1, alcher.animation);
		Assert.assertEquals(1, styler.restyled);
	}

	@Test
	public void partyAlchersDoOneOfTheEmotes()
	{
		AlchStyler styler = new AlchStyler(client(new FakePlayer().proxy()));
		for (int cast = 0; cast < 50; cast++)
		{
			FakePlayer alcher = new FakePlayer();
			alcher.animation = cast % 2 == 0 ? AnimationID.HUMAN_CASTLOWLVLALCHEMY : AnimationID.HUMAN_CASTHIGHLVLALCHEMY_FIRE;
			styler.noticed(alcher.proxy());
			styler.apply(PersonalSpaceConfig.Alchers.PARTY, true);
			int emote = alcher.animation;
			Assert.assertTrue("cast " + cast + ": " + emote, Arrays.stream(AlchStyler.PARTY_EMOTES).anyMatch(e -> e == emote));
			Assert.assertEquals("from the start", 0, alcher.frame);
		}
	}

	@Test
	public void yourOwnAlchingAndEveryoneElsesOtherAnimationsAreLeftAlone()
	{
		FakePlayer you = new FakePlayer();
		you.animation = AnimationID.HUMAN_CASTHIGHLVLALCHEMY;
		FakePlayer smith = new FakePlayer();
		smith.animation = 898;
		Player yours = you.proxy();
		AlchStyler styler = new AlchStyler(client(yours));
		styler.noticed(yours);
		styler.noticed(smith.proxy());
		styler.apply(PersonalSpaceConfig.Alchers.PARTY, true);
		Assert.assertEquals("your alch", AnimationID.HUMAN_CASTHIGHLVLALCHEMY, you.animation);
		Assert.assertEquals("smithing", 898, smith.animation);
		Assert.assertEquals(0, styler.restyled);
	}

	@Test
	public void normalOrSwitchedOffLeavesAlchersAsTheyAre()
	{
		for (boolean normal : new boolean[]{true, false})
		{
			FakePlayer alcher = new FakePlayer();
			alcher.animation = AnimationID.HUMAN_CASTHIGHLVLALCHEMY;
			AlchStyler styler = new AlchStyler(client(new FakePlayer().proxy()));
			styler.noticed(alcher.proxy());
			styler.apply(normal ? PersonalSpaceConfig.Alchers.NORMAL : PersonalSpaceConfig.Alchers.STILL, normal);
			Assert.assertEquals(AnimationID.HUMAN_CASTHIGHLVLALCHEMY, alcher.animation);
		}
	}

	@Test
	public void eachCastIsARandomEmoteNeverTheSameTwiceRunning()
	{
		AlchStyler styler = new AlchStyler(client(new FakePlayer().proxy()));
		int[] seen = new int[AlchStyler.PARTY_EMOTES.length];
		int last = -1;
		for (int cast = 0; cast < 600; cast++)
		{
			int emote = styler.nextEmote(42);
			Assert.assertNotEquals("cast " + cast + " repeated the last emote", last, emote);
			for (int i = 0; i < seen.length; i++)
			{
				seen[i] += AlchStyler.PARTY_EMOTES[i] == emote ? 1 : 0;
			}
			last = emote;
		}
		for (int i = 0; i < seen.length; i++)
		{
			Assert.assertTrue("emote " + AlchStyler.PARTY_EMOTES[i] + " came up " + seen[i] + " times in 600", seen[i] > 55);
		}
	}

	@Test
	public void thePartyEmoteBringsItsGlowAndTheNextEmoteTakesItAway()
	{
		cycle = 5000;
		AlchStyler styler = new AlchStyler(client(new FakePlayer().proxy()));
		FakePlayer alcher = new FakePlayer();
		Player p = alcher.proxy();
		boolean sawParty = false;
		boolean sawGlowGo = false;
		for (int cast = 0; cast < 200; cast++)
		{
			alcher.animation = AnimationID.HUMAN_CASTHIGHLVLALCHEMY;
			styler.noticed(p);
			styler.apply(PersonalSpaceConfig.Alchers.PARTY, true);
			boolean glow = AlchStyler.PARTY_GLOW == (alcher.effects.getOrDefault(AlchStyler.PARTY_GLOW_SLOT, -1));
			if (alcher.animation == AnimationID.EMOTE_PARTY)
			{
				sawParty = true;
				Assert.assertTrue("cast " + cast + ": the Party emote without its glow", glow);
			}
			else
			{
				Assert.assertFalse("cast " + cast + ": the glow stayed under " + alcher.animation, glow);
				sawGlowGo |= sawParty;
			}
		}
		Assert.assertTrue(sawParty && sawGlowGo);
		// Dancing done, or Party switched off: no glow left under them.
		while (alcher.animation != AnimationID.EMOTE_PARTY)
		{
			alcher.animation = AnimationID.HUMAN_CASTHIGHLVLALCHEMY;
			styler.noticed(p);
			styler.apply(PersonalSpaceConfig.Alchers.PARTY, true);
		}
		alcher.animation = -1;
		styler.apply(PersonalSpaceConfig.Alchers.PARTY, true);
		Assert.assertFalse("the glow outlasted the dance", alcher.effects.containsKey(AlchStyler.PARTY_GLOW_SLOT));
		while (alcher.animation != AnimationID.EMOTE_PARTY)
		{
			alcher.animation = AnimationID.HUMAN_CASTHIGHLVLALCHEMY;
			styler.noticed(p);
			styler.apply(PersonalSpaceConfig.Alchers.PARTY, true);
		}
		styler.apply(PersonalSpaceConfig.Alchers.NORMAL, true);
		Assert.assertFalse("the glow outlasted Party", alcher.effects.containsKey(AlchStyler.PARTY_GLOW_SLOT));
	}

	@Test
	public void noEmoteIsAnAlchAndEveryAlchCastIsKnown()
	{
		for (int e : AlchStyler.PARTY_EMOTES)
		{
			Assert.assertFalse(AlchStyler.CASTS.contains(e));
		}
		Assert.assertEquals(6, AlchStyler.PARTY_EMOTES.length);
		Assert.assertTrue("alchs, superheat, charge orb, enchants", AlchStyler.CASTS.containsAll(Arrays.asList(712, 713, 725, 726, 719, 931)));
		Assert.assertTrue(AlchStyler.EFFECTS.containsAll(Arrays.asList(112, 113, 148, 149, 150, 151, 152, 114, 238)));
	}
}

package com.grant9008.personalspace;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Player;
import org.junit.Assert;
import org.junit.Test;

/**
 * Leaving a busy player's action out of their walk model: what the model is built from, and that
 * everything is put back exactly, even when something throws.
 */
public class BusyWalkTest
{
	private static final int CAMPFIRE = 10573;
	private static final int IDLE = 808;
	private static final int WALK = 819;

	/** A player whose animation behaves like the client's: choosing an action restarts it, clearing it forgets the frame. */
	private static final class FakePlayer
	{
		int animation = -1;
		int animationFrame = -1;
		int pose = IDLE;
		int poseFrame;
		/** What the model was built from: action, pose, pose frame. */
		int[] builtFrom;
		/** The animation and frame the client would have drawn the model with (see {@link #shown}). */
		int[] drawn;
		final List<String> calls = new ArrayList<>();
		boolean failRestore;
		boolean failModel;
		/** setAnimation of this id throws, after choosing it half-way like the client would. */
		int failOn = -2;
		/** The client's crowd rule: more than 200 players about and standing in the idle pose. */
		boolean unanimated;
		/** An action still waiting out its start delay: the client leaves it out of the model. */
		boolean actionDelayed;
		/** The frame the client's idle fallback was left at. */
		int idleFallbackFrame = 9;

		/**
		 * What the client draws, as in its model choice: the action unless delayed; the pose unless
		 * the player is marked unanimated, or it is the idle pose under an action; the idle fallback
		 * at its leftover frame if neither. A walk has no interleave mask, so with an action the
		 * pose is not seen.
		 */
		int[] shown()
		{
			if (animation != -1 && !actionDelayed)
			{
				return new int[]{animation, animationFrame};
			}
			boolean poseUsed = pose != -1 && !unanimated && !(pose == IDLE && animation != -1 && !actionDelayed);
			return poseUsed ? new int[]{pose, poseFrame} : new int[]{IDLE, idleFallbackFrame};
		}

		Player proxy()
		{
			return (Player) Proxy.newProxyInstance(Player.class.getClassLoader(), new Class<?>[]{Player.class}, (p, m, args) ->
			{
				switch (m.getName())
				{
					case "getAnimation":
						return animation;
					case "getAnimationFrame":
						return animationFrame;
					case "getPoseAnimation":
						return pose;
					case "getPoseAnimationFrame":
						return poseFrame;
					case "setAnimation":
					{
						int id = (Integer) args[0];
						calls.add("setAnimation " + id);
						if (id == failOn)
						{
							failOn = -2;
							animation = id;
							throw new IllegalStateException("definition lookup failed");
						}
						if (id >= 0 && failRestore)
						{
							failRestore = false;
							animation = id;
							animationFrame = -1;
							throw new IllegalStateException("definition lookup failed");
						}
						if (id < 0)
						{
							animation = -1;
							animationFrame = -1;
						}
						else if (id != animation)
						{
							animation = id;
							if (animationFrame == -1)
							{
								animationFrame = 0;
							}
						}
						return null;
					}
					case "setAnimationFrame":
						calls.add("setAnimationFrame " + args[0]);
						animationFrame = (Integer) args[0];
						return null;
					case "setPoseAnimation":
						pose = (Integer) args[0];
						return null;
					case "setPoseAnimationFrame":
						poseFrame = (Integer) args[0];
						return null;
					case "getIdlePoseAnimation":
						return IDLE;
					case "getModel":
						builtFrom = new int[]{animation, pose, poseFrame};
						drawn = shown();
						if (failModel)
						{
							throw new IllegalStateException("model failed");
						}
						return null;
					case "hashCode":
						return System.identityHashCode(p);
					case "equals":
						return p == args[0];
					default:
						Class<?> r = m.getReturnType();
						return r == boolean.class ? false : r == int.class ? 0 : r == long.class ? 0L : null;
				}
			});
		}
	}

	private static FakePlayer tending()
	{
		FakePlayer f = new FakePlayer();
		f.animation = CAMPFIRE;
		f.animationFrame = 7;
		f.pose = IDLE;
		f.poseFrame = 3;
		return f;
	}

	@Test
	public void busyPlayerIsBuiltWalkingWithTheActionLeftOut()
	{
		FakePlayer f = tending();
		SpreadingDrawCallbacks.modelMidStep(f.proxy(), WALK, 5);
		Assert.assertArrayEquals(new int[]{-1, WALK, 5}, f.builtFrom);
	}

	@Test
	public void actionComesBackAtTheFrameItHadReached()
	{
		FakePlayer f = tending();
		SpreadingDrawCallbacks.modelMidStep(f.proxy(), WALK, 5);
		Assert.assertEquals(CAMPFIRE, f.animation);
		Assert.assertEquals(7, f.animationFrame);
		Assert.assertEquals(IDLE, f.pose);
		Assert.assertEquals(3, f.poseFrame);
	}

	@Test
	public void idlePlayersActionIsNeverTouched()
	{
		FakePlayer f = new FakePlayer();
		f.poseFrame = 2;
		SpreadingDrawCallbacks.modelMidStep(f.proxy(), WALK, 4);
		Assert.assertArrayEquals(new int[]{-1, WALK, 4}, f.builtFrom);
		Assert.assertTrue(f.calls.isEmpty());
		Assert.assertEquals(IDLE, f.pose);
		Assert.assertEquals(2, f.poseFrame);
	}

	@Test
	public void everythingIsPutBackWhenTheModelFails()
	{
		FakePlayer f = tending();
		f.failModel = true;
		try
		{
			SpreadingDrawCallbacks.modelMidStep(f.proxy(), WALK, 5);
			Assert.fail();
		}
		catch (IllegalStateException expected)
		{
		}
		Assert.assertEquals(CAMPFIRE, f.animation);
		Assert.assertEquals(7, f.animationFrame);
		Assert.assertEquals(IDLE, f.pose);
		Assert.assertEquals(3, f.poseFrame);
	}

	@Test
	public void aFailedRestoreLeavesTheActionClearedNotHalfChosen()
	{
		FakePlayer f = tending();
		f.failRestore = true;
		try
		{
			SpreadingDrawCallbacks.modelMidStep(f.proxy(), WALK, 5);
			Assert.fail();
		}
		catch (IllegalStateException expected)
		{
		}
		Assert.assertEquals(-1, f.animation);
		Assert.assertEquals("setAnimation -1", f.calls.get(f.calls.size() - 1));
		Assert.assertEquals(IDLE, f.pose);
		Assert.assertEquals(3, f.poseFrame);
	}

	// ---- walking to a spot: the walk in the action slot too ----------------------------------

	@Test
	public void inACrowdThePoseAloneLeftTheLegsStill()
	{
		// The 1.9.3 report: 246 players about, walks drawn with legs still. The pose is dropped.
		FakePlayer f = new FakePlayer();
		f.unanimated = true;
		for (int frame = 0; frame < 4; frame++)
		{
			SpreadingDrawCallbacks.modelMidStep(f.proxy(), WALK, frame);
			Assert.assertArrayEquals(new int[]{IDLE, 9}, f.drawn);
		}
	}

	@Test
	public void inACrowdTheWalkIsDrawnFrameByFrame()
	{
		for (boolean busy : new boolean[]{false, true})
		{
			FakePlayer f = busy ? tending() : new FakePlayer();
			f.unanimated = true;
			for (int frame = 0; frame < 4; frame++)
			{
				SpreadingDrawCallbacks.modelStepping(f.proxy(), WALK, frame);
				Assert.assertArrayEquals(new int[]{WALK, frame}, f.drawn);
			}
		}
	}

	@Test
	public void outOfACrowdTheWalkIsDrawnToo()
	{
		FakePlayer f = new FakePlayer();
		SpreadingDrawCallbacks.modelStepping(f.proxy(), WALK, 6);
		Assert.assertArrayEquals(new int[]{WALK, WALK, 6}, f.builtFrom);
		Assert.assertArrayEquals(new int[]{WALK, 6}, f.drawn);
	}

	@Test
	public void anActionWaitingToStartStillLetsTheWalkShow()
	{
		FakePlayer f = tending();
		f.actionDelayed = true;
		SpreadingDrawCallbacks.modelStepping(f.proxy(), WALK, 2);
		Assert.assertArrayEquals(new int[]{WALK, 2}, f.drawn);
	}

	@Test
	public void steppingPutsAnIdlePlayerBackExactly()
	{
		FakePlayer f = new FakePlayer();
		f.animationFrame = 11;
		f.poseFrame = 4;
		SpreadingDrawCallbacks.modelStepping(f.proxy(), WALK, 5);
		Assert.assertEquals(-1, f.animation);
		Assert.assertEquals(11, f.animationFrame);
		Assert.assertEquals(IDLE, f.pose);
		Assert.assertEquals(4, f.poseFrame);
		Assert.assertEquals("setAnimation -1", f.calls.get(f.calls.size() - 2));
	}

	@Test
	public void steppingPutsABusyPlayerBackAtTheFrameTheyHadReached()
	{
		FakePlayer f = tending();
		SpreadingDrawCallbacks.modelStepping(f.proxy(), WALK, 5);
		Assert.assertEquals(CAMPFIRE, f.animation);
		Assert.assertEquals(7, f.animationFrame);
		Assert.assertEquals(IDLE, f.pose);
		Assert.assertEquals(3, f.poseFrame);
	}

	@Test
	public void steppingPutsEverythingBackWhenTheModelFails()
	{
		FakePlayer f = tending();
		f.failModel = true;
		try
		{
			SpreadingDrawCallbacks.modelStepping(f.proxy(), WALK, 5);
			Assert.fail();
		}
		catch (IllegalStateException expected)
		{
		}
		Assert.assertEquals(CAMPFIRE, f.animation);
		Assert.assertEquals(7, f.animationFrame);
		Assert.assertEquals(IDLE, f.pose);
		Assert.assertEquals(3, f.poseFrame);
	}

	@Test
	public void aWalkThatCantBeChosenStillPutsTheActionBack()
	{
		FakePlayer f = tending();
		f.failOn = WALK;
		try
		{
			SpreadingDrawCallbacks.modelStepping(f.proxy(), WALK, 5);
			Assert.fail();
		}
		catch (IllegalStateException expected)
		{
		}
		Assert.assertEquals(CAMPFIRE, f.animation);
		Assert.assertEquals(7, f.animationFrame);
		Assert.assertEquals(IDLE, f.pose);
		Assert.assertEquals(3, f.poseFrame);
	}

	@Test
	public void aFailedRestoreAfterSteppingLeavesTheActionClearedNotHalfChosen()
	{
		FakePlayer f = tending();
		f.failOn = CAMPFIRE;
		try
		{
			SpreadingDrawCallbacks.modelStepping(f.proxy(), WALK, 5);
			Assert.fail();
		}
		catch (IllegalStateException expected)
		{
		}
		Assert.assertEquals(-1, f.animation);
		Assert.assertEquals("setAnimation -1", f.calls.get(f.calls.size() - 1));
		Assert.assertEquals(IDLE, f.pose);
		Assert.assertEquals(3, f.poseFrame);
	}
}

package com.grant9008.personalspace;

import net.runelite.api.ChatMessageType;
import org.junit.Assert;
import org.junit.Test;

public class ChatHiderTest
{
	@Test
	public void onlyPublicChatIsEverDropped()
	{
		Assert.assertTrue(ChatHider.isPublic(ChatMessageType.PUBLICCHAT));
		Assert.assertTrue(ChatHider.isPublic(ChatMessageType.AUTOTYPER));
		Assert.assertFalse("private messages stay", ChatHider.isPublic(ChatMessageType.PRIVATECHAT));
		Assert.assertFalse("clan chat stays", ChatHider.isPublic(ChatMessageType.CLAN_CHAT));
		Assert.assertFalse("friends chat stays", ChatHider.isPublic(ChatMessageType.FRIENDSCHAT));
		Assert.assertFalse("game messages stay", ChatHider.isPublic(ChatMessageType.GAMEMESSAGE));
	}

	@Test
	public void chatFurtherThanTheRangeIsHidden()
	{
		Assert.assertFalse("off", ChatHider.tooFar(14, 0));
		Assert.assertFalse("within range", ChatHider.tooFar(5, 5));
		Assert.assertTrue("one past it", ChatHider.tooFar(6, 5));
		Assert.assertFalse("speaker never found: shown", ChatHider.tooFar(null, 5));
		Assert.assertEquals("a diagonal step counts one", 3, ChatHider.tilesApart(10, 10, 13, 12));
		Assert.assertEquals(7, ChatHider.tilesApart(3200, 3200, 3200, 3193));
	}

	@Test
	public void namesMatchWhateverIconsAndSpacesTheyCarry()
	{
		Assert.assertEquals(ChatHider.standard("Casino Bot"), ChatHider.standard("<img=41>casino\u00a0bot"));
	}
}

package com.grant9008.personalspace;

import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class ChatRangeOverlayTest
{
	@Test
	public void theAreaIsTheSquareOfTilesTheChatFilterKeeps()
	{
		// Within 2 tiles of tile (50, 50): tiles 48..52 each way, so corners from 48 to 53 tiles in.
		List<int[]> corners = ChatRangeOverlay.boundary(50, 50, 2);
		Assert.assertEquals("a corner a tile apart all round, and back to the start", 4 * 5 + 1, corners.size());
		Assert.assertArrayEquals(corners.get(0), corners.get(corners.size() - 1));
		int min = Integer.MAX_VALUE;
		int max = Integer.MIN_VALUE;
		for (int[] c : corners)
		{
			min = Math.min(min, Math.min(c[0], c[1]));
			max = Math.max(max, Math.max(c[0], c[1]));
		}
		Assert.assertEquals(48 * 128, min);
		Assert.assertEquals(53 * 128, max);
		// Every tile inside it is one the chat filter counts as within 2: the far corner tile included.
		Assert.assertEquals(2, ChatHider.tilesApart(50, 50, 52, 52));
		Assert.assertEquals(3, ChatHider.tilesApart(50, 50, 53, 50));
	}
}

package com.grant9008.personalspace;

import org.junit.Assert;
import org.junit.Test;

public class CollisionTerrainTest
{
	private static final int SIZE = 20;
	private static final int TX = 10;
	private static final int TZ = 10;
	private static final int CX = TX * 128 + 64;
	private static final int CZ = TZ * 128 + 64;

	private static int[][][] openGround()
	{
		int[][][] flags = new int[4][][];
		flags[0] = new int[SIZE][SIZE];
		return flags;
	}

	@Test
	public void nobodyIsDrawnInsideABlockedTileOrAgainstIt()
	{
		// A bank booth on the tile to the north.
		int[][][] flags = openGround();
		flags[0][TX][TZ + 1] = CollisionTerrain.BLOCK_FULL;
		CollisionTerrain terrain = new CollisionTerrain(flags);
		Assert.assertFalse("inside the booth", terrain.canStand(0, CX, CZ, CX, CZ + 128));
		Assert.assertFalse("pressed against the booth", terrain.canStand(0, CX, CZ, CX, CZ + 60));
		Assert.assertTrue(terrain.canStand(0, CX, CZ, CX, CZ + 20));
		Assert.assertTrue("open to the south", terrain.canStand(0, CX, CZ, CX, CZ - 100));
	}

	@Test
	public void wallsAreNotCrossed()
	{
		// Wall along the east edge of the tile.
		int[][][] flags = openGround();
		flags[0][TX][TZ] |= CollisionTerrain.BLOCK_EAST;
		flags[0][TX + 1][TZ] |= CollisionTerrain.BLOCK_WEST;
		CollisionTerrain terrain = new CollisionTerrain(flags);
		Assert.assertFalse("across the wall", terrain.canStand(0, CX, CZ, CX + 100, CZ));
		Assert.assertFalse("against the wall", terrain.canStand(0, CX, CZ, CX + 50, CZ));
		Assert.assertTrue(terrain.canStand(0, CX, CZ, CX - 100, CZ));
	}

	@Test
	public void aStraightLineStopsAtWallsAndBlockedTilesButGoesThroughADoor()
	{
		// A wall along the north edge of row TZ, with a door in it at column TX.
		int[][][] flags = openGround();
		for (int x = TX - 3; x <= TX + 3; x++)
		{
			if (x != TX)
			{
				flags[0][x][TZ] |= CollisionTerrain.BLOCK_NORTH;
				flags[0][x][TZ + 1] |= CollisionTerrain.BLOCK_SOUTH;
			}
		}
		flags[0][TX + 5][TZ] = CollisionTerrain.BLOCK_FULL;
		CollisionTerrain terrain = new CollisionTerrain(flags);
		Assert.assertTrue("through the door", terrain.clearLine(0, CX, CZ, CX + 20, CZ + 128));
		Assert.assertFalse("through the wall beside it", terrain.clearLine(0, CX + 128, CZ, CX + 128, CZ + 128));
		Assert.assertFalse("slanting out through the wall", terrain.clearLine(0, CX + 200, CZ, CX + 100, CZ + 256));
		Assert.assertTrue("along the inside of the wall", terrain.clearLine(0, CX - 300, CZ + 40, CX + 300, CZ + 40));
		Assert.assertFalse("through the booth", terrain.clearLine(0, CX + 4 * 128, CZ, CX + 6 * 128, CZ));
		Assert.assertFalse("from inside it", terrain.clearLine(0, CX + 5 * 128, CZ, CX + 6 * 128, CZ));
		Assert.assertTrue("the same spot", terrain.clearLine(0, CX, CZ, CX, CZ));
		// Exactly through the corner where the wall starts beside the door: it takes both ways round it.
		Assert.assertFalse("diagonally past the end of the wall", terrain.clearLine(0, CX, CZ, CX + 128, CZ + 128));
		Assert.assertTrue("straight out of the door", terrain.clearLine(0, CX, CZ, CX, CZ + 256));
	}

	@Test
	public void roomForABodyKeepsClearOfBlockedEdges()
	{
		int[][][] flags = openGround();
		flags[0][TX][TZ] |= CollisionTerrain.BLOCK_EAST;
		flags[0][TX + 1][TZ] |= CollisionTerrain.BLOCK_WEST;
		flags[0][TX][TZ + 1] = CollisionTerrain.BLOCK_FULL;
		CollisionTerrain terrain = new CollisionTerrain(flags);
		Assert.assertTrue(terrain.roomAt(0, CX, CZ));
		Assert.assertFalse("against the wall", terrain.roomAt(0, CX + 50, CZ));
		Assert.assertFalse("against the booth", terrain.roomAt(0, CX, CZ + 50));
		Assert.assertFalse("in the booth", terrain.roomAt(0, CX, CZ + 128));
		Assert.assertTrue(new CollisionTerrain(new int[4][][]).roomAt(0, CX, CZ));
	}

	@Test
	public void noMapMeansNoLimits()
	{
		Assert.assertTrue(new CollisionTerrain(new int[4][][]).canStand(0, CX, CZ, CX + 300, CZ));
	}

	@Test
	public void facingAnAnvilOrAWallCountsButOpenFloorDoesNot()
	{
		int[][][] anvil = openGround();
		anvil[0][TX][TZ + 1] = CollisionTerrain.BLOCK_FULL;
		Assert.assertTrue(new CollisionTerrain(anvil).facesObstacle(0, TX, TZ, Math.PI));
		Assert.assertFalse("facing away from it", new CollisionTerrain(anvil).facesObstacle(0, TX, TZ, 0));

		int[][][] wall = openGround();
		wall[0][TX][TZ] |= CollisionTerrain.BLOCK_EAST;
		Assert.assertTrue(new CollisionTerrain(wall).facesObstacle(0, TX, TZ, 3 * Math.PI / 2));

		Assert.assertFalse(new CollisionTerrain(openGround()).facesObstacle(0, TX, TZ, Math.PI));
	}

	@Test
	public void aRowOfBoothsIsACounterButASingleAnvilIsNot()
	{
		// Facing north (pi) from the tile at (TX, TZ).
		int[][][] booths = openGround();
		for (int x = TX - 2; x <= TX + 2; x++)
		{
			booths[0][x][TZ + 1] = CollisionTerrain.BLOCK_FULL;
		}
		Assert.assertTrue(new CollisionTerrain(booths).isCounter(0, TX, TZ, Math.PI));

		int[][][] anvil = openGround();
		anvil[0][TX][TZ + 1] = CollisionTerrain.BLOCK_FULL;
		Assert.assertFalse(new CollisionTerrain(anvil).isCounter(0, TX, TZ, Math.PI));

		Assert.assertFalse("open floor", new CollisionTerrain(openGround()).isCounter(0, TX, TZ, Math.PI));
		Assert.assertFalse("facing along the counter, not at it", new CollisionTerrain(booths).isCounter(0, TX, TZ, Math.PI / 2));
	}

	@Test
	public void aCounterWallCountsToo()
	{
		// A wall along the north edge of three tiles in a row.
		int[][][] flags = openGround();
		for (int x = TX - 1; x <= TX + 1; x++)
		{
			flags[0][x][TZ] |= CollisionTerrain.BLOCK_NORTH;
			flags[0][x][TZ + 1] |= CollisionTerrain.BLOCK_SOUTH;
		}
		Assert.assertTrue(new CollisionTerrain(flags).isCounter(0, TX, TZ, Math.PI));
	}

	@Test
	public void terrainStepRules()
	{
		int[][] f = new int[3][3];
		Assert.assertTrue(CollisionTerrain.canStep(f, 1, 1, 1, 0));
		f[2][1] = CollisionTerrain.BLOCK_FULL;
		Assert.assertFalse("can't step onto a blocked tile", CollisionTerrain.canStep(f, 1, 1, 1, 0));
		f[2][1] = 0;
		f[1][1] = CollisionTerrain.BLOCK_NORTH;
		Assert.assertFalse("wall on the north edge", CollisionTerrain.canStep(f, 1, 1, 0, 1));
		Assert.assertFalse("diagonal past that wall", CollisionTerrain.canStep(f, 1, 1, 1, 1));
		Assert.assertTrue(CollisionTerrain.canStep(f, 1, 1, 0, -1));
		Assert.assertFalse("off the map", CollisionTerrain.canStep(f, 2, 2, 1, 0));
	}
}

package com.grant9008.personalspace;

import org.junit.Assert;
