		// Within each row, the tiles keep their people in order along the bank.
		for (int t = 0; t < 3; t++)
		{
			for (int i = 1; i <= 7; i++)
			{
				for (int k = 1; k <= 7; k++)
				{
					int[] mine = at.get(t * 10 + i);
					int[] next = at.get((t + 1) * 10 + k);
					if (mine[1] == next[1])
					{
						Assert.assertTrue("tile " + t + " passes tile " + (t + 1) + " in a row", mine[0] < next[0]);
					}
				}
			}
		}
	}

