	@Test
	public void theCrowdOnACampfireInACornerWalksOutOfItButNotThroughTheWalls()
	{
		// The fire's own tile in the corner of a room, walls along its west and south edges. Walking
		// out of the fire, someone headed for the gap between the two walls, through the corner.
		int[][][] flags = openFlags();
		for (int y = 50; y <= 60; y++)
		{
			flags[0][49][y] |= CollisionTerrain.BLOCK_EAST;
			flags[0][50][y] |= CollisionTerrain.BLOCK_WEST;
		}
		for (int x = 50; x <= 60; x++)
		{
			flags[0][x][49] |= CollisionTerrain.BLOCK_NORTH;
			flags[0][x][50] |= CollisionTerrain.BLOCK_SOUTH;
		}
		CrowdPlanner.Surroundings campfire = fireAt5050(flags, false);
		List<StackSpreader.Entry> still = new ArrayList<>();
		int[] id = {1};
		tending(still, id, 50, 50, 14);
		tending(still, id, 50, 51, 4);
		tending(still, id, 51, 51, 4);
		tending(still, id, 51, 50, 4);
		CrowdPlanner planner = new CrowdPlanner();
		for (int t = 1; t <= 10; t++)
		{
			CrowdPlanner.Plan plan = atTheFire(planner, still, t, campfire);
			Assert.assertEquals(CrowdPlanner.ROUND_FIRE, plan.tiles.get(FIRE).shape);
			assertNobodyInsideAnybody("tick " + t, drawnAsThePluginDoes(plan, still));
			for (StackSpreader.Placement p : plan.placements)
			{
				int x = StackRegistry.sceneX(p.tile) * 128 + 64 + p.dx;
				int z = StackRegistry.sceneY(p.tile) * 128 + 64 + p.dz;
				Assert.assertTrue("tick " + t + ": player " + p.id + " is drawn outside the room at (" + p.dx + ", " + p.dz + ")",
					x >= 50 * 128 && z >= 50 * 128);
				// Their walk there, one tile to the next: never across a wall, nor through a corner both walls meet at.
				int px = StackRegistry.sceneX(p.tile);
				int pz = StackRegistry.sceneY(p.tile);
				for (int k = 1; k <= 64; k++)
				{
					int tx = Math.floorDiv(StackRegistry.sceneX(p.tile) * 128 + 64 + (int) Math.round(p.dx * k / 64.0), 128);
					int tz = Math.floorDiv(StackRegistry.sceneY(p.tile) * 128 + 64 + (int) Math.round(p.dz * k / 64.0), 128);
					if (tx != px || tz != pz)
					{
						Assert.assertTrue("tick " + t + ": player " + p.id + " walks through a wall to (" + p.dx + ", " + p.dz + ")",
							CollisionTerrain.canStep(flags[0], px, pz, tx - px, tz - pz));
						px = tx;
						pz = tz;
					}
				}
			}
		}
	}

	@Test
	public void theLastAtABusyCampfireKeepTheirPlacesRoundItAndNeverWalkThroughIt()
	{
		// A busy campfire empties until one is left on it and one beside it, each alone on their tile,
		// then only the one on it. With nobody left sharing a tile the crowd wasn't laid out at all:
		// the one on the fire was given the first place by it afresh, and walked straight through it.
		CrowdPlanner.Surroundings campfire = fireAt5050(openFlags(), false);
		List<StackSpreader.Entry> still = busyCampfire(10, 3, false);
		CrowdPlanner planner = new CrowdPlanner();
		Map<Integer, int[]> was = null;
		for (int t = 1; t <= 10; t++)
		{
			was = spots(atTheFire(planner, still, t, campfire));
		}
		// The one on the fire standing furthest west, across it from the first place by it.
		StackSpreader.Entry onIt = null;
		StackSpreader.Entry beside = null;
		for (StackSpreader.Entry e : still)
		{
			if (e.tile == FIRE && was.containsKey(e.id) && (onIt == null || was.get(e.id)[0] < was.get(onIt.id)[0]))
			{
				onIt = e;
			}
			beside = beside == null && e.tile == StackRegistry.key(0, 50, 51) ? e : beside;
		}
		Assert.assertTrue("someone on the fire stands west of it", was.get(onIt.id)[0] < -64);
		List<StackSpreader.Entry> few = new ArrayList<>();
		few.add(onIt);
		few.add(beside);
		int[] at = was.get(onIt.id);
		for (int t = 11; t <= 30; t++)
		{
			List<StackSpreader.Entry> now = t <= 20 ? few : few.subList(0, 1);
			int[] spot = spots(atTheFire(planner, now, t, campfire)).get(onIt.id);
			Assert.assertNotNull("tick " + t + ": the last one on the fire is drawn in it", spot);
			for (int k = 0; k <= 64; k++)
			{
				int x = 50 * 128 + 64 + at[0] + (int) Math.round((spot[0] - at[0]) * k / 64.0);
				int z = 50 * 128 + 64 + at[1] + (int) Math.round((spot[1] - at[1]) * k / 64.0);
				Assert.assertFalse("tick " + t + ": the last one on the fire walks through it from (" + at[0] + ", " + at[1] + ") to ("
					+ spot[0] + ", " + spot[1] + ")", inFireClearance(x, z));
			}
			double moved = Math.hypot(spot[0] - at[0], spot[1] - at[1]);
			Assert.assertTrue("tick " + t + ": the last one on the fire moved " + Math.round(moved), t == 21 ? moved < 48 : moved < 16);
			at = spot;
		}
	}

	@Test
	public void twoBusyCampfiresSideBySideAreStoodRoundClearOfBothFires()
	{
		// Two Forester's Campfires on neighbouring tiles, both busy. The crowd round each stood clear of
		// its own flames, but up against the other fire's, and walked round the corner of them.
		int[][][] flags = openFlags();
		CollisionTerrain terrain = new CollisionTerrain(flags);
		long other = StackRegistry.key(0, 51, 50);
		CrowdPlanner.Surroundings two = new CrowdPlanner.Surroundings()
		{
			public boolean canStand(long t, int dx, int dz)
			{
				int x = StackRegistry.sceneX(t) * 128 + 64;
				int z = StackRegistry.sceneY(t) * 128 + 64;
				return terrain.canStand(0, x, z, x + dx, z + dz) && !inFireClearance(x + dx, z + dz) && !inFireClearance(x + dx - 128, z + dz);
			}
			public boolean facesObstacle(long t, double a) { return false; }
			public boolean isCounter(long t, double a) { return false; }
			public boolean facesFire(long t, double a)
			{
				int x = StackRegistry.sceneX(t) + (int) Math.round(-Math.sin(a));
				int y = StackRegistry.sceneY(t) + (int) Math.round(-Math.cos(a));
				return (x == 50 || x == 51) && y == 50;
			}
			public List<int[]> firesNear(long t)
			{
				List<int[]> out = new ArrayList<>();
				for (int fx = 50; fx <= 51; fx++)
				{
					int east = fx - StackRegistry.sceneX(t);
					int north = 50 - StackRegistry.sceneY(t);
					if (Math.abs(east) <= 1 && Math.abs(north) <= 1)
					{
						out.add(new int[]{east, north});
					}
				}
				return out;
			}
		};
		List<StackSpreader.Entry> still = new ArrayList<>();
		int[] id = {1};
		int[][] crowd = {{50, 50, 8, 50}, {51, 50, 8, 51}, {49, 50, 5, 50}, {52, 50, 5, 51}, {50, 51, 5, 50}, {51, 51, 5, 51},
			{50, 49, 4, 50}, {51, 49, 5, 51}, {49, 51, 3, 50}, {52, 49, 3, 51}};
		for (int[] c : crowd)
		{
			for (int i = 0; i < c[2]; i++)
			{
				int facing = c[0] == c[3] && c[1] == 50 ? (id[0] * 300) % 2048 : OffsetTable.facing(c[3] - c[0], 50 - c[1]);
				still.add(new StackSpreader.Entry(id[0]++, StackRegistry.key(0, c[0], c[1]), false, facing, true));
			}
		}
		CrowdPlanner planner = new CrowdPlanner();
		Map<Integer, int[]> last = new HashMap<>();
		for (int t = 1; t <= 10; t++)
		{
			CrowdPlanner.Plan plan = atTheFire(planner, still, t, two);
			assertNobodyInsideAnybody("tick " + t, drawnAsThePluginDoes(plan, still));
			Map<Integer, int[]> now = new HashMap<>();
			for (StackSpreader.Placement p : plan.placements)
			{
				Assert.assertEquals("tick " + t + ": player " + p.id + " is one of a crowd round a fire", CrowdPlanner.ROUND_FIRE, plan.tiles.get(p.tile).shape);
				int x = StackRegistry.sceneX(p.tile) * 128 + 64 + p.dx;
				int z = StackRegistry.sceneY(p.tile) * 128 + 64 + p.dz;
				for (int fire = 0; fire <= 1; fire++)
				{
					double clear = fromTheFiresTile(x - fire * 128, z);
					Assert.assertTrue("tick " + t + ": player " + p.id + " is drawn " + Math.round(clear) + " from a fire's tile", clear >= CrowdPlanner.FIRE_MARGIN - 0.5);
				}
				int[] from = last.getOrDefault(p.id, new int[]{0, 0});
				for (int fire = 0; fire <= 1; fire++)
				{
					if (from[0] == 0 && from[1] == 0 && p.tile == (fire == 0 ? FIRE : other))
					{
						continue; // walking out of the fire they stand on
					}
					for (int k = 0; k <= 64; k++)
					{
						int wx = StackRegistry.sceneX(p.tile) * 128 + 64 + from[0] + (int) Math.round((p.dx - from[0]) * k / 64.0);
						int wz = StackRegistry.sceneY(p.tile) * 128 + 64 + from[1] + (int) Math.round((p.dz - from[1]) * k / 64.0);
						Assert.assertFalse("tick " + t + ": player " + p.id + " walks through a fire from (" + from[0] + ", " + from[1] + ") to ("
							+ p.dx + ", " + p.dz + ")", inFireClearance(wx - fire * 128, wz));
					}
				}
				now.put(p.id, new int[]{p.dx, p.dz});
			}
			last = now;
		}
	}

	/**
	 * How far behind someone wearing a cape, and how far round from straight back, the legs of whoever
	 * stands there pass through it, as the game's own models of the common capes have it (both
	 * standing, idling): about 64 apart, within 70 degrees of straight back.
	 */
	private static final int CAPE_HANGS = 64;
	private static final double CAPE_SIDE = Math.cos(Math.toRadians(70));

	/** These people, with a cape on everyone {@code caped} picks. */
	private static List<StackSpreader.Entry> withCapes(List<StackSpreader.Entry> still, java.util.function.IntPredicate caped)
	{
		List<StackSpreader.Entry> out = new ArrayList<>();
		for (StackSpreader.Entry e : still)
		{
			out.add(new StackSpreader.Entry(e.id, e.tile, e.local, e.orientation, e.busy, caped.test(e.id)));
		}
		return out;
	}

	/**
	 * Everyone drawn ({@code at}) in the way of someone's cape: behind them as the plugin turns them
	 * (towards the fire they're round, or what they face), nearer than {@link #CAPE_HANGS}.
	 */
	private static List<String> inTheWayOfCapes(CrowdPlanner.Plan plan, List<StackSpreader.Entry> still, Map<Integer, double[]> at)
	{
		Map<Integer, int[]> offset = spots(plan);
		List<String> out = new ArrayList<>();
		for (StackSpreader.Entry a : still)
		{
			double[] wearer = at.get(a.id);
			if (!a.cape || wearer == null)
			{
				continue;
			}
			int[] d = offset.getOrDefault(a.id, new int[]{0, 0});
			int[] fire = plan.fires.get(a.tile);
			int facing = fire != null ? StackSpreader.faceTowards(a.orientation, d[0], d[1], fire[0], fire[1])
				: plan.curvedRows.contains(a.tile) ? StackSpreader.faceSameSpot(a.orientation, d[0], d[1]) : a.orientation;
			double turn = facing * 2 * Math.PI / StackSpreader.FULL_TURN;
			// Facing (-sin, -cos): the cape hangs the other way.
			double backX = Math.sin(turn);
			double backZ = Math.cos(turn);
			for (Map.Entry<Integer, double[]> b : at.entrySet())
			{
				double east = b.getValue()[0] - wearer[0];
				double north = b.getValue()[1] - wearer[1];
				double apart = Math.hypot(east, north);
				if (b.getKey() != a.id && apart > 0 && apart < CAPE_HANGS && east * backX + north * backZ > CAPE_SIDE * apart)
				{
					out.add(b.getKey() + " is drawn " + Math.round(apart) + " behind " + a.id + "'s cape");
				}
			}
		}
		return out;
	}

	@Test
	public void nobodyRoundABusyCampfireStandsWhereSomeonesCapeHangs()
	{
		// Everyone round a busy campfire faces it, so a cape hangs out towards whoever stands behind,
		// and with depth between players on, a yellow cape was drawn through the green legs of the
		// one behind its wearer. Half of them wear capes, you too, and people come and go.
		CrowdPlanner.Surroundings campfire = fireAt5050(openFlags(), false);
		java.util.Random rnd = new java.util.Random(5);
		List<StackSpreader.Entry> roster = withCapes(busyCampfire(12, 8, true), id -> id % 2 == 1);
		Set<Integer> away = new HashSet<>();
		CrowdPlanner planner = new CrowdPlanner();
		Map<Integer, int[]> last = new HashMap<>();
		int moves = 0;
		int stays = 0;
		int drawn = 0;
		for (int t = 1; t <= 200; t++)
		{
			for (StackSpreader.Entry e : roster)
			{
				if (e.id != YOU && t > 10 && rnd.nextInt(100) < 2 && !away.remove(e.id))
				{
					away.add(e.id);
				}
			}
			List<StackSpreader.Entry> still = new ArrayList<>();
			for (StackSpreader.Entry e : roster)
			{
				if (!away.contains(e.id))
				{
					still.add(e);
				}
			}
			CrowdPlanner.Plan plan = atTheFire(planner, still, t, campfire);
			if (t >= 3)
			{
				Map<Integer, double[]> at = drawnAsThePluginDoes(plan, still);
				assertNobodyInsideAnybody("tick " + t, at);
				Assert.assertEquals("tick " + t, new ArrayList<>(), inTheWayOfCapes(plan, still, at));
				drawn += at.size();
			}
			Map<Integer, int[]> now = spots(plan);
			for (Map.Entry<Integer, int[]> e : now.entrySet())
			{
				int[] was = last.get(e.getKey());
				if (t > 10 && was != null)
				{
					stays++;
					moves += Math.hypot(was[0] - e.getValue()[0], was[1] - e.getValue()[1]) >= 16 ? 1 : 0;
				}
			}
			last = now;
		}
		Assert.assertTrue("people who stayed at the fire moved " + moves + " times in " + stays, stays > 3000 && moves <= 5);
		Assert.assertTrue("only " + drawn / 198 + " drawn round the fire", drawn / 198 >= 36);
	}

	@Test
	public void nobodyRoundABusyAnvilStandsWhereSomeonesCapeHangs()
	{
		// As round a fire: forty smithing, every other one in a cape, you among them in one. The
		// people on the corner tiles face the anvil slantwise, and their capes hang that way.
		List<StackSpreader.Entry> still = withCapes(smithing(15, 12, 2, 0, true), id -> id % 2 == 1 || id == YOU);
		List<StackSpreader.Entry> corners = new ArrayList<>(still);
		int id = 100;
		for (long corner : new long[]{StackRegistry.key(0, 49, 50), StackRegistry.key(0, 51, 50)})
		{
			for (int i = 0; i < 4; i++)
			{
				corners.add(new StackSpreader.Entry(id, corner, false, facingTheAnvil(corner), true, id++ % 2 == 1));
			}
		}
		for (List<StackSpreader.Entry> crowd : java.util.Arrays.asList(still, corners))
		{
			CrowdPlanner planner = new CrowdPlanner();
			CrowdPlanner.Plan plan = null;
			for (int t = 1; t <= 5; t++)
			{
				plan = atTheAnvil(planner, crowd, t);
				assertStandingRoundTheAnvil("tick " + t, plan, crowd);
				// Drawn: everyone given a spot, you, and whoever waits in the middle of a tile in sight.
				Map<Integer, double[]> at = drawnAt(plan, crowd);
				Set<Integer> placed = spots(plan).keySet();
				for (StackSpreader.Entry e : crowd)
				{
					if (!placed.contains(e.id) && !e.local && plan.middleOutOfSight.contains(e.tile))
					{
						at.remove(e.id);
					}
				}
				Assert.assertEquals("tick " + t, new ArrayList<>(), inTheWayOfCapes(plan, crowd, at));
			}
			Assert.assertTrue("only " + plan.placements.size() + " of " + crowd.size() + " stand round the anvil", plan.placements.size() >= crowd.size() * 3 / 4);
		}
	}

	@Test
	public void capesDontKeepAnyoneFromStandingBesideThem()
	{
		// A cape is only in the way of whoever stands behind it: side by side round the fire, a body's
		// width apart, as many stand right at it with everyone in a cape as with nobody in one.
		CrowdPlanner.Surroundings campfire = fireAt5050(openFlags(), false);
		int[] nearest = new int[2];
		for (int caped = 0; caped <= 1; caped++)
		{
			boolean capes = caped == 1;
			List<StackSpreader.Entry> still = withCapes(busyCampfire(12, 8, true), who -> capes);
			CrowdPlanner planner = new CrowdPlanner();
			CrowdPlanner.Plan plan = null;
			for (int t = 1; t <= 5; t++)
			{
				plan = atTheFire(planner, still, t, campfire);
			}
			for (double[] a : drawnAsThePluginDoes(plan, still).values())
			{
				nearest[caped] += fromTheFiresTile(a[0], a[1]) < CrowdPlanner.FIRE_MARGIN + CrowdPlanner.OBJECT_RING_STEP / 2.0 ? 1 : 0;
			}
		}
		Assert.assertTrue("right at the fire: " + nearest[0] + " without capes, " + nearest[1] + " with", nearest[1] >= nearest[0] && nearest[0] >= 10);
	}

	@Test
	public void aCapeHangsBehindItsWearerWhicheverWayTheyFace()
	{
		// Not everyone round the anvil faces it squarely: some are turned 30 or 40 degrees off it, some
		// to the door, and those on the corners look past it. The plugin turns each of them to look
		// where they were looking, so a cape hangs behind its wearer as they face, not as they would
		// facing the anvil, and nobody is drawn there either.
		List<StackSpreader.Entry> still = new ArrayList<>();
		for (StackSpreader.Entry e : smithing(15, 12, 2, 0, true))
		{
			int turn = e.local ? 0 : e.id % 4 == 1 ? 228 : e.id % 4 == 2 ? -171 : e.id % 8 == 3 ? 1024 : 0;
			still.add(new StackSpreader.Entry(e.id, e.tile, e.local, (e.orientation + turn + 2048) % 2048, e.busy, e.id % 2 == 1 || e.local));
		}
		int id = 100;
		for (long corner : new long[]{StackRegistry.key(0, 49, 52), StackRegistry.key(0, 51, 52), StackRegistry.key(0, 49, 50)})
		{
			for (int i = 0; i < 3; i++)
			{
				int turn = (i - 1) * 142;
				still.add(new StackSpreader.Entry(id, corner, false, (facingTheAnvil(corner) + turn + 2048) % 2048, false, id++ % 2 == 0));
			}
		}
		CrowdPlanner planner = new CrowdPlanner();
		CrowdPlanner.Plan plan = null;
		for (int t = 1; t <= 6; t++)
		{
			plan = atTheAnvil(planner, still, t);
			Map<Integer, double[]> at = drawnAt(plan, still);
			Set<Integer> placed = spots(plan).keySet();
			for (StackSpreader.Entry e : still)
			{
				if (!placed.contains(e.id) && !e.local && plan.middleOutOfSight.contains(e.tile))
				{
					at.remove(e.id);
				}
			}
			assertNobodyInsideAnybody("tick " + t, at);
			Assert.assertEquals("tick " + t, new ArrayList<>(), inTheWayOfCapes(plan, still, at));
		}
		// Fewer than when all face it: the place in front of anyone turned away is in the way of their cape.
		Assert.assertTrue("only " + plan.placements.size() + " of " + still.size() + " stand round the anvil", plan.placements.size() >= still.size() * 2 / 3);
	}

	@Test
	public void nobodyStandsWhereYourCapeHangsWithGiveMeASpotOff()
	{
		// With Give me a spot off you're drawn where you stand, in the middle of your tile, among the
		// crowd round the fire or the anvil. Your cape hangs behind you all the same, and the ones who
		// stood there kept their spots in its way.
		List<List<StackSpreader.Entry>> scenes = java.util.Arrays.asList(withCapes(busyCampfire(12, 8, true), id -> id == YOU || id % 3 == 0),
			withCapes(smithing(15, 12, 6, 6, true), id -> id == YOU || id % 3 == 0));
		for (int k = 0; k < scenes.size(); k++)
		{
			List<StackSpreader.Entry> still = scenes.get(k);
			CrowdPlanner.Surroundings around = k == 0 ? fireAt5050(openFlags(), false) : smithy();
			CrowdPlanner planner = new CrowdPlanner();
			for (int t = 1; t <= 8; t++)
			{
				CrowdPlanner.Plan plan = planner.plan(still, q -> true, PersonalSpaceConfig.SPACING_WIDE, PersonalSpaceConfig.MAX_STACK, true, false, t, around);
				if (t >= 3)
				{
					Map<Integer, double[]> at = drawnAsThePluginDoes(plan, still);
					assertNobodyInsideAnybody((k == 0 ? "fire" : "anvil") + ", tick " + t, at);
					Assert.assertEquals((k == 0 ? "fire" : "anvil") + ", tick " + t, new ArrayList<>(), inTheWayOfCapes(plan, still, at));
				}
			}
		}
	}
}

package com.grant9008.personalspace;

import java.lang.reflect.Array;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.nio.IntBuffer;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Projection;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import org.junit.Assert;
import org.junit.Assume;
import org.junit.Test;

/**
 * Handing kept people to the renderer with "Depth between players" (see {@link DepthSpacer}),
 * checked against RuneLite's real GPU plugin, run without a screen: its drawTemp, model uploaders
 * and VAO ranges are the real ones, only the GL buffer is plain memory. If the GPU plugin's
 * insides have changed shape, those tests are skipped; if they're there but behave differently,
 * they fail, as depth may then not work in the game either.
 */
public class DepthHandOverTest
{
	private static final int X = 6400;
	private static final int Z = 6400;

	/** The camera as the sorted path sees it: 1000 in front of everyone, looking along +z. */
	private static final Projection CAMERA = new Projection()
	{
		@Override
		public float[] project(float x, float y, float z)
		{
			return project(x, y, z, new float[3]);
		}

		@Override
		public float[] project(float x, float y, float z, float[] out)
		{
			out[0] = x - X;
			out[1] = y;
			out[2] = z - Z + 1000;
			return out;
		}
	};

	// ---------------------------------------------------------------- the real GPU plugin, offline

	/** RuneLite's GPU plugin with its buffers in memory; null (test skipped) if it's not built as expected. */
	private static final class Gpu
	{
		DrawCallbacks plugin;
		Object vaoO;
		Object vaoA;
		Class<?> vaoClass;
		Class<?> vboClass;
		Class<?> rangeClass;
		final List<Integer> modes = new ArrayList<>();
		/** Where each object handed over says it is, and the model behind its renderable. */
		final List<Integer> xs = new ArrayList<>();
		final List<Model> models = new ArrayList<>();

		/** Render method of each range of drawn models so far, and how many ints each holds. */
		List<int[]> ranges() throws ReflectiveOperationException
		{
			List<int[]> out = new ArrayList<>();
			int count = field(vaoClass, "off").getInt(vaoO);
			Object[] ranges = (Object[]) field(vaoClass, "ranges").get(vaoO);
			int start = 0;
			for (int i = 0; i < count; i++)
			{
				int end = field(rangeClass, "endpos").getInt(ranges[i]);
				out.add(new int[]{field(rangeClass, "renderMethod").getByte(ranges[i]), end - start});
				start = end;
			}
			return out;
		}

		String methods() throws ReflectiveOperationException
		{
			StringBuilder b = new StringBuilder();
			for (int[] r : ranges())
			{
				b.append(b.length() == 0 ? "" : " ").append(r[0]);
			}
			return b.toString();
		}

		int alphaInts() throws ReflectiveOperationException
		{
			Object vbo = field(vaoClass, "vbo").get(vaoA);
			return ((IntBuffer) field(vboClass, "vb").get(vbo)).position();
		}
	}

	private static Field field(Class<?> c, String name) throws NoSuchFieldException
	{
		Field f = c.getDeclaredField(name);
		f.setAccessible(true);
		return f;
	}

	private static Constructor<?> ctor(Class<?> c, Class<?>... types) throws NoSuchMethodException
	{
		Constructor<?> k = c.getDeclaredConstructor(types);
		k.setAccessible(true);
		return k;
	}

	private static Gpu gpu()
	{
		try
		{
			String p = "net.runelite.client.plugins.gpu.";
			Class<?> gpuClass = Class.forName(SpreadingDrawCallbacks.GPU_PLUGIN);
			Class<?> sceneContext = Class.forName(p + "GpuPlugin$SceneContext");
			Class<?> renderThread = Class.forName(p + "GpuPlugin$RenderThread");
			Class<?> vaoList = Class.forName(p + "VAOList");
			Class<?> uploader = Class.forName(p + "ModelUploader");
			Gpu g = new Gpu();
			g.vaoClass = Class.forName(p + "VAO");
			g.vboClass = Class.forName(p + "VBO");
			g.rangeClass = Class.forName(p + "VAO$Range");
			g.plugin = (DrawCallbacks) ctor(gpuClass).newInstance();
			field(gpuClass, "root").set(g.plugin, ctor(sceneContext, int.class, int.class).newInstance(23, 23));
			Object rt = ctor(renderThread).newInstance();
			Object[] lists = new Object[2];
			Object[] vaos = new Object[2];
			for (int i = 0; i < 2; i++)
			{
				lists[i] = ctor(vaoList, boolean.class).newInstance(false);
				vaos[i] = ctor(g.vaoClass, int.class).newInstance(1 << 20);
				Object vbo = field(g.vaoClass, "vbo").get(vaos[i]);
				field(g.vboClass, "vb").set(vbo, IntBuffer.allocate(1 << 18));
				field(g.vboClass, "mapped").setBoolean(vbo, true);
				@SuppressWarnings("unchecked")
				List<Object> list = (List<Object>) field(vaoList, "vaos").get(lists[i]);
				list.add(vaos[i]);
			}
			field(renderThread, "vaoO").set(rt, lists[0]);
			field(renderThread, "vaoA").set(rt, lists[1]);
			field(renderThread, "modelUploader").set(rt, ctor(uploader).newInstance());
			Object rts = Array.newInstance(renderThread, 1);
			Array.set(rts, 0, rt);
			field(gpuClass, "rts").set(g.plugin, rts);
			RenderCallbackManager callbacks = new RenderCallbackManager();
			callbacks.register(new RenderCallback()
			{
				@Override
				public boolean drawObject(Scene scene, TileObject object)
				{
					Renderable r = ((GameObject) object).getRenderable();
					g.modes.add(r.getRenderMode());
					g.xs.add(((GameObject) object).getX());
					g.models.add(r.getModel());
					return true;
				}
			});
			field(gpuClass, "renderCallbackManager").set(g.plugin, callbacks);
			g.vaoO = vaos[0];
			g.vaoA = vaos[1];
			g.ranges();
			g.alphaInts();
			return g;
		}
		catch (ReflectiveOperationException | LinkageError | ClassCastException | IllegalArgumentException e)
		{
			Assume.assumeNoException("the GPU plugin's insides have changed shape", e);
			return null;
		}
	}

	// ---------------------------------------------------------------- the shim

	/** Model ids the fake cache has, and how often it was asked. */
	private final Map<Integer, ModelData> cache = new HashMap<>();
	private int cacheReads;
	/** The last shim's frame counter. */
	private OffsetTable offsets;

	private SpreadingDrawCallbacks shim(DrawCallbacks delegate)
	{
		Map<String, Object> answers = new HashMap<>();
		answers.put("loadModelData", (Function<Object[], Object>) args ->
		{
			cacheReads++;
			return cache.get((Integer) args[0]);
		});
		answers.put("isClientThread", true);
		Client client = FakeMeshes.fake(Client.class, answers);
		offsets = new OffsetTable();
		StackRegistry stacks = new StackRegistry();
		return new SpreadingDrawCallbacks(client, offsets, stacks, new StackProbe(client, offsets, stacks), new RenderCallbackManager(), delegate);
	}

	/** Someone as the game hands them over, standing {@code dx} east of the middle. */
	private static final class Person
	{
		final Model model;
		final GameObject object;
		final int x;

		Person(int faces, int dx)
		{
			FakeMeshes.Mesh mesh = FakeMeshes.strip(faces);
			mesh.priorities = new byte[faces];
			model = FakeMeshes.model(mesh, 2000);
			x = X + dx;
			object = FakeMeshes.object(FakeMeshes.player(model), x, Z);
		}
	}

	private static void handOver(SpreadingDrawCallbacks s, Person p, boolean depth)
	{
		s.handOver(CAMERA, FakeMeshes.scene(), p.object, null, 0, p.model, 0, p.x, 0, Z, depth);
	}

	{
		cache.put(DepthSpacer.CANDIDATES[0], FakeMeshes.modelData(FakeMeshes.strip(16), false));
	}

	// ---------------------------------------------------------------- tests

	@Test
	public void theGameDrawsARunOfPeopleAllInOneGo() throws Exception
	{
		Gpu g = gpu();
		Person a = new Person(6, 0);
		Person b = new Person(6, 30);
		g.plugin.drawTemp(CAMERA, FakeMeshes.scene(), a.object, a.model, 0, a.x, 0, Z);
		g.plugin.drawTemp(CAMERA, FakeMeshes.scene(), b.object, b.model, 0, b.x, 0, Z);
		// One range drawn with render method 2: every colour with no depth written, then every depth.
		Assert.assertEquals("2", g.methods());
	}

	@Test
	public void withDepthEachPersonIsDrawnOnTheirOwnInTheirOwnLayering() throws Exception
	{
		Gpu g = gpu();
		SpreadingDrawCallbacks s = shim(g.plugin);
		Person a = new Person(6, 0);
		Person b = new Person(6, 30);
		handOver(s, a, true);
		handOver(s, b, true);
		// Each person a range of their own, still drawn as a person (method 2: the game's layering),
		// each after a spacer's range of one face (18 ints) that ends the run before it.
		Assert.assertEquals("0 2 0 2", g.methods());
		List<int[]> r = g.ranges();
		Assert.assertEquals(18, r.get(0)[1]);
		Assert.assertEquals(18, r.get(2)[1]);
		Assert.assertEquals("nothing goes down the see-through pass", 0, g.alphaInts());
		Assert.assertEquals(2, s.depthDraws);
		Assert.assertEquals(0, s.depthNoSpacer);
		Assert.assertEquals("the spacer is made once", 1, cacheReads);
		// What other plugins see (Entity Hider and the like): the spacer as something other than a
		// person, and each person just as the game hands them over.
		Assert.assertEquals(List.of(Renderable.RENDERMODE_SORTED, Renderable.RENDERMODE_SORTED_NO_DEPTH,
			Renderable.RENDERMODE_SORTED, Renderable.RENDERMODE_SORTED_NO_DEPTH), g.modes);
	}

	@Test
	public void withoutDepthEveryoneIsDrawnJustAsTheGameDoes() throws Exception
	{
		Gpu g = gpu();
		SpreadingDrawCallbacks s = shim(g.plugin);
		Person a = new Person(6, 0);
		Person b = new Person(6, 30);
		handOver(s, a, false);
		handOver(s, b, false);
		Assert.assertEquals("2", g.methods());
		Assert.assertEquals(0, cacheReads);

		g = gpu();
		s = shim(g.plugin);
		s.depthBetweenPlayers = false;
		handOver(s, a, true);
		handOver(s, b, true);
		Assert.assertEquals("the setting off", "2", g.methods());
		Assert.assertEquals(0, s.depthDraws);
	}

	@Test
	public void someoneOverlappingNobodyJoinsTheRunBeforeThem() throws Exception
	{
		Gpu g = gpu();
		SpreadingDrawCallbacks s = shim(g.plugin);
		handOver(s, new Person(6, 0), false);
		handOver(s, new Person(6, 30), true);
		handOver(s, new Person(6, 60), false);
		Assert.assertEquals("2 0 2", g.methods());
	}

	@Test
	public void withNoSpacerEveryoneIsDrawnAsTheGameDoesAndItIsCounted() throws Exception
	{
		cache.clear();
		Gpu g = gpu();
		SpreadingDrawCallbacks s = shim(g.plugin);
		handOver(s, new Person(6, 0), true);
		handOver(s, new Person(6, 30), true);
		Assert.assertEquals("2", g.methods());
		Assert.assertEquals(2, s.depthNoSpacer);
		Assert.assertEquals(0, s.depthDraws);
		Assert.assertEquals("every candidate tried, once a frame", DepthSpacer.CANDIDATES.length, cacheReads);
		// Retried each frame a while (the cache may not have it yet), then given up on.
		for (int i = 0; i < SpreadingDrawCallbacks.SPACER_TRIES + 10; i++)
		{
			offsets.advance(0.02f);
			handOver(s, new Person(2, 0), true);
			handOver(s, new Person(2, 30), true);
		}
		Assert.assertEquals(SpreadingDrawCallbacks.SPACER_TRIES * DepthSpacer.CANDIDATES.length, cacheReads);
	}

	@Test
	public void aSpacerThatTurnsUpLaterIsUsedFromThen() throws Exception
	{
		ModelData later = cache.remove(DepthSpacer.CANDIDATES[0]);
		Gpu g = gpu();
		SpreadingDrawCallbacks s = shim(g.plugin);
		handOver(s, new Person(6, 0), true);
		cache.put(DepthSpacer.CANDIDATES[0], later);
		handOver(s, new Person(6, 30), true);
		Assert.assertEquals("not tried again in the same frame", "2", g.methods());
		offsets.advance(0.02f);
		handOver(s, new Person(6, 60), true);
		Assert.assertEquals("2 0 2", g.methods());
	}

	@Test
	public void drawnAsAnythingButAPersonABodyLosesTheGamesLayering() throws Exception
	{
		// Why 1.9.17 drew gear wrong: handed over as something other than a person, a body goes down
		// the opaque path, every face in model order, by depth alone (method 0), priorities unused.
		Gpu g = gpu();
		Person a = new Person(6, 0);
		g.plugin.drawTemp(CAMERA, FakeMeshes.scene(), new DepthTestedObject().wrap(a.object), a.model, 0, a.x, 0, Z);
		Assert.assertEquals("0", g.methods());
		Assert.assertEquals("all 6 faces, none sorted or culled", 6 * 18, g.ranges().get(0)[1]);
	}

	@Test
	public void aSpacerHandedOverAsAPersonWouldNotEndTheRun() throws Exception
	{
		// The sorted path drops a face of no size, so nothing is written and the run goes on.
		Gpu g = gpu();
		Person a = new Person(6, 0);
		Person b = new Person(6, 30);
		Model spacer = DepthSpacer.build(cache.get(DepthSpacer.CANDIDATES[0]));
		Assert.assertNotNull(spacer);
		g.plugin.drawTemp(CAMERA, FakeMeshes.scene(), a.object, a.model, 0, a.x, 0, Z);
		g.plugin.drawTemp(CAMERA, FakeMeshes.scene(), FakeMeshes.object(FakeMeshes.player(spacer), X, Z), spacer, 0, X, 0, Z);
		g.plugin.drawTemp(CAMERA, FakeMeshes.scene(), b.object, b.model, 0, b.x, 0, Z);
		Assert.assertEquals("2", g.methods());
	}

	@Test
	public void lentSomeonesObjectTheyAreStillDrawnAsThemselves() throws Exception
	{
		Gpu g = gpu();
		SpreadingDrawCallbacks s = shim(g.plugin);
		Person lender = new Person(6, 0);
		Person who = new Person(6, 30);
		s.handOver(CAMERA, FakeMeshes.scene(), lender.object, who.object.getRenderable(), 0, who.model, 0, who.x, 0, Z, true);
		Assert.assertEquals("0 2", g.methods());
		Assert.assertEquals(List.of(Renderable.RENDERMODE_SORTED, Renderable.RENDERMODE_SORTED_NO_DEPTH), g.modes);
		// The spacer too stands in for the one drawn, where they're drawn: never the lender, whose
		// model rebuilt by another plugin would overwrite the one about to be drawn.
		Assert.assertEquals(List.of(who.x, who.x), g.xs);
		Assert.assertEquals(List.of(who.model, who.model), g.models);
	}

	@Test
	public void aSpacerTheRendererChokesOnIsDroppedAndThePersonStillDrawn() throws Exception
	{
		Gpu g = gpu();
		List<Model> drawn = new ArrayList<>();
		Map<String, Object> answers = new HashMap<>();
		answers.put("drawTemp", (Function<Object[], Object>) args ->
		{
			Model m = (Model) args[3];
			if (((GameObject) args[2]).getRenderable().getRenderMode() != Renderable.RENDERMODE_SORTED_NO_DEPTH)
			{
				throw new IllegalStateException("choked");
			}
			drawn.add(m);
			return null;
		});
		DrawCallbacks choking = FakeMeshes.fake(DrawCallbacks.class, answers);
		// The shim only sends spacers to the GPU plugin, so hand it the real one and swap the
		// delegate afterwards.
		SpreadingDrawCallbacks s = shim(g.plugin);
		Field delegate = SpreadingDrawCallbacks.class.getDeclaredField("delegate");
		delegate.setAccessible(true);
		delegate.set(s, choking);
		Person a = new Person(6, 0);
		handOver(s, a, true);
		Assert.assertEquals(List.of(a.model), drawn);
		Assert.assertEquals(1, s.depthNoSpacer);
		offsets.advance(0.02f);
		handOver(s, a, true);
		Assert.assertEquals(2, drawn.size());
		Assert.assertEquals("not tried again", 2, s.depthNoSpacer);
		Assert.assertEquals(1, cacheReads);
	}

	@Test
	public void inAnyOtherRendererEveryoneIsDrawnAsTheGameDoes()
	{
		// 117 HD draws all its people in one batch a spacer can't split: nothing is sent but them.
		List<Object[]> calls = new ArrayList<>();
		Map<String, Object> answers = new HashMap<>();
		answers.put("drawTemp", (Function<Object[], Object>) args ->
		{
			GameObject o = (GameObject) args[2];
			calls.add(new Object[]{o, o.getRenderable().getRenderMode(), args[3]});
			return null;
		});
		DrawCallbacks other = FakeMeshes.fake(DrawCallbacks.class, answers);
		SpreadingDrawCallbacks s = shim(other);
		Person a = new Person(6, 0);
		handOver(s, a, true);
		Assert.assertEquals(1, calls.size());
		Assert.assertSame(a.object, calls.get(0)[0]);
		Assert.assertEquals(Renderable.RENDERMODE_SORTED_NO_DEPTH, calls.get(0)[1]);
		Assert.assertSame(a.model, calls.get(0)[2]);
		Assert.assertEquals(0, cacheReads);
		Assert.assertEquals(0, s.depthDraws + s.depthNoSpacer);
	}
}

package com.grant9008.personalspace;

import java.util.Arrays;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import org.junit.Assert;
import org.junit.Test;

/** The invisible model drawn between two people with depth (see {@link DepthSpacer}). */
public class DepthSpacerTest
{
	@Test
	public void aSpacerHasOneFaceOfNoSizeAndNothingSeeThrough()
	{
		Model spacer = DepthSpacer.build(FakeMeshes.modelData(FakeMeshes.strip(16), false));
		Assert.assertNotNull(spacer);
		Assert.assertTrue(DepthSpacer.usable(spacer));
		Assert.assertNull("no see-through faces: the GPU plugin's opaque path", spacer.getFaceTransparencies());
		Assert.assertEquals(0, spacer.getTransparency());
		int shown = 0;
		for (int f = 0; f < spacer.getFaceCount(); f++)
		{
			if (spacer.getFaceColors3()[f] != DepthSpacer.HIDDEN)
			{
				shown++;
				int a = spacer.getFaceIndices1()[f];
				int b = spacer.getFaceIndices2()[f];
				int c = spacer.getFaceIndices3()[f];
				Assert.assertEquals(spacer.getVerticesX()[a], spacer.getVerticesX()[b], 0);
				Assert.assertEquals(spacer.getVerticesX()[a], spacer.getVerticesX()[c], 0);
				Assert.assertEquals(spacer.getVerticesY()[a], spacer.getVerticesY()[c], 0);
				Assert.assertEquals(spacer.getVerticesZ()[b], spacer.getVerticesZ()[c], 0);
			}
		}
		Assert.assertEquals("one face, so only 3 vertices are sent", 1, shown);
	}

	@Test
	public void theCachesModelIsNeverChanged()
	{
		FakeMeshes.Mesh mesh = FakeMeshes.strip(16);
		float[] x = mesh.x.clone();
		float[] y = mesh.y.clone();
		float[] z = mesh.z.clone();
		int[] a = mesh.a.clone();
		int[] b = mesh.b.clone();
		int[] c = mesh.c.clone();
		ModelData data = FakeMeshes.modelData(mesh, false);
		// Lit before and after, as the game does with the same model: its colours stay its own.
		Model before = data.light();
		int[] beforeColors = before.getFaceColors3().clone();
		Model spacer = DepthSpacer.build(data);
		Assert.assertNotNull(spacer);
		Assert.assertArrayEquals(x, mesh.x, 0);
		Assert.assertArrayEquals(y, mesh.y, 0);
		Assert.assertArrayEquals(z, mesh.z, 0);
		Assert.assertArrayEquals(a, mesh.a);
		Assert.assertArrayEquals(b, mesh.b);
		Assert.assertArrayEquals(c, mesh.c);
		Assert.assertArrayEquals(beforeColors, before.getFaceColors3());
		Assert.assertArrayEquals(beforeColors, data.light().getFaceColors3());
		Assert.assertNotSame(mesh.x, spacer.getVerticesX());
	}

	@Test
	public void modelDataWhoseVerticesCantBeCopiedIsntUsed()
	{
		// cloneVertices handing back the cache's own arrays: moving them would move the game's model.
		FakeMeshes.Mesh mesh = FakeMeshes.strip(8);
		ModelData stubborn = FakeMeshes.fake(ModelData.class, new java.util.HashMap<String, Object>()
		{
			{
				ModelData real = FakeMeshes.modelData(mesh, false);
				put("getFaceCount", 8);
				put("getVerticesCount", mesh.x.length);
				put("getVerticesX", mesh.x);
				put("getVerticesY", mesh.y);
				put("getVerticesZ", mesh.z);
				put("shallowCopy", real);
				put("light", (java.util.function.Function<Object[], Object>) args -> real.light());
			}
		});
		float[] x = mesh.x.clone();
		Assert.assertNull(DepthSpacer.build(stubborn));
		Assert.assertArrayEquals(x, mesh.x, 0);
	}

	@Test
	public void seeThroughTexturedEmptyOrMissingModelsArentUsed()
	{
		Assert.assertNull(DepthSpacer.build(null));
		FakeMeshes.Mesh alpha = FakeMeshes.strip(4);
		alpha.alphas = new byte[4];
		Assert.assertNull("all-zero transparencies still take the sorted path", DepthSpacer.build(FakeMeshes.modelData(alpha, false)));
		FakeMeshes.Mesh textured = FakeMeshes.strip(4);
		textured.textures = new short[]{-1, -1, 7, -1};
		Assert.assertNull(DepthSpacer.build(FakeMeshes.modelData(textured, false)));
		FakeMeshes.Mesh untextured = FakeMeshes.strip(4);
		untextured.textures = new short[]{-1, -1, -1, -1};
		Assert.assertNotNull("a texture array with no texture in it is fine", DepthSpacer.build(FakeMeshes.modelData(untextured, false)));
		FakeMeshes.Mesh empty = FakeMeshes.strip(0);
		Assert.assertNull(DepthSpacer.build(FakeMeshes.modelData(empty, false)));
	}

	@Test
	public void onlyOneInvisibleOpaqueFaceIsUsable()
	{
		FakeMeshes.Mesh mesh = FakeMeshes.strip(3);
		Arrays.fill(mesh.x, 0);
		Arrays.fill(mesh.y, 0);
		Arrays.fill(mesh.z, 0);
		Model m = FakeMeshes.model(mesh, 1000);
		Assert.assertFalse("three faces shown", DepthSpacer.usable(m));
		m.getFaceColors3()[1] = DepthSpacer.HIDDEN;
		m.getFaceColors3()[2] = DepthSpacer.HIDDEN;
		Assert.assertTrue(DepthSpacer.usable(m));
		mesh.x[2] = 1;
		Assert.assertFalse("a face with a size to it", DepthSpacer.usable(m));
		mesh.x[2] = 0;
		Arrays.fill(m.getFaceColors3(), DepthSpacer.HIDDEN);
		Assert.assertFalse("nothing sent at all: the run isn't ended", DepthSpacer.usable(m));
		m.getFaceColors3()[0] = DepthSpacer.FLAT;
		Assert.assertTrue(DepthSpacer.usable(m));
		mesh.alphas = new byte[3];
		Model seeThrough = FakeMeshes.model(mesh, 1000);
		seeThrough.getFaceColors3()[1] = DepthSpacer.HIDDEN;
		seeThrough.getFaceColors3()[2] = DepthSpacer.HIDDEN;
		Assert.assertFalse("see-through faces: the sorted path", DepthSpacer.usable(seeThrough));
		Assert.assertFalse(DepthSpacer.usable(null));
	}

	@Test
	public void thereAreModelsToMakeItFrom()
	{
		Assert.assertTrue(DepthSpacer.CANDIDATES.length > 0);
	}
}

package com.grant9008.personalspace;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GameObject;
import net.runelite.api.Renderable;
import org.junit.Assert;
import org.junit.Test;

/** The stand-in object a depth spacer, or someone lent another's object, is handed over with. */
public class DepthTestedObjectTest
{
	/** A proxy recording every call and answering each method with something of its own. */
	private static final class Recorder
	{
		final List<String> calls = new ArrayList<>();
		final Map<String, Object> answers = new HashMap<>();

		<T> T proxy(Class<T> type)
		{
			return type.cast(Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{type}, (p, m, args) ->
			{
				switch (m.getName())
				{
					case "equals":
						return p == args[0];
					case "hashCode":
						return System.identityHashCode(p);
					case "toString":
						return "recorder";
					default:
						calls.add(m.getName() + Arrays.toString(args == null ? new Object[0] : args));
						return answers.computeIfAbsent(m.toGenericString(), k -> answerFor(m));
				}
			}));
		}
	}

	/** Something distinct for a method to answer with. */
	private static Object answerFor(Method m)
	{
		Class<?> r = m.getReturnType();
		int seed = Math.abs(m.toGenericString().hashCode() % 1000) + 3;
		if (r == void.class)
		{
			return null;
		}
		if (r == int.class)
		{
			return seed;
		}
		if (r == long.class)
		{
			return (long) seed * 1_000_003L;
		}
		if (r == boolean.class)
		{
			return true;
		}
		if (r == String.class)
		{
			return m.getName();
		}
		if (r.isInterface())
		{
			return FakeMeshes.fake(r, new HashMap<>());
		}
		for (Constructor<?> c : r.getConstructors())
		{
			if (Arrays.stream(c.getParameterTypes()).allMatch(t -> t == int.class))
			{
				Object[] args = new Object[c.getParameterCount()];
				Arrays.fill(args, seed);
				try
				{
					return c.newInstance(args);
				}
				catch (ReflectiveOperationException e)
				{
					throw new AssertionError(e);
				}
			}
		}
		throw new AssertionError("no answer for " + m);
	}

	private static Object[] argsFor(Method m)
	{
		Object[] args = new Object[m.getParameterCount()];
		Class<?>[] types = m.getParameterTypes();
		for (int i = 0; i < args.length; i++)
		{
			args[i] = types[i] == int.class ? 17 + i : types[i] == String.class ? "text" : null;
		}
		return args;
	}

	private static List<Method> methodsOf(Class<?> type)
	{
		List<Method> out = new ArrayList<>();
		for (Method m : type.getMethods())
		{
			if (!Modifier.isStatic(m.getModifiers()) && !m.isDefault())
			{
				out.add(m);
			}
		}
		Assert.assertFalse(out.isEmpty());
		return out;
	}

	@Test
	public void wrappedEveryObjectCallButTheRenderableGoesToTheRealObject() throws Exception
	{
		Recorder inner = new Recorder();
		GameObject real = inner.proxy(GameObject.class);
		GameObject wrapped = new DepthTestedObject().wrap(real);
		inner.calls.clear();
		for (Method m : methodsOf(GameObject.class))
		{
			if (m.getName().equals("getRenderable"))
			{
				continue;
			}
			Object[] args = argsFor(m);
			inner.calls.clear();
			Object got = m.invoke(wrapped, args);
			Assert.assertEquals(m.getName(), Arrays.asList(m.getName() + Arrays.toString(args)), inner.calls);
			Assert.assertEquals(m.getName(), m.invoke(real, args), got);
		}
	}

	@Test
	public void wrappedItsRenderableIsTheRealOneButForTheRenderMode() throws Exception
	{
		Recorder body = new Recorder();
		Renderable person = body.proxy(Renderable.class);
		body.answers.put(Renderable.class.getMethod("getRenderMode").toGenericString(), Renderable.RENDERMODE_SORTED_NO_DEPTH);
		GameObject real = FakeMeshes.object(person, 1, 2);
		Renderable r = new DepthTestedObject().wrap(real).getRenderable();
		Assert.assertNotSame(person, r);
		Assert.assertNotEquals("not drawn as a person: the GPU plugin's opaque path",
			Renderable.RENDERMODE_SORTED_NO_DEPTH, r.getRenderMode());
		Assert.assertEquals(Renderable.RENDERMODE_SORTED, r.getRenderMode());
		for (Method m : methodsOf(Renderable.class))
		{
			if (m.getName().equals("getRenderMode"))
			{
				continue;
			}
			Object[] args = argsFor(m);
			body.calls.clear();
			Object got = m.invoke(r, args);
			Assert.assertEquals(m.getName(), Arrays.asList(m.getName() + Arrays.toString(args)), body.calls);
			Assert.assertEquals(m.getName(), m.invoke(person, args), got);
		}
	}

	@Test
	public void lentThePersonIsHandedOverAsTheyAreWhereTheyStand() throws Exception
	{
		Recorder lender = new Recorder();
		GameObject lendersObject = lender.proxy(GameObject.class);
		Renderable who = FakeMeshes.player(null);
		GameObject lent = new DepthTestedObject().lend(lendersObject, who, 640, 896, 2);
		Assert.assertSame("drawn as the person they are, with their own render mode", who, lent.getRenderable());
		Assert.assertEquals(Renderable.RENDERMODE_SORTED_NO_DEPTH, lent.getRenderable().getRenderMode());
		Assert.assertEquals(640, lent.getX());
		Assert.assertEquals(896, lent.getY());
		Assert.assertEquals(2, lent.getPlane());
		for (Method m : methodsOf(GameObject.class))
		{
			String n = m.getName();
			if (n.equals("getRenderable") || n.equals("getX") || n.equals("getY") || n.equals("getPlane"))
			{
				continue;
			}
			Object[] args = argsFor(m);
			lender.calls.clear();
			Object got = m.invoke(lent, args);
			Assert.assertEquals(n, Arrays.asList(n + Arrays.toString(args)), lender.calls);
			Assert.assertEquals(n, m.invoke(lendersObject, args), got);
		}
	}

	@Test
	public void lentAsOtherItIsTheLentPersonWhereTheyStandButNotAsAPerson() throws Exception
	{
		Recorder body = new Recorder();
		Renderable who = body.proxy(Renderable.class);
		body.answers.put(Renderable.class.getMethod("getRenderMode").toGenericString(), Renderable.RENDERMODE_SORTED_NO_DEPTH);
		GameObject lendersObject = FakeMeshes.object(FakeMeshes.player(null), 100, 200);
		DepthTestedObject o = new DepthTestedObject();
		GameObject stand = o.lendAsOther(lendersObject, who, 640, 896, 2);
		Assert.assertNotSame(who, stand.getRenderable());
		Assert.assertEquals(Renderable.RENDERMODE_SORTED, stand.getRenderable().getRenderMode());
		Assert.assertEquals(640, stand.getX());
		Assert.assertEquals(896, stand.getY());
		Assert.assertEquals(2, stand.getPlane());
		body.calls.clear();
		Object model = stand.getRenderable().getModel();
		Assert.assertEquals("the lent person's own model", Arrays.asList("getModel[]"), body.calls);
		Assert.assertSame(who.getModel(), model);
		// and the next call, lending them as they are, hands them over as the person
		Assert.assertSame(who, o.lend(lendersObject, who, 640, 896, 2).getRenderable());
	}

	@Test
	public void reusedEachCallForgetsTheLastOne()
	{
		DepthTestedObject o = new DepthTestedObject();
		Renderable a = FakeMeshes.player(null);
		Renderable b = FakeMeshes.player(null);
		GameObject first = FakeMeshes.object(a, 100, 200);
		GameObject second = FakeMeshes.object(b, 300, 400);
		o.lend(first, b, 5, 6, 1);
		o.wrap(second);
		Assert.assertEquals(300, o.getX());
		Assert.assertEquals(400, o.getY());
		Assert.assertEquals(0, o.getPlane());
		Assert.assertEquals(Renderable.RENDERMODE_SORTED, o.getRenderable().getRenderMode());
		o.lend(first, b, 5, 6, 1);
		Assert.assertSame(b, o.getRenderable());
		Assert.assertEquals(5, o.getX());
		o.wrap(first);
		Assert.assertEquals(100, o.getX());
		Assert.assertNotSame(a, o.getRenderable());
	}

	@Test
	public void aPersonWithoutARenderableHasNone()
	{
		GameObject real = FakeMeshes.object(null, 1, 2);
		Assert.assertNull(new DepthTestedObject().wrap(real).getRenderable());
		Assert.assertNull(new DepthTestedObject().lend(real, null, 1, 2, 0).getRenderable());
	}
}

package com.grant9008.personalspace;

import org.junit.Assert;
import org.junit.Test;

/** With "Draw me in front" and depth, who is drawn in one run with you (see SpreadingDrawCallbacks.drawKept). */
public class DrawMeInFrontRunTest
{
	private static SpreadingDrawCallbacks.Kept at(int x, int z)
	{
		SpreadingDrawCallbacks.Kept k = new SpreadingDrawCallbacks.Kept();
		k.x = x;
		k.z = z;
		return k;
	}

	@Test
	public void theRunStartsAtTheFirstOfYourCrowdDrawn()
	{
		SpreadingDrawCallbacks.Kept you = at(1000, 1000);
		SpreadingDrawCallbacks.Kept[] kept = {
			at(5000, 5000), // far off: drawn with depth as usual
			at(1000 + SpreadingDrawCallbacks.NEAR_YOU, 1000 - 50), // in your crowd: the run starts here
			at(3000, 1000), // drawn between, not in your crowd: in the run too, so you're over everyone in it
			at(1000, 1100),
			you,
			at(1100, 1000), // after you: depth as usual
		};
		int youAt = SpreadingDrawCallbacks.indexOf(kept, kept.length, you);
		Assert.assertEquals(4, youAt);
		Assert.assertEquals(1, SpreadingDrawCallbacks.frontRunStart(kept, youAt));
	}

	@Test
	public void withNobodyOfYourCrowdBeforeYouTheRunIsYouAlone()
	{
		SpreadingDrawCallbacks.Kept you = at(1000, 1000);
		SpreadingDrawCallbacks.Kept[] kept = {at(1000 + SpreadingDrawCallbacks.NEAR_YOU + 1, 1000), you};
		Assert.assertEquals(1, SpreadingDrawCallbacks.frontRunStart(kept, 1));
		Assert.assertEquals(-1, SpreadingDrawCallbacks.indexOf(kept, 2, null));
		Assert.assertEquals(-1, SpreadingDrawCallbacks.indexOf(kept, 1, you));
	}
}

package com.grant9008.personalspace;

import org.junit.Assert;
import org.junit.Test;

public class DrawOrderTest
{
	@Test
	public void swingingTheCameraDoesntSwapPeopleStandingSideBySide()
	{
		// Last frame: 0 drawn first (farther), then 1. The camera has swung a little and 1 is now a
		// hair farther: they stay as they were.
		int[] order = {0, 1};
		SpreadingDrawCallbacks.settle(order, new double[]{1000, 1000 + SpreadingDrawCallbacks.SORT_TOLERANCE - 4}, 2, SpreadingDrawCallbacks.SORT_TOLERANCE);
		Assert.assertArrayEquals(new int[]{0, 1}, order);
		// Swung further, 1 is clearly farther now: they swap.
		order = new int[]{0, 1};
		SpreadingDrawCallbacks.settle(order, new double[]{1000, 1000 + SpreadingDrawCallbacks.SORT_TOLERANCE + 8}, 2, SpreadingDrawCallbacks.SORT_TOLERANCE);
		Assert.assertArrayEquals(new int[]{1, 0}, order);
	}

	@Test
	public void someoneNewIsPutWhereTheyBelong()
	{
		// Three already in order, far to near; someone new (last in the list) farther than all of them.
		int[] order = {0, 1, 2, 3};
		SpreadingDrawCallbacks.settle(order, new double[]{1200, 1100, 1000, 1300}, 4, SpreadingDrawCallbacks.SORT_TOLERANCE);
		Assert.assertArrayEquals(new int[]{3, 0, 1, 2}, order);
	}

	@Test
	public void peopleApartOnScreenAreSortedFreelyButOverlappingOnesHold()
	{
		// 0 was drawn first, 1 is now a little farther. Apart on screen: they swap, as nobody can see
		// it. Overlapping: they hold until 1 is clearly farther.
		double[] apart = {0, 1, 0, 1, 1, 5, 6, 0, 1, 1};
		double[] overlapping = {0, 1, 0, 1, 1, 0.5, 1.5, 0, 1, 1};
		double[] distance = {1000, 1010};
		int[] order = {0, 1};
		SpreadingDrawCallbacks.settle(order, distance, 2, SpreadingDrawCallbacks.SORT_TOLERANCE, null, apart);
		Assert.assertArrayEquals(new int[]{1, 0}, order);
		order = new int[]{0, 1};
		SpreadingDrawCallbacks.settle(order, distance, 2, SpreadingDrawCallbacks.SORT_TOLERANCE, null, overlapping);
		Assert.assertArrayEquals(new int[]{0, 1}, order);
		order = new int[]{0, 1};
		SpreadingDrawCallbacks.settle(order, new double[]{1000, 1000 + SpreadingDrawCallbacks.SORT_TOLERANCE + 1}, 2,
			SpreadingDrawCallbacks.SORT_TOLERANCE, null, overlapping);
		Assert.assertArrayEquals("clearly farther now", new int[]{1, 0}, order);
	}

	@Test
	public void someoneNewIsPlacedWhereTheyBelongAtOnce()
	{
		int[] order = {0, 1, 2};
		boolean[] fresh = {false, false, true};
		SpreadingDrawCallbacks.settle(order, new double[]{1000, 990, 1005}, 3, SpreadingDrawCallbacks.SORT_TOLERANCE, fresh, null);
		Assert.assertArrayEquals(new int[]{2, 0, 1}, order);
	}

	@Test
	public void someoneWalkingOffTurnsGraduallyTheShortWayRound()
	{
		Assert.assertEquals(48, SpreadingDrawCallbacks.turnTowards(0, 512, 48));
		Assert.assertEquals(2000, SpreadingDrawCallbacks.turnTowards(0, 1536, 48));
		Assert.assertEquals(510, SpreadingDrawCallbacks.turnTowards(500, 510, 48));
	}

	@Test
	public void aMovingPlayerIsFiledUnderTheTileTheyAreSteppingOnto()
	{
		// Tile (10, 10)'s middle is (1344, 1344).
		Assert.assertArrayEquals(new int[]{10, 10, 10, 11}, SpreadingDrawCallbacks.movingSpan(1344, 1344, 1024)); // north
		Assert.assertArrayEquals(new int[]{10, 9, 10, 10}, SpreadingDrawCallbacks.movingSpan(1344, 1344, 0)); // south
		Assert.assertArrayEquals(new int[]{9, 10, 10, 10}, SpreadingDrawCallbacks.movingSpan(1344, 1344, 512)); // west
		// Half-way east across the edge of tile 10 into 11, stepping on into 12.
		Assert.assertArrayEquals(new int[]{10, 10, 12, 10}, SpreadingDrawCallbacks.movingSpan(1408, 1344, 1536));
		// North-east: both ways.
		Assert.assertArrayEquals(new int[]{10, 10, 11, 11}, SpreadingDrawCallbacks.movingSpan(1344, 1344, 1280));
	}

	@Test
	public void someoneDealingWithAClerkFacesHimFromWhereTheyreDrawn()
	{
		// The game's orientations: 0 faces south, 512 west, 1024 north, 1536 east.
		Assert.assertEquals("clerk due south", 0, SpreadingDrawCallbacks.facingToward(0, 0, 0, -256, -1));
		Assert.assertEquals("clerk due west", 512, SpreadingDrawCallbacks.facingToward(0, 0, -256, 0, -1));
		Assert.assertEquals("clerk due north", 1024, SpreadingDrawCallbacks.facingToward(0, 0, 0, 256, -1));
		Assert.assertEquals("clerk due east", 1536, SpreadingDrawCallbacks.facingToward(0, 0, 256, 0, -1));
		// Drawn a third of a tile east of where they stand, they turn a little west, towards him.
		int turned = SpreadingDrawCallbacks.facingToward(42, 0, 0, 256, -1);
		Assert.assertTrue("turned towards the clerk: " + turned, turned < 1024 && turned > 1024 - 128);
		Assert.assertEquals("on top of them: their own rule", -1, SpreadingDrawCallbacks.facingToward(5, 5, 5, 5, -1));
		Assert.assertEquals("too far: their own rule", -1, SpreadingDrawCallbacks.facingToward(0, 0, 0, 20 * 128, -1));
	}

	@Test
	public void onlySomeoneDrawnAwayFromWhereTheyStandStepsAsideForTheClick()
	{
		Assert.assertTrue("drawn beside the fire", PersonalSpacePlugin.movedAway(7, 85, 0));
		Assert.assertTrue(PersonalSpacePlugin.movedAway(7, 0, -40));
		Assert.assertFalse("standing where they are", PersonalSpacePlugin.movedAway(7, 0, 0));
		Assert.assertFalse("no such player", PersonalSpacePlugin.movedAway(-1, 85, 0));
	}
}

package com.grant9008.personalspace;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;

/**
 * Test stand-ins for the game's models, people and objects, answering only what they're told to and
 * the type's zero for anything else.
 */
final class FakeMeshes
{
	private FakeMeshes()
	{
	}

	/** A proxy of {@code type}: each method named in {@code answers} returns that (a Function is called with the args). */
	@SuppressWarnings("unchecked")
	static <T> T fake(Class<T> type, Map<String, Object> answers)
	{
		return (T) Proxy.newProxyInstance(FakeMeshes.class.getClassLoader(), new Class<?>[]{type}, (proxy, m, args) ->
		{
			if (answers.containsKey(m.getName()))
			{
				Object v = answers.get(m.getName());
				return v instanceof Function ? ((Function<Object[], Object>) v).apply(args) : v;
			}
			switch (m.getName())
			{
				case "equals":
					return proxy == args[0];
				case "hashCode":
					return System.identityHashCode(proxy);
				case "toString":
					return "fake " + type.getSimpleName();
				default:
					return zero(m.getReturnType());
			}
		});
	}

	static Object zero(Class<?> r)
	{
		if (r == boolean.class)
		{
			return false;
		}
		if (r == byte.class)
		{
			return (byte) 0;
		}
		if (r == short.class)
		{
			return (short) 0;
		}
		if (r == char.class)
		{
			return (char) 0;
		}
		if (r == int.class)
		{
			return 0;
		}
		if (r == long.class)
		{
			return 0L;
		}
		if (r == float.class)
		{
			return 0f;
		}
		if (r == double.class)
		{
			return 0d;
		}
		return null;
	}

	/** Mesh arrays: vertices and faces, with optional per-face transparencies and textures. */
	static final class Mesh
	{
		float[] x;
		float[] y;
		float[] z;
		int[] a;
		int[] b;
		int[] c;
		byte[] alphas;
		short[] textures;
		byte[] priorities;

		Mesh copy()
		{
			Mesh m = new Mesh();
			m.x = x;
			m.y = y;
			m.z = z;
			m.a = a;
			m.b = b;
			m.c = c;
			m.alphas = alphas;
			m.textures = textures;
			m.priorities = priorities;
			return m;
		}
	}

	/**
	 * A mesh of {@code faces} triangles: face f has corners (f, f+1, f+2) of a strip of vertices
	 * spread out around (0, 0, 0), so none of them is of no size.
	 */
	static Mesh strip(int faces)
	{
		Mesh m = new Mesh();
		int verts = faces + 2;
		m.x = new float[verts];
		m.y = new float[verts];
		m.z = new float[verts];
		for (int v = 0; v < verts; v++)
		{
			m.x[v] = (v % 2) * 20 - 10;
			m.y[v] = -v * 10;
			m.z[v] = v % 3;
		}
		m.a = new int[faces];
		m.b = new int[faces];
		m.c = new int[faces];
		for (int f = 0; f < faces; f++)
		{
			m.a[f] = f;
			m.b[f] = f + 1;
			m.c[f] = f + 2;
		}
		return m;
	}

	/**
	 * Model data behaving as the client's does: {@code shallowCopy} shares every array (and marks
	 * the vertices shared), {@code cloneVertices} copies shared vertices (or returns itself if they
	 * are its own), {@code light} makes a model on the same vertices with face colours of its own.
	 */
	static ModelData modelData(Mesh mesh, boolean verticesShared)
	{
		Map<String, Object> a = new HashMap<>();
		a.put("getFaceCount", mesh.a.length);
		a.put("getVerticesCount", mesh.x.length);
		a.put("getVerticesX", mesh.x);
		a.put("getVerticesY", mesh.y);
		a.put("getVerticesZ", mesh.z);
		a.put("getFaceIndices1", mesh.a);
		a.put("getFaceIndices2", mesh.b);
		a.put("getFaceIndices3", mesh.c);
		a.put("getFaceTransparencies", mesh.alphas);
		a.put("getFaceTextures", mesh.textures);
		a.put("shallowCopy", (Function<Object[], Object>) args -> modelData(mesh.copy(), true));
		ModelData[] self = new ModelData[1];
		a.put("cloneVertices", (Function<Object[], Object>) args ->
		{
			if (!verticesShared)
			{
				return self[0];
			}
			Mesh m = mesh.copy();
			m.x = mesh.x.clone();
			m.y = mesh.y.clone();
			m.z = mesh.z.clone();
			return modelData(m, false);
		});
		a.put("light", (Function<Object[], Object>) args -> model(mesh, 1000));
		self[0] = fake(ModelData.class, a);
		return self[0];
	}

	/** A lit model on {@code mesh}'s arrays, every face lit {@code color}, with priorities if the mesh has them. */
	static Model model(Mesh mesh, int color)
	{
		int faces = mesh.a.length;
		int[] c1 = new int[faces];
		int[] c2 = new int[faces];
		int[] c3 = new int[faces];
		java.util.Arrays.fill(c1, color);
		java.util.Arrays.fill(c2, color);
		java.util.Arrays.fill(c3, color);
		Map<String, Object> a = new HashMap<>();
		a.put("getFaceCount", faces);
		a.put("getVerticesCount", mesh.x.length);
		a.put("getVerticesX", mesh.x);
		a.put("getVerticesY", mesh.y);
		a.put("getVerticesZ", mesh.z);
		a.put("getFaceIndices1", mesh.a);
		a.put("getFaceIndices2", mesh.b);
		a.put("getFaceIndices3", mesh.c);
		a.put("getFaceColors1", c1);
		a.put("getFaceColors2", c2);
		a.put("getFaceColors3", c3);
		a.put("getFaceTransparencies", mesh.alphas);
		a.put("getFaceTextures", mesh.textures);
		a.put("getFaceRenderPriorities", mesh.priorities);
		a.put("getRadius", 60);
		a.put("getDiameter", 121);
		return fake(Model.class, a);
	}

	/** A player as the game hands them over: {@link Renderable#RENDERMODE_SORTED_NO_DEPTH}, with this model. */
	static Player player(Model model)
	{
		Map<String, Object> a = new HashMap<>();
		a.put("getRenderMode", Renderable.RENDERMODE_SORTED_NO_DEPTH);
		a.put("getModel", model);
		a.put("getModelHeight", 200);
		return fake(Player.class, a);
	}

	/** The object the game draws someone with, at (x, y) on plane 0. */
	static GameObject object(Renderable renderable, int x, int y)
	{
		Map<String, Object> a = new HashMap<>();
		a.put("getRenderable", renderable);
		a.put("getX", x);
		a.put("getY", y);
		return fake(GameObject.class, a);
	}

	/** The main world's scene. */
	static Scene scene()
	{
		return fake(Scene.class, new HashMap<>());
	}
}

package com.grant9008.personalspace;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import net.runelite.api.gameval.AnimationID;
import org.junit.Assert;
import org.junit.Test;

public class HideLogTest
{
	/** Hide this player every frame from {@code fromFrame} for {@code frames} frames, a cycle per frame. */
	private static void hide(HideLog log, int id, String name, int reason, int holder, String holderName, int fromFrame, int frames)
	{
		for (int f = fromFrame; f < fromFrame + frames; f++)
		{
			if (log.notedThisFrame(id, f))
			{
				continue;
			}
			if (log.continues(id, f, reason))
			{
				log.extend(id, f, f);
				if (holder != log.toId(id))
				{
					log.setTo(id, holder, holderName);
				}
			}
			else
			{
				log.start(id, f, f, reason, name, holder, holderName, false);
			}
		}
	}

	@Test
	public void nobodyHiddenForASecondReportsNothing()
	{
		HideLog log = new HideLog();
		hide(log, 3, "Quick", HideLog.UNCONFIRMED, -1, null, 1, 20);
		Assert.assertNull(log.longest(100, 100));
	}

	@Test
	public void theLongVanishStaysInTheReportAfterManyShortOnes()
	{
		HideLog log = new HideLog();
		hide(log, 7, "Notfancysea", HideLog.WAITING_MIDDLE_TAKEN, 9, "Newcomer", 1, 300);
		// Then a hundred shorter ones within the same minute, the report read now and then.
		for (int i = 0; i < 100; i++)
		{
			hide(log, 100 + i, "Banker" + i, HideLog.WAITING_MIDDLE_TAKEN, 9, "Newcomer", 400 + 20 * i, 60);
			log.longest(462 + 20 * i, 462 + 20 * i);
		}
		String report = log.longest(2500, 2500);
		Assert.assertNotNull(report);
		Assert.assertTrue(report, report.startsWith("Notfancysea 6.0 s (waiting for a break, middle shown to Newcomer"));
	}

	@Test
	public void peopleKeptOffAFullTileDontCrowdOutSomeoneVanishing()
	{
		HideLog log = new HideLog();
		for (int i = 0; i < 5; i++)
		{
			hide(log, 20 + i, "Heap" + i, HideLog.NO_SPOT_MIDDLE_TAKEN, 1, "First", 1, 2000);
		}
		hide(log, 7, "Tender", HideLog.WAITING_MIDDLE_TAKEN, 1, "First", 1500, 300);
		String report = log.longest(2000, 2000);
		Assert.assertTrue(report, report.contains("Tender 6.0 s"));
		Assert.assertEquals("one of each reason", 1, report.split("Heap").length - 1);
	}

	@Test
	public void theMiddleChangingHandsNamesWhoHasItNow()
	{
		HideLog log = new HideLog();
		hide(log, 7, "Tender", HideLog.WAITING_MIDDLE_TAKEN, 1, "First", 1, 100);
		hide(log, 7, "Tender", HideLog.WAITING_MIDDLE_TAKEN, 2, "Second", 101, 100);
		String report = log.longest(201, 201);
		Assert.assertTrue(report, report.startsWith("Tender 4.0 s (waiting for a break, middle shown to Second, still hidden)"));
	}

	@Test
	public void aStreakEndsWhenTheyAreDrawnAgain()
	{
		HideLog log = new HideLog();
		hide(log, 7, "Tender", HideLog.UNCONFIRMED, -1, null, 1, 100);
		hide(log, 7, "Tender", HideLog.UNCONFIRMED, -1, null, 103, 100); // drawn on frames 101 and 102
		String report = log.longest(300, 300);
		Assert.assertTrue(report, report.startsWith("Tender 2.0 s (not shown by the game lately)"));
	}

	@Test
	public void someoneUndrawnForAFrameAgainAndAgainIsReportedAsFlickering()
	{
		HideLog log = new HideLog();
		for (int i = 0; i < 12; i++)
		{
			// Out for two frames, drawn for ten.
			hide(log, 7, "NoCombatKing", HideLog.NOT_HANDED_OVER, -1, null, 1 + 12 * i, 2);
		}
		hide(log, 8, "Once", HideLog.UNCONFIRMED, -1, null, 500, 2);
		String report = log.flickering(600, 600);
		Assert.assertTrue(report, report.startsWith("NoCombatKing 12 times (the game didn't draw them)"));
		Assert.assertTrue(report, report.contains("Once 1 time (not shown by the game lately)"));
		Assert.assertNull("nothing to report a minute later", log.flickering(5000, 5000));
	}

	@Test
	public void whoeverSlidFurthestIsNamedWithHowTheySlid()
	{
		HideLog log = new HideLog();
		for (int i = 0; i < 30; i++)
		{
			log.noteSlide("Dr Ang31", HideLog.SLIDE_WALKING_OFF, 100 + i, 6.4, false);
		}
		log.noteSlide("Fastgood2482", HideLog.SLIDE_BUSY, 200, 3, true);
		String report = log.sliding(300);
		Assert.assertTrue(report, report.startsWith("Dr Ang31 1.5 tiles over 30 frames (walking off a spot)"));
		Assert.assertTrue(report, report.contains("Fastgood2482 0.0 tiles over 1 frames (busy, at a fire)"));
		Assert.assertNull("nothing a minute later", log.sliding(5000));
	}

	@Test
	public void everyForestersCampfireActionIsNeverWaitedOn() throws IllegalAccessException
	{
		int checked = 0;
		for (Field f : AnimationID.class.getFields())
		{
			if (Modifier.isStatic(f.getModifiers()) && f.getType() == int.class
				&& f.getName().startsWith("FORESTRY_CAMPFIRE_BURNING_") && !f.getName().endsWith("SPOTANIM"))
			{
				Assert.assertTrue(f.getName(), PersonalSpacePlugin.neverPauses(f.getInt(null)));
				checked++;
			}
		}
		Assert.assertTrue("found the campfire actions", checked >= 13);
		Assert.assertFalse("high alchemy pauses", PersonalSpacePlugin.neverPauses(713));
		Assert.assertFalse("the spotanim isn't a player action", PersonalSpacePlugin.neverPauses(AnimationID.FORESTRY_CAMPFIRE_BURNING_SPOTANIM));
	}
}

