	{
		System.setProperty("java.awt.headless", "true");
		PersonalSpaceConfig config = (PersonalSpaceConfig) Proxy.newProxyInstance(
			PersonalSpaceConfig.class.getClassLoader(), new Class<?>[]{PersonalSpaceConfig.class},
			(proxy, method, margs) ->
			{
				if (method.isDefault())
				{
					return MethodHandles.privateLookupIn(PersonalSpaceConfig.class, MethodHandles.lookup())
						.unreflectSpecial(method, PersonalSpaceConfig.class).bindTo(proxy).invokeWithArguments(margs == null ? new Object[0] : margs);
				}
				if (method.getName().equals("toString"))
				{
					return "config";
				}
				return null;
			});
		PersonalSpacePanel panel = new PersonalSpacePanel(null, config);

		Snapshot s = new Snapshot();
		set(s, "active", true);
		set(s, "gate", Snapshot.Gate.SAFE);
		set(s, "nearby", 24);
		set(s, "still", 21);
		set(s, "stackedTiles", 4);
		set(s, "moving", 18);
		set(s, "renderer", "GPU");
		set(s, "hooked", true);
		set(s, "mode", PersonalSpaceConfig.Mode.SPREAD);
		set(s, "nudgedDrawsPerSec", 200.0);
		set(s, "revealedDrawsPerSec", 600.0);
		set(s, "pluginVersion", PersonalSpacePlugin.VERSION);
		set(s, "yourShape", "You're in a row along the counter or wall, kept close by Auto spacing");
		set(s, "spacing", 256);
		set(s, "maxStack", 5);
		set(s, "smallGroupsClose", true);
		set(s, "pauseInCombat", true);
		set(s, "hover", true);
		set(s, "hoverArrow", true);
		if (args.length > 2 && args[2].equals("nogpu"))
		{
			// As it looks with no GPU renderer running: the Turn on GPU button shows.
			set(s, "renderer", null);
			set(s, "hooked", false);
			set(s, "yourShape", null);
		}
		if (args.length > 2 && args[2].equals("alone"))
		{
			// Nobody else on your tile: the line under the status says so, at the same height.
			set(s, "yourShape", null);
		}
		for (Method m : PersonalSpacePanel.class.getDeclaredMethods())
		{
			if (m.getName().equals("update") && m.getParameterCount() == 1)
			{
				m.setAccessible(true);
				m.invoke(panel, s);
			}
		}

		int width = Integer.parseInt(args[1]);
		panel.setSize(width, 4000);
		layout(panel);
		int height = contentHeight(panel);
		panel.setSize(width, height);
		layout(panel);

		int scale = 2;
		BufferedImage image = new BufferedImage(width * scale, height * scale, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		g.scale(scale, scale);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		panel.printAll(g);
		g.dispose();
		ImageIO.write(image, "png", new File(args[0]));
		System.out.println("wrote " + args[0] + " " + width + "x" + height);
	}

	/** The height everything needs when nothing scrolls: the tallest chain of preferred sizes. */
	private static int contentHeight(Component c)
	{
		if (c instanceof javax.swing.JScrollPane)
		{
			Component view = ((javax.swing.JScrollPane) c).getViewport().getView();
			return view == null ? 0 : view.getPreferredSize().height;
		}
		if (!(c instanceof Container))
		{
			return c.getPreferredSize().height;
		}
		Container container = (Container) c;
		if (container.getLayout() instanceof java.awt.BorderLayout)
		{
			int total = 0;
			for (Component child : container.getComponents())
			{
				total += contentHeight(child);
			}
			return total;
		}
		return c.getPreferredSize().height;
	}

	private static void layout(Component c)
	{
		c.doLayout();
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				layout(child);
			}
		}
	}

	private static void set(Object o, String field, Object value)
	{
		try
		{
			Field f = o.getClass().getDeclaredField(field);
			f.setAccessible(true);
			Class<?> type = f.getType();
			if (value instanceof Number)
			{
				Number n = (Number) value;
				value = type == int.class ? (Object) n.intValue() : type == long.class ? (Object) n.longValue()
					: type == float.class ? (Object) n.floatValue() : type == double.class ? (Object) n.doubleValue() : value;
			}
			f.set(o, value);
		}
		catch (ReflectiveOperationException | RuntimeException e)
		{
			System.out.println("couldn't set " + field + ": " + e);
		}
	}

}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class ShapeMemoryTest
{
	private static final long TILE = 7L;

	private static List<StackSpreader.Entry> group(int... idAndOrientation)
	{
		List<StackSpreader.Entry> g = new ArrayList<>();
		for (int i = 0; i < idAndOrientation.length; i += 2)
		{
			g.add(new StackSpreader.Entry(idAndOrientation[i], TILE, false, idAndOrientation[i + 1]));
		}
		return g;
	}

	private static ShapeMemory.Shape tick(ShapeMemory memory, List<StackSpreader.Entry> group)
	{
		memory.startTick();
		return memory.decide(TILE, group, true);
	}

	@Test
	public void aPlayerTurningDoesNotChangeTheShape()
	{
		ShapeMemory memory = new ShapeMemory();
		ShapeMemory.Shape first = tick(memory, group(1, 1024, 2, 1024));
		Assert.assertTrue("both face north: a row", first.row);

		// Player 2 starts casting and spins round to face south, then east.
		ShapeMemory.Shape turned = tick(memory, group(1, 1024, 2, 0));
		Assert.assertTrue("same people: still a row", turned.row);
		Assert.assertEquals(first.angle, turned.angle, 1e-9);
		ShapeMemory.Shape turnedAgain = tick(memory, group(1, 1024, 2, 1536));
		Assert.assertEquals(first.angle, turnedAgain.angle, 1e-9);
	}

	@Test
	public void aCrowdBecomesARowOnceEveryoneTurnsToFaceTheSameThing()
	{
		// Two players walk up to a bank booth facing different ways, then both turn to face it.
		ShapeMemory memory = new ShapeMemory();
		Assert.assertFalse(tick(memory, group(1, 0, 2, 1024)).row);
		ShapeMemory.Shape turned = tick(memory, group(1, 1024, 2, 1024));
		Assert.assertTrue(turned.row);
		// One of them turns away again: still a row, so nobody moves.
		Assert.assertTrue(tick(memory, group(1, 0, 2, 1024)).row);
		Assert.assertEquals("one change, never back", 1, memory.changes);
	}

	@Test
	public void someoneArrivingLetsTheShapeBeReconsidered()
	{
		ShapeMemory memory = new ShapeMemory();
		Assert.assertFalse(tick(memory, group(1, 0, 2, 1024)).row);
		Assert.assertTrue(tick(memory, group(1, 1024, 2, 1024, 3, 1024)).row);
	}

	@Test
	public void aRowKeepsItsDirectionThroughSmallChangesWhenSomeoneArrives()
	{
		ShapeMemory memory = new ShapeMemory();
		ShapeMemory.Shape first = tick(memory, group(1, 1024, 2, 1024));
		// A newcomer facing a little off to one side: the row doesn't swing round for them.
		ShapeMemory.Shape after = tick(memory, group(1, 1024, 2, 1024, 3, 1150));
		Assert.assertTrue(after.row);
		Assert.assertEquals(first.angle, after.angle, 1e-9);
	}

	@Test
	public void someoneSteppingAwayAndBackDoesNotFlipTheTile()
	{
		ShapeMemory memory = new ShapeMemory();
		// Two players facing different ways: a crowd.
		Assert.assertFalse(tick(memory, group(1, 1024, 2, 0)).row);
		// Player 2 drops out for a moment. Player 1 alone would count as a row, but must not.
		Assert.assertFalse("a departure keeps the shape", tick(memory, group(1, 1024)).row);
		// Player 2 comes back: not a newcomer, nothing to reconsider.
		Assert.assertFalse(tick(memory, group(1, 1024, 2, 0)).row);
		Assert.assertEquals("no shape changes at all", 0, memory.changes);
	}

	@Test
	public void aRealNewcomerStillCountsAfterSomeoneLeft()
	{
		ShapeMemory memory = new ShapeMemory();
		Assert.assertFalse(tick(memory, group(1, 0, 2, 1024)).row);
		tick(memory, group(1, 1024));
		Assert.assertTrue("player 3 is new, and everyone faces north", tick(memory, group(1, 1024, 3, 1024)).row);
		Assert.assertEquals(1, memory.changes);
	}

	@Test
	public void circleArrangementNeverMakesRows()
	{
		ShapeMemory memory = new ShapeMemory();
		memory.startTick();
		Assert.assertFalse(memory.decide(TILE, group(1, 1024, 2, 1024), false).row);
	}

	@Test
	public void angleBetweenWrapsRound()
	{
		Assert.assertEquals(Math.toRadians(20), ShapeMemory.angleBetween(Math.toRadians(350), Math.toRadians(10)), 1e-9);
		Assert.assertEquals(Math.PI, ShapeMemory.angleBetween(0, Math.PI), 1e-9);
	}
}

package com.grant9008.personalspace;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class SlotBookTest
{
	private static final long TILE = 42L;

	private static Map<Integer, Integer> step(SlotBook book, int tick, Integer... ids)
	{
		Map<Long, List<Integer>> present = new HashMap<>();
		if (ids.length > 0)
		{
			present.put(TILE, Arrays.asList(ids));
		}
		Map<Long, Map<Integer, Integer>> out = book.update(present, tile -> 5, tick);
		return out.getOrDefault(TILE, Collections.emptyMap());
	}

	@Test
	public void newcomersTakeTheNextSpotAndNobodyElseMoves()
	{
		SlotBook book = new SlotBook();
		Map<Integer, Integer> a = step(book, 1, 10, 20);
		Assert.assertEquals(0, (int) a.get(10));
		Assert.assertEquals(1, (int) a.get(20));

		Map<Integer, Integer> b = step(book, 2, 10, 20, 5); // a lower id arrives
		Assert.assertEquals("existing players keep their spots", 0, (int) b.get(10));
		Assert.assertEquals(1, (int) b.get(20));
		Assert.assertEquals("newcomer goes to the next spot", 2, (int) b.get(5));
	}

	@Test
	public void aSpotIsHeldForSomeoneWhoStepsAwayBriefly()
	{
		SlotBook book = new SlotBook();
		step(book, 1, 1, 2, 3);
		Map<Integer, Integer> gone = step(book, 2, 1, 3); // 2 steps away
		Assert.assertEquals("3 stays put while 2's spot is held", 2, (int) gone.get(3));
		Map<Integer, Integer> back = step(book, 4, 1, 2, 3);
		Assert.assertEquals("2 gets its spot back", 1, (int) back.get(2));
		Assert.assertEquals(2, (int) back.get(3));
	}

	@Test
	public void aNewcomerWalksIntoAHeldSpotButNeverOneHeldForYou()
	{
		SlotBook book = new SlotBook();
		step(book, 1, 1, 2, 3);
		step(book, 2, 1, 3);
		Map<Integer, Integer> m = step(book, 3, 1, 3, 9);
		Assert.assertEquals("9 walks straight into the gap 2 left", 1, (int) m.get(9));
		Map<Integer, Integer> back = step(book, 4, 1, 2, 3, 9);
		Assert.assertEquals("2, back, takes the next free spot; nobody else moves", 3, (int) back.get(2));
		Assert.assertEquals(1, (int) back.get(9));

		SlotBook yours = new SlotBook();
		yours.localId = 99;
		yours.yourId = 99;
		step(yours, 1, 99, 2, 3);
		step(yours, 2, 2, 3);
		Map<Integer, Integer> n = step(yours, 3, 2, 3, 9);
		Assert.assertNotEquals("your spot is kept for you", 0, (int) n.get(9));
		Assert.assertEquals("and it's yours when you come back", 0, (int) step(yours, 4, 99, 2, 3, 9).get(99));
	}

	@Test
	public void whenAHoldRunsOutOnlyTheBackPlayerMovesForward()
	{
		SlotBook book = new SlotBook();
		step(book, 1, 1, 2, 3, 4);
		step(book, 2, 1, 3, 4); // 2 leaves for good
		Map<Integer, Integer> m = step(book, 2 + SlotBook.HOLD_TICKS + 1, 1, 3, 4);
		Assert.assertEquals("front stays", 0, (int) m.get(1));
		Assert.assertEquals("middle stays", 2, (int) m.get(3));
		Assert.assertEquals("the back player fills the gap", 1, (int) m.get(4));
	}

	@Test
	public void aFullTileLeavesExtrasWithoutASpot()
	{
		SlotBook book = new SlotBook();
		Map<Integer, Integer> m = step(book, 1, 1, 2, 3, 4, 5, 6, 7);
		Assert.assertEquals(5, m.size());
		Assert.assertFalse(m.containsKey(6));
		Assert.assertFalse(m.containsKey(7));
	}

	@Test
	public void holdsKeepATileRememberedAfterEveryoneLeaves()
	{
		SlotBook book = new SlotBook();
		step(book, 1, 1, 2);
		step(book, 2);
		Map<Integer, Integer> back = step(book, 5, 2, 1);
		Assert.assertEquals("both get their own spots back", 0, (int) back.get(1));
		Assert.assertEquals(1, (int) back.get(2));
	}

	@Test
	public void youGoStraightToTheFrontSpotAndOnlyOnePersonMakesRoom()
	{
		SlotBook book = new SlotBook();
		book.localId = 99;
		Map<Integer, Integer> before = step(book, 1, 10, 20, 30);
		Map<Integer, Integer> after = step(book, 2, 10, 20, 30, 99);
		Assert.assertEquals("you get the best spot as soon as you arrive, not off to the side first", 0, (int) after.get(99));
		int moved = 0;
		for (Map.Entry<Integer, Integer> e : before.entrySet())
		{
			moved += e.getValue().equals(after.get(e.getKey())) ? 0 : 1;
		}
		Assert.assertEquals("only whoever had it moves", 1, moved);
		Assert.assertEquals("and then everyone stays put", after, step(book, 20, 10, 20, 30, 99));
	}

	@Test
	public void yourSpotNeverPointsPastTheEndOfATileThatGotSmaller()
	{
		// Your spot was picked while your tile had five spots; then it had three. You were swapped
		// into the spot picked before, past the end, and the planner failed reading it.
		SlotBook book = new SlotBook();
		book.localId = 99;
		book.pairSideForYou.put(TILE, 3);
		Map<Long, List<Integer>> five = new HashMap<>();
		five.put(TILE, Arrays.asList(10, 20, 30, 40, 99));
		Map<Integer, Integer> first = book.update(five, tile -> 5, 1).get(TILE);
		Assert.assertEquals("you take the spot picked for you", 3, (int) first.get(99));
		Map<Long, List<Integer>> three = new HashMap<>();
		three.put(TILE, Arrays.asList(10, 20, 99));
		for (int t = 2; t <= 2 + SlotBook.LOCAL_SWAP_DELAY + 5; t++)
		{
			Map<Integer, Integer> now = book.update(three, tile -> 3, t).get(TILE);
			for (Map.Entry<Integer, Integer> e : now.entrySet())
			{
				Assert.assertTrue("tick " + t + ": player " + e.getKey() + " given spot " + e.getValue() + " of 3", e.getValue() < 3);
			}
		}
	}

	@Test
	public void stoppingNowAndThenMovesOnePersonAtATime()
	{
		// (Walking past never reaches here: nobody is given a spot until they've stood still.)
		SlotBook book = new SlotBook();
		book.localId = 99;
		Map<Integer, Integer> was = step(book, 1, 10, 20, 30);
		int moves = 0;
		for (int t = 2; t <= 40; t++)
		{
			boolean stopped = t % 12 == 0 || t % 12 == 1;
			Map<Integer, Integer> now = stopped ? step(book, t, 10, 20, 30, 99) : step(book, t, 10, 20, 30);
			int movedNow = 0;
			for (int id : new int[]{10, 20, 30})
			{
				movedNow += was.get(id).equals(now.get(id)) ? 0 : 1;
			}
			Assert.assertTrue("tick " + t + ": " + movedNow + " people moved at once", movedNow <= 1);
			moves += movedNow;
			was = now;
		}
		// Three stops: each time one person makes room, and gets their spot back once yours has
		// been held a while after you left.
		Assert.assertTrue(moves + " moves", moves <= 6);
	}

	@Test
	public void youTakeAFrontSpotHeldForSomeoneStraightAway()
	{
		// The front player steps away; you arrive while their spot is still held for them. You take
		// it the tick you arrive, nobody else moves, and when they come back they get a free spot.
		SlotBook book = new SlotBook();
		book.localId = 99;
		Map<Integer, Integer> before = step(book, 1, 10, 20, 30, 40);
		for (int t = 2; t <= 30; t++)
		{
			Map<Integer, Integer> now = t < 5 ? step(book, t, 10, 20, 30, 40) : t < 8 ? step(book, t, 20, 30, 40) : step(book, t, 20, 30, 40, 99);
			for (int id : new int[]{20, 30, 40})
			{
				Assert.assertEquals("tick " + t + ": player " + id + " was moved", before.get(id), now.get(id));
			}
			if (t >= 8)
			{
				Assert.assertEquals("tick " + t + ": you're not at the front", 0, (int) now.get(99));
			}
		}
		Map<Integer, Integer> back = step(book, 31, 10, 20, 30, 40, 99);
		Assert.assertEquals("you keep the front", 0, (int) back.get(99));
		Assert.assertEquals("they take the free spot at the back", 4, (int) back.get(10));
	}

	@Test
	public void youWalkOnceToTheFrontEvenWhenAMiddleSpotIsFree()
	{
		SlotBook book = new SlotBook();
		book.localId = 99;
		step(book, 1, 10, 20, 30, 40, 99);
		// 20 and 30 leave: their spots are held for a while, then free.
		Map<Integer, Integer> before = null;
		int yourMoves = 0;
		int was = 4;
		for (int t = 2; t <= 1 + SlotBook.HOLD_TICKS + 2; t++)
		{
			before = step(book, t, 10, 40, 99);
			yourMoves += before.get(99) == was ? 0 : 1;
			was = before.get(99);
		}
		Assert.assertEquals("you end up at the front", 0, (int) before.get(99));
		Assert.assertEquals("in one move", 1, yourMoves);
		for (int t = 1; t <= 4; t++)
		{
			Assert.assertEquals("and then nobody moves", before, step(book, 20 + t, 10, 40, 99));
		}
	}

	@Test
	public void walkingInBesideSomeoneSettlesInOneStep()
	{
		// The other player has the lower id, so without first pick they would take the front spot and
		// you would swap with them a few ticks later: the pair shuffling about once for no reason.
		SlotBook book = new SlotBook();
		book.localId = 99;
		// A tile with one person on it isn't laid out, so the pair's spots are both handed out the
		// tick you arrive: the other player has the lower id and would otherwise take the front one.
		Map<Integer, Integer> pair = step(book, 1, 7, 99);
		Assert.assertEquals("you take the front spot as you arrive", 0, (int) pair.get(99));
		for (int t = 2; t <= 2 + SlotBook.LOCAL_SWAP_DELAY + 2; t++)
		{
			Assert.assertEquals("and then nobody shuffles", pair, step(book, t, 7, 99));
		}
	}

	@Test
	public void clearForgetsEverything()
	{
		SlotBook book = new SlotBook();
		step(book, 1, 1, 2);
		book.clear();
		Map<Integer, Integer> m = step(book, 2, 2);
		Assert.assertEquals(0, (int) m.get(2));
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

public class StackRegistryTest
{
	@Test
	public void keysAreDistinctAcrossPlaneAndBothAxes()
	{
		Set<Long> keys = new HashSet<>();
		for (int plane = 0; plane < 4; plane++)
		{
			for (int x = 0; x < 200; x += 7)
			{
				for (int y = 0; y < 200; y += 7)
				{
					Assert.assertTrue("duplicate key for " + plane + "," + x + "," + y, keys.add(StackRegistry.key(plane, x, y)));
				}
			}
		}
		Assert.assertNotEquals(StackRegistry.key(0, 1, 2), StackRegistry.key(0, 2, 1));
	}

	@Test
	public void aBoatsDeckHasLayersOfItsOwn()
	{
		Assert.assertEquals("the main world's layers are its planes", 2, StackRegistry.layer(net.runelite.api.WorldView.TOPLEVEL, 2));
		int deck = StackRegistry.layer(7, 1);
		Assert.assertEquals(1, StackRegistry.planeOf(deck));
		Assert.assertEquals(7, StackRegistry.worldViewOf(deck));
		long onDeck = StackRegistry.key(deck, 50, 50);
		Assert.assertNotEquals("the same tile on a boat is not the world's", StackRegistry.key(1, 50, 50), onDeck);
		Assert.assertEquals(deck, StackRegistry.plane(onDeck));
		Assert.assertEquals(50, StackRegistry.sceneX(onDeck));
		Assert.assertEquals(50, StackRegistry.sceneY(onDeck));
		Assert.assertEquals(0, StackRegistry.worldViewOf(StackRegistry.plane(StackRegistry.key(3, 9, 9))));
	}

	@Test
	public void emptyUntilRebuiltAndNeverReturnsNull()
	{
		StackRegistry r = new StackRegistry();
		Assert.assertTrue(r.isEmpty());
		Assert.assertEquals(0, r.membersAt(StackRegistry.key(0, 10, 10)).length);
	}

	@Test
	public void rebuildGroupsPlacementsByTile()
	{
		long a = StackRegistry.key(0, 40, 50);
		long b = StackRegistry.key(0, 41, 50);
		List<StackSpreader.Placement> placements = new ArrayList<>();
		placements.add(new StackSpreader.Placement(3, a, 32, 0));
		placements.add(new StackSpreader.Placement(9, a, -32, 0));
		placements.add(new StackSpreader.Placement(5, b, 32, 0));

		StackRegistry r = new StackRegistry();
		r.rebuild(placements);
		Assert.assertFalse(r.isEmpty());
		Assert.assertArrayEquals(new int[]{3, 9}, r.membersAt(a));
		Assert.assertArrayEquals(new int[]{5}, r.membersAt(b));
		Assert.assertEquals(0, r.membersAt(StackRegistry.key(1, 40, 50)).length);
	}

	@Test
	public void rebuildReplacesTheOldTable()
	{
		long a = StackRegistry.key(0, 40, 50);
		long b = StackRegistry.key(0, 60, 60);
		StackRegistry r = new StackRegistry();
		List<StackSpreader.Placement> first = new ArrayList<>();
		first.add(new StackSpreader.Placement(3, a, 32, 0));
		r.rebuild(first);
		List<StackSpreader.Placement> second = new ArrayList<>();
		second.add(new StackSpreader.Placement(4, b, 32, 0));
		r.rebuild(second);
		Assert.assertEquals("old tile gone", 0, r.membersAt(a).length);
		Assert.assertArrayEquals(new int[]{4}, r.membersAt(b));

		r.rebuild(new ArrayList<>());
		Assert.assertTrue(r.isEmpty());
	}

	@Test
	public void clearEmptiesTheTable()
	{
		long a = StackRegistry.key(0, 40, 50);
		List<StackSpreader.Placement> placements = new ArrayList<>();
		placements.add(new StackSpreader.Placement(3, a, 32, 0));
		StackRegistry r = new StackRegistry();
		r.rebuild(placements);
		r.clear();
		Assert.assertTrue(r.isEmpty());
		Assert.assertEquals(0, r.membersAt(a).length);
	}

	@Test
	public void playersRoundAFireFaceItAndCurvedRowsTurnIn()
	{
		long fireTile = StackRegistry.key(0, 2, 2);
		long rowTile = StackRegistry.key(0, 3, 3);
		StackRegistry r = new StackRegistry();
		r.rebuild(new ArrayList<>(), java.util.Collections.singleton(rowTile), java.util.Collections.emptySet(),
			java.util.Collections.singletonMap(fireTile, new int[]{128, 0}));
		Assert.assertEquals("west of the fire, facing east", 1536, r.drawOrientation(fireTile, 0, -80, 0));
		Assert.assertEquals(StackSpreader.faceSameSpot(1024, 60, 0), r.drawOrientation(rowTile, 1024, 60, 0));
		Assert.assertEquals("anywhere else, their own facing", 700, r.drawOrientation(StackRegistry.key(0, 9, 9), 700, 60, 0));
	}

	@Test
	public void posedPairsFaceOrAngleTowardsEachOther()
	{
		long facing = StackRegistry.key(0, 4, 4);
		long angled = StackRegistry.key(0, 5, 5);
		java.util.Map<Long, PersonalSpaceConfig.Pose> poses = new java.util.HashMap<>();
		poses.put(facing, PersonalSpaceConfig.Pose.FACING);
		poses.put(angled, PersonalSpaceConfig.Pose.ANGLED);
		StackRegistry r = new StackRegistry();
		r.rebuild(new ArrayList<>(), java.util.Collections.emptySet(), java.util.Collections.emptySet(), java.util.Collections.emptyMap(), poses);
		// Drawn east of the middle: facing each other means facing west.
		Assert.assertEquals(512, r.drawOrientation(facing, 0, 80, 0));
		Assert.assertEquals(1536, r.drawOrientation(facing, 0, -80, 0));
		// Both really facing south (the camera): angled turns each halfway in.
		Assert.assertEquals(256, r.drawOrientation(angled, 0, 80, 0));
		Assert.assertEquals(1792, r.drawOrientation(angled, 0, -80, 0));
		Assert.assertEquals("someone in the middle keeps their facing", 300, r.drawOrientation(facing, 300, 0, 0));
	}

	@Test
	public void playersWithoutASpotAreRemembered()
	{
		long tile = StackRegistry.key(0, 1, 1);
		List<StackSpreader.Placement> members = new ArrayList<>();
		members.add(new StackSpreader.Placement(1, tile, 40, 0));
		members.add(new StackSpreader.Placement(2, tile, 0, 0));
		StackRegistry r = new StackRegistry();
		r.rebuild(members, java.util.Collections.emptySet(), java.util.Collections.singleton(2));
		Assert.assertTrue(r.isUnplaced(2));
		Assert.assertFalse(r.isUnplaced(1));
		r.clear();
		Assert.assertFalse(r.isUnplaced(2));
	}

	@Test
	public void plannedPlayersCarryTheirTileIntoTheRegistry()
	{
		long tile = StackRegistry.key(0, 12, 34);
		List<StackSpreader.Entry> entries = new ArrayList<>();
		entries.add(new StackSpreader.Entry(1, tile, true, 1024));
		entries.add(new StackSpreader.Entry(2, tile, false, 0));
		entries.add(new StackSpreader.Entry(3, tile, false, 512));

		CrowdPlanner.Surroundings open = new CrowdPlanner.Surroundings()
		{
			@Override
			public boolean canStand(long t, int dx, int dz)
			{
				return true;
			}

			@Override
			public boolean facesObstacle(long t, double angle)
			{
				return false;
			}

			@Override
			public boolean isCounter(long t, double angle)
			{
				return false;
			}

			@Override
			public boolean facesFire(long t, double angle)
			{
				return false;
			}

			@Override
			public List<int[]> firesNear(long t)
			{
				return new ArrayList<>();
			}
		};
		CrowdPlanner.Plan plan = new CrowdPlanner().plan(entries, id -> true, 32, 5, true, false, 1, open);
		StackRegistry r = new StackRegistry();
		r.rebuild(plan.placements);
		Assert.assertArrayEquals("local player stays put, the other two are placed on the tile", new int[]{2, 3}, r.membersAt(tile));
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class StackSpreaderTest
{
	private static final long TILE_A = 1L;
	private static final long TILE_B = 2L;

	@Test
	public void stackedTilesCountsOnlyTilesWithTwoOrMore()
	{
		List<StackSpreader.Entry> in = new ArrayList<>();
		Assert.assertEquals(0, StackSpreader.stackedTiles(in));
		in.add(new StackSpreader.Entry(1, TILE_A, false));
		in.add(new StackSpreader.Entry(2, TILE_B, false));
		Assert.assertEquals(0, StackSpreader.stackedTiles(in));
		in.add(new StackSpreader.Entry(3, TILE_A, false));
		Assert.assertEquals(1, StackSpreader.stackedTiles(in));
		in.add(new StackSpreader.Entry(4, TILE_A, false));
		Assert.assertEquals("a third player on the same tile is still one stacked tile", 1, StackSpreader.stackedTiles(in));
		in.add(new StackSpreader.Entry(5, TILE_B, false));
		Assert.assertEquals(2, StackSpreader.stackedTiles(in));
	}

	@Test
	public void aWideRowCurvesRoundTheThingInsteadOfRunningPastIt()
	{
		// Players facing north at an anvil, widest spacing: the front row stays a tile from the anvil
		// spot, doesn't go past its sides, and everyone turned to face the same spot faces the anvil.
		double focusX = 0;
		double focusZ = StackSpreader.LOOK_AHEAD;
		for (int[] o : StackSpreader.spots(true, false, Math.PI, false, PersonalSpaceConfig.MAX_SPACING, 6, null))
		{
			Assert.assertEquals("everyone is the same distance from the anvil", StackSpreader.LOOK_AHEAD,
				Math.hypot(o[0] - focusX, o[1] - focusZ), 2);
			Assert.assertTrue("went past the anvil: z " + o[1], o[1] < focusZ - 30);

			int facing = StackSpreader.faceSameSpot(1024, o[0], o[1]);
			double lookX = -Math.sin(StackSpreader.toRadians(facing));
			double lookZ = -Math.cos(StackSpreader.toRadians(facing));
			double toAnvilX = focusX - o[0];
			double toAnvilZ = focusZ - o[1];
			double cos = (lookX * toAnvilX + lookZ * toAnvilZ) / Math.hypot(toAnvilX, toAnvilZ);
			Assert.assertTrue("isn't facing the anvil from " + o[0] + "," + o[1], cos > 0.99);
		}
	}

	@Test
	public void curvedRowsBehindKeepTheFrontRowsAngles()
	{
		// Facing north: row two's whole steps sit exactly between row one's half steps.
		List<int[]> spots = StackSpreader.spots(true, false, Math.PI, false, 72, StackSpreader.CURVED_ROW_WIDTH + 2, null);
		double front = Math.atan2(spots.get(0)[0], StackSpreader.LOOK_AHEAD - spots.get(0)[1]);
		double back = Math.atan2(spots.get(StackSpreader.CURVED_ROW_WIDTH + 1)[0], StackSpreader.LOOK_AHEAD - spots.get(StackSpreader.CURVED_ROW_WIDTH + 1)[1]);
		Assert.assertEquals("row two's first step out is twice row one's half step", 2 * front, back, 0.02);
	}

	@Test
	public void aGroupFacingTheSameWayHasASharedFacing()
	{
		List<StackSpreader.Entry> group = new ArrayList<>();
		group.add(new StackSpreader.Entry(1, TILE_A, false, 1024));
		group.add(new StackSpreader.Entry(2, TILE_A, false, 1000));
		Double facing = StackSpreader.sharedFacing(group, StackSpreader.SAME_FACING);
		Assert.assertNotNull(facing);
		Assert.assertEquals(Math.PI, Math.abs(facing), 0.1);

		group.add(new StackSpreader.Entry(3, TILE_A, false, 0));
		Assert.assertNull("one facing the other way: no shared facing", StackSpreader.sharedFacing(group, StackSpreader.SAME_FACING));

		List<StackSpreader.Entry> unknown = new ArrayList<>();
		unknown.add(new StackSpreader.Entry(1, TILE_A, false));
		unknown.add(new StackSpreader.Entry(2, TILE_A, false));
		Assert.assertNull(StackSpreader.sharedFacing(unknown, StackSpreader.SAME_FACING));
	}

	@Test
	public void endsOfARowTurnInTowardsWhatEveryoneIsFacing()
	{
		// Facing north (1024) at an anvil. Pushed east, you turn to the north-west to still face it.
		int east = StackSpreader.faceSameSpot(1024, 88, 0);
		Assert.assertTrue("turned towards the west: " + east, east > 512 && east < 1024);
		// Pushed west, you turn to the north-east.
		int west = StackSpreader.faceSameSpot(1024, -88, 0);
		Assert.assertTrue("turned towards the east: " + west, west > 1024 && west < 1536);
		// The further out, the more you turn.
		Assert.assertTrue(StackSpreader.faceSameSpot(1024, 120, 0) < StackSpreader.faceSameSpot(1024, 40, 0));
		// Not moved sideways: keep facing straight ahead.
		Assert.assertEquals(1024, StackSpreader.faceSameSpot(1024, 0, 0));
		Assert.assertEquals(1024, StackSpreader.faceSameSpot(1024, 0, -30));
	}

	@Test
	public void rowTilesAreRememberedForDrawing()
	{
		StackRegistry r = new StackRegistry();
		java.util.Set<Long> rows = new java.util.HashSet<>();
		rows.add(TILE_A);
		r.rebuild(new ArrayList<>(), rows);
		Assert.assertTrue(r.isCurvedRow(TILE_A));
		Assert.assertFalse(r.isCurvedRow(TILE_B));
		r.clear();
		Assert.assertFalse(r.isCurvedRow(TILE_A));
	}

	@Test
	public void twoPlayersInACrowdStandEitherSideOfTheMiddle()
	{
		List<int[]> spots = StackSpreader.spots(false, false, 0, false, 60, 5, null);
		Assert.assertEquals(5, spots.size());
		Assert.assertEquals("first spot east", 0, spots.get(0)[1]);
		Assert.assertTrue(spots.get(0)[0] > 0);
		Assert.assertEquals("second spot straight across", -spots.get(0)[0], spots.get(1)[0]);
		Assert.assertEquals(0, spots.get(1)[1]);
	}

	@Test
	public void theSpotPatternDoesNotDependOnHowManyPlayersThereAre()
	{
		for (boolean straight : new boolean[]{false, true})
		{
			for (boolean middleTaken : new boolean[]{false, true})
			{
				List<int[]> small = StackSpreader.spots(true, straight, Math.PI, middleTaken, 80, 3, null);
				List<int[]> big = StackSpreader.spots(true, straight, Math.PI, middleTaken, 80, 10, null);
				for (int i = 0; i < small.size(); i++)
				{
					Assert.assertArrayEquals("spot " + i + " must not move when the tile gets bigger", small.get(i), big.get(i));
				}
			}
		}
	}

	@Test
	public void theMiddleIsLeftForWhoeverStaysPut()
	{
		for (boolean row : new boolean[]{false, true})
		{
			for (boolean straight : new boolean[]{false, true})
			{
				List<int[]> spots = StackSpreader.spots(row, straight, Math.PI, true, 80, 10, null);
				Assert.assertEquals(10, spots.size());
				for (int[] s : spots)
				{
					Assert.assertFalse("row=" + row + ": nobody may be put in the middle", s[0] == 0 && s[1] == 0);
				}
			}
		}
	}

	@Test
	public void twoPlayersInARowShareTheSpaceEvenly()
	{
		// Facing north, at an anvil (curved row) and at a counter (straight row).
		for (boolean straight : new boolean[]{false, true})
		{
			List<int[]> spots = StackSpreader.spots(true, straight, Math.PI, false, 42, 2, null);
			Assert.assertEquals(2, spots.size());
			Assert.assertEquals("either side of the middle", -spots.get(0)[0], spots.get(1)[0]);
			Assert.assertEquals(spots.get(0)[1], spots.get(1)[1]);
			Assert.assertEquals("one spacing apart", 42.0, spots.get(0)[0] - spots.get(1)[0], 2.0);
		}
	}

	@Test
	public void aFourthPlayerAtACounterStillJoinsTheFrontRowWhenOneSideIsBlocked()
	{
		// Facing north at a counter with a rope barrier just east of the tile.
		List<int[]> spots = StackSpreader.spots(true, true, Math.PI, false, 42, 10, (dx, dz) -> dx <= 38);
		for (int i = 0; i < 4; i++)
		{
			Assert.assertEquals("spot " + i + " is in the front row", 0, spots.get(i)[1]);
			Assert.assertTrue(spots.get(i)[0] <= 38);
		}
		Assert.assertEquals("the first two still share the middle", -spots.get(0)[0], spots.get(1)[0]);
	}

	@Test
	public void aCurvedRowWrapsRoundTheThingBeforeAnyoneStandsBehind()
	{
		// Facing north: what everyone faces is 128 north of the tile centre.
		List<int[]> spots = StackSpreader.spots(true, false, Math.PI, false, 60, StackSpreader.CURVED_ROW_WIDTH + 1, null);
		for (int i = 0; i < StackSpreader.CURVED_ROW_WIDTH; i++)
		{
			Assert.assertEquals("spot " + i + " is in the front ring", 128, Math.hypot(spots.get(i)[0], 128 - spots.get(i)[1]), 1.5);
		}
		Assert.assertTrue("the next one is in the row behind",
			Math.hypot(spots.get(StackSpreader.CURVED_ROW_WIDTH)[0], 128 - spots.get(StackSpreader.CURVED_ROW_WIDTH)[1]) > 150);
	}

	@Test
	public void aRowBehindStandsInTheGaps()
	{
		List<int[]> spots = StackSpreader.spots(true, true, Math.PI, false, 42, StackSpreader.ROW_WIDTH + 1, null);
		Assert.assertEquals("the second row starts straight behind the middle", 0, spots.get(StackSpreader.ROW_WIDTH)[0]);
		Assert.assertTrue(spots.get(StackSpreader.ROW_WIDTH)[1] < 0);
	}

	@Test
	public void aCurvedRowNeverWrapsPastTheWrapLimit()
	{
		for (int spacing : new int[]{PersonalSpaceConfig.MIN_SPACING, 72, 160, PersonalSpaceConfig.MAX_SPACING})
		{
			for (boolean middleTaken : new boolean[]{false, true})
			{
				for (int[] s : StackSpreader.spots(true, false, Math.PI, middleTaken, spacing, 17, null))
				{
					double round = Math.atan2(Math.abs(s[0]), 128 - s[1]);
					Assert.assertTrue("spacing " + spacing + ": " + Math.toDegrees(round) + " degrees round",
						round <= StackSpreader.WRAP_ARC + 0.02);
				}
			}
		}
	}

	@Test
	public void blockedSpotsAreSkippedAndTheNextOneIsUsed()
	{
		// Anything to the north (into a booth) is off limits.
		List<int[]> spots = StackSpreader.spots(false, false, 0, false, 80, 6, (dx, dz) -> dz <= 20);
		Assert.assertEquals(6, spots.size());
		for (int[] s : spots)
		{
			Assert.assertTrue("spot in the booth: " + s[1], s[1] <= 20);
		}
	}

	@Test
	public void wideSpacingDoesNotFlingRowsFarBack()
	{
		for (boolean straight : new boolean[]{false, true})
		{
			for (int[] s : StackSpreader.spots(true, straight, Math.PI, false, PersonalSpaceConfig.MAX_SPACING, 17, null))
			{
				Assert.assertTrue("at most two row-depths back: " + s[1], s[1] >= -2 * StackSpreader.ROW_DEPTH - 2);
			}
		}
	}

	@Test
	public void backRowsStandBehindTheFrontRow()
	{
		// Facing north: the front row is nearer the thing, row two is a spacing further back.
		int back = StackSpreader.CURVED_ROW_WIDTH;
		List<int[]> spots = StackSpreader.spots(true, false, Math.PI, false, 80, back + 1, null);
		Assert.assertTrue("back row is further south: " + spots.get(0)[1] + " vs " + spots.get(back)[1], spots.get(back)[1] < spots.get(0)[1] - 40);
	}

	@Test
	public void firesAreRecognisedByName()
	{
		Assert.assertTrue(StackSpreader.isFireName("Fire"));
		Assert.assertTrue(StackSpreader.isFireName("Forester's Campfire"));
		Assert.assertTrue(StackSpreader.isFireName("Fire pit"));
		Assert.assertFalse(StackSpreader.isFireName("Fireplace"));
		Assert.assertFalse(StackSpreader.isFireName("Anvil"));
		Assert.assertFalse(StackSpreader.isFireName(null));
	}
}

package com.grant9008.personalspace;

import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class StatusSummaryTest
{
	/** A snapshot of the plugin happily spreading players at the GE. Tests break one thing at a time. */
	private static Snapshot working()
	{
		Snapshot s = new Snapshot();
		s.active = true;
		s.mode = PersonalSpaceConfig.Mode.SPREAD;
		s.spacing = PersonalSpaceConfig.SPACING_NORMAL;
		s.maxStack = 5;
		s.testOffset = 32;
		s.gate = Snapshot.Gate.SAFE;
		s.renderer = "GPU plugin";
		s.hooked = true;
		s.playerDrawsPerSec = 300;
		s.nudgedDrawsPerSec = 40;
		s.nearby = 80;
		s.still = 50;
		s.stackedTiles = 2;
		s.moving = 4;
		return s;
	}

	private static StatusSummary.Headline headline(Snapshot s)
	{
		return StatusSummary.headline(s);
	}

	@Test
	public void workingSaysHowManyAreSpread()
	{
		StatusSummary.Headline h = headline(working());
		Assert.assertEquals(StatusSummary.Level.OK, h.level);
		Assert.assertEquals("Spreading 4 players on 2 tiles", h.title);
	}

	@Test
	public void singularWording()
	{
		Snapshot s = working();
		s.moving = 1;
		s.stackedTiles = 1;
		Assert.assertEquals("Spreading 1 player on 1 tile", headline(s).title);
	}

	@Test
	public void pausedWinsOverEverythingElse()
	{
		Snapshot s = working();
		s.active = false;
		s.renderer = null;
		Assert.assertEquals(StatusSummary.Level.PAUSED, headline(s).level);
	}

	@Test
	public void notLoggedInIsWaitingNotAProblem()
	{
		Snapshot s = working();
		s.gate = Snapshot.Gate.NOT_LOGGED_IN;
		s.hooked = false;
		Assert.assertEquals(StatusSummary.Level.WAITING, headline(s).level);
	}

	@Test
	public void safetyGatesSayWhy()
	{
		Snapshot s = working();
		s.gate = Snapshot.Gate.WILDERNESS;
		StatusSummary.Headline h = headline(s);
		Assert.assertEquals(StatusSummary.Level.PAUSED, h.level);
		Assert.assertTrue(h.detail.contains("Wilderness"));
	}

	@Test
	public void noRendererTellsYouToTurnOnGpu()
	{
		Snapshot s = working();
		s.renderer = null;
		s.hooked = false;
		StatusSummary.Headline h = headline(s);
		Assert.assertEquals(StatusSummary.Level.PROBLEM, h.level);
		Assert.assertTrue(h.title.contains("GPU"));
	}

	@Test
	public void notHookedIsAProblem()
	{
		Snapshot s = working();
		s.hooked = false;
		Assert.assertEquals(StatusSummary.Level.PROBLEM, headline(s).level);
	}

	@Test
	public void aBriefGapInPlayerDrawsIsNotAlarming()
	{
		Snapshot s = working();
		s.playerDrawsPerSec = 0;
		s.nudgedDrawsPerSec = 0;
		Assert.assertNotEquals(StatusSummary.Level.PROBLEM, headline(s).level);
	}

	@Test
	public void sustainedNoPlayerDrawsIsAProblem()
	{
		Snapshot s = working();
		s.playerDrawsPerSec = 0;
		s.noPlayerDrawsSustained = true;
		StatusSummary.Headline h = headline(s);
		Assert.assertEquals(StatusSummary.Level.PROBLEM, h.level);
		Assert.assertTrue(h.detail.contains("Copy report"));
	}

	@Test
	public void noStackedPlayersIsWaiting()
	{
		Snapshot s = working();
		s.stackedTiles = 0;
		s.moving = 0;
		s.nudgedDrawsPerSec = 0;
		StatusSummary.Headline h = headline(s);
		Assert.assertEquals(StatusSummary.Level.WAITING, h.level);
		Assert.assertEquals("No crowds here", h.title);
	}

	@Test
	public void revealingHiddenPlayersAloneCountsAsWorking()
	{
		Snapshot s = working();
		s.nudgedDrawsPerSec = 0; // e.g. you are the drawn player and stay put
		s.revealedDrawsPerSec = 120;
		Assert.assertEquals(StatusSummary.Level.OK, headline(s).level);
	}

	@Test
	public void oddityRowCoversEveryShouldNeverHappenCounter()
	{
		Snapshot s = working();
		s.offThreadDraws = 1;
		Assert.assertTrue(hasLabel(StatusSummary.checks(s), "Oddities"));
		s = working();
		s.revealErrors = 2;
		Assert.assertTrue(hasLabel(StatusSummary.checks(s), "Oddities"));
	}

	@Test
	public void stackedButNotYetDrawnMovedIsWaitingUntilSustained()
	{
		Snapshot s = working();
		s.nudgedDrawsPerSec = 0;
		Assert.assertEquals(StatusSummary.Level.WAITING, headline(s).level);
		s.nothingMovedSustained = true;
		Assert.assertEquals(StatusSummary.Level.PROBLEM, headline(s).level);
	}

	@Test
	public void testModeWorking()
	{
		Snapshot s = working();
		s.mode = PersonalSpaceConfig.Mode.TEST_SHIFT_ME;
		s.stackedTiles = 0;
		s.moving = 1;
		StatusSummary.Headline h = headline(s);
		Assert.assertEquals(StatusSummary.Level.OK, h.level);
		Assert.assertTrue(h.detail.contains("32 units"));
		Assert.assertEquals("Test mode is on", h.title);
	}

	@Test
	public void testModeWithZeroOffsetExplainsTheSlider()
	{
		Snapshot s = working();
		s.mode = PersonalSpaceConfig.Mode.TEST_SHIFT_ME;
		s.testOffset = 0;
		s.moving = 0;
		s.nudgedDrawsPerSec = 0;
		Assert.assertEquals(StatusSummary.Level.WAITING, headline(s).level);
	}

	@Test
	public void testModeSustainedNothingShiftedIsAProblem()
	{
		Snapshot s = working();
		s.mode = PersonalSpaceConfig.Mode.TEST_SHIFT_ME;
		s.moving = 1;
		s.nudgedDrawsPerSec = 0;
		s.nothingMovedSustained = true;
		Assert.assertEquals(StatusSummary.Level.PROBLEM, headline(s).level);
	}

	@Test
	public void checksHideSafetyAndDrawRateWhenLoggedOut()
	{
		Snapshot s = working();
		s.gate = Snapshot.Gate.NOT_LOGGED_IN;
		List<StatusSummary.Check> checks = StatusSummary.checks(s);
		for (StatusSummary.Check c : checks)
		{
			Assert.assertNotEquals("Safety", c.label);
			Assert.assertNotEquals("Players drawn", c.label);
		}
	}

	@Test
	public void oddityRowAppearsOnlyWhenSomethingOddHappened()
	{
		Snapshot s = working();
		Assert.assertFalse(hasLabel(StatusSummary.checks(s), "Oddities"));
		s.playersInOtherCalls = 3;
		Assert.assertTrue(hasLabel(StatusSummary.checks(s), "Oddities"));
	}

	@Test
	public void reportContainsTheNumbersNeededToDebug()
	{
		Snapshot s = working();
		String r = StatusSummary.report(s);
		Assert.assertTrue(r.startsWith("Personal Space " + PersonalSpacePlugin.VERSION));
		Assert.assertTrue(r.contains("Renderer: GPU plugin, connected yes"));
		Assert.assertTrue(r.contains("Player draws/sec: 300"));
		Assert.assertTrue(r.contains("stacked tiles: 2"));
		Assert.assertTrue(r.contains("players in other calls (should be 0): 0"));
		Assert.assertTrue(r.contains("hidden shown/sec: 0"));
		Assert.assertTrue(r.contains("pause in combat yes"));
	}

	private static boolean hasLabel(List<StatusSummary.Check> checks, String label)
	{
		for (StatusSummary.Check c : checks)
		{
			if (c.label.equals(label))
			{
				return true;
			}
		}
		return false;
	}
}

package com.grant9008.personalspace;

import org.junit.Assert;
import org.junit.Test;

public class StillnessTrackerTest
{
	private static final long TILE_A = 10L;
	private static final long TILE_B = 11L;

	@Test
	public void standingInTheMiddleOfOneTileForTwoTicksCountsAsStill()
	{
		StillnessTracker t = new StillnessTracker();
		Assert.assertFalse("one tick is not enough", t.observe(7, TILE_A, true, 1));
		Assert.assertTrue(t.observe(7, TILE_A, true, 2));
		Assert.assertTrue("and stays still", t.observe(7, TILE_A, true, 3));
	}

	@Test
	public void beingBetweenTilesIsNeverStill()
	{
		StillnessTracker t = new StillnessTracker();
		Assert.assertFalse(t.observe(7, TILE_A, false, 1));
		Assert.assertFalse(t.observe(7, TILE_A, false, 2));
	}

	@Test
	public void walkingOntoANewTileResetsStillness()
	{
		StillnessTracker t = new StillnessTracker();
		t.observe(7, TILE_A, true, 1);
		Assert.assertTrue(t.observe(7, TILE_A, true, 2));
		Assert.assertFalse("arrived on a different tile", t.observe(7, TILE_B, true, 3));
		Assert.assertTrue("then waited a tick there", t.observe(7, TILE_B, true, 4));
	}

	@Test
	public void passingThroughTheCentreMidWalkDoesNotCount()
	{
		StillnessTracker t = new StillnessTracker();
		t.observe(7, TILE_A, true, 1);
		Assert.assertFalse(t.observe(7, TILE_A, false, 2));
		Assert.assertFalse("stillness must restart after moving", t.observe(7, TILE_A, true, 3));
	}

	@Test
	public void aMissedTickResetsStillness()
	{
		StillnessTracker t = new StillnessTracker();
		t.observe(7, TILE_A, true, 1);
		Assert.assertFalse("not seen on tick 2, so tick 3 starts over", t.observe(7, TILE_A, true, 3));
	}

	@Test
	public void clearForgetsEveryone()
	{
		StillnessTracker t = new StillnessTracker();
		t.observe(7, TILE_A, true, 1);
		t.clear();
		Assert.assertFalse(t.observe(7, TILE_A, true, 2));
	}

	@Test
	public void outOfRangeIdsAreIgnored()
	{
		StillnessTracker t = new StillnessTracker();
		Assert.assertFalse(t.observe(-1, TILE_A, true, 1));
		Assert.assertFalse(t.observe(OffsetTable.CAPACITY, TILE_A, true, 1));
	}

	@Test
	public void centreOfATileIsHalfATileIn()
	{
		Assert.assertTrue(StillnessTracker.isCentred(64, 64));
		Assert.assertTrue(StillnessTracker.isCentred(128 * 40 + 64, 128 * 7 + 64));
		Assert.assertFalse(StillnessTracker.isCentred(128 * 40 + 70, 128 * 7 + 64));
		Assert.assertFalse(StillnessTracker.isCentred(128 * 40, 128 * 7 + 64));
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * Someone walking or running off a spot is drawn where they really are plus what is left of their
 * offset. Out of a crowd round a smithy's anvil, that was across the room's wall from where they
 * really ran, and through it by the door. Frame by frame, as the plugin runs it: the game moves them
 * along their path, the offsets move ({@link OffsetTable#advance}) and are kept clear of walls
 * ({@link OffsetTable#keepClear}). What is drawn is checked here without the plugin's own wall code.
 */
public class WalkingOffWallsTest
{
	private static final int SIZE = 40;
	private static final int ID = 7;
	private static final float DT = 0.02f;

	private int[][][] flags;

	private void room(int x0, int z0, int x1, int z1, int doorX)
	{
		flags = new int[4][][];
		flags[0] = new int[SIZE][SIZE];
		for (int x = x0; x <= x1; x++)
		{
			if (x != doorX)
			{
				wallNorth(x, z1);
			}
			wallNorth(x, z0 - 1);
		}
		for (int z = z0; z <= z1; z++)
		{
			wallEast(x1, z);
			wallEast(x0 - 1, z);
		}
	}

	private void wallNorth(int x, int z)
	{
		flags[0][x][z] |= CollisionTerrain.BLOCK_NORTH;
		flags[0][x][z + 1] |= CollisionTerrain.BLOCK_SOUTH;
	}

	private void wallEast(int x, int z)
	{
		flags[0][x][z] |= CollisionTerrain.BLOCK_EAST;
		flags[0][x + 1][z] |= CollisionTerrain.BLOCK_WEST;
	}

	private boolean blocked(int x, int z)
	{
		return x < 0 || z < 0 || x >= SIZE || z >= SIZE || (flags[0][x][z] & CollisionTerrain.BLOCK_FULL) != 0;
	}

	/** Whether a straight move between two drawn points goes through a wall or a blocked tile, sampled a unit at a time. */
	private boolean throughSomething(double ax, double az, double bx, double bz)
	{
		int n = Math.max(1, (int) Math.ceil(Math.hypot(bx - ax, bz - az)));
		int px = (int) Math.floor(ax / 128);
		int pz = (int) Math.floor(az / 128);
		if (blocked(px, pz))
		{
			return true;
		}
		for (int k = 1; k <= n; k++)
		{
			int tx = (int) Math.floor((ax + (bx - ax) * k / n) / 128);
			int tz = (int) Math.floor((az + (bz - az) * k / n) / 128);
			if (tx == px && tz == pz)
			{
				continue;
			}
			if (blocked(tx, tz))
			{
				return true;
			}
			int sx = tx - px;
			int sz = tz - pz;
			boolean ok = sx != 0 && sz != 0
				? CollisionTerrain.canStep(flags[0], px, pz, sx, 0) && CollisionTerrain.canStep(flags[0], px + sx, pz, 0, sz)
					|| CollisionTerrain.canStep(flags[0], px, pz, 0, sz) && CollisionTerrain.canStep(flags[0], px, pz + sz, sx, 0)
				: CollisionTerrain.canStep(flags[0], px, pz, sx, sz);
			if (!ok)
			{
				return true;
			}
			px = tx;
			pz = tz;
		}
		return false;
	}

	/** What happened over one walk off a spot. */
	private static final class Run
	{
		int framesThrough;
		int framesOnBlocked;
		double biggestStep;
		/** The most anyone was drawn moving in a frame beyond their real step and the pace an offset runs out at. */
		double biggestExcess;
		int framesUntilGone = -1;
		final List<double[]> drawn = new ArrayList<>();
		boolean walkingWhileDrawnMovingStill = true;
	}

	/**
	 * Someone standing on tile (x, z) with this offset walks (or runs) the path, the way the client
	 * moves people: each axis by up to its speed a cycle, stopping on each tile it's heading for.
	 * Then they stand where they got to until their offset has run out.
	 */
	private Run walkOff(int x, int z, int offsetX, int offsetZ, int[][] path, boolean running, boolean guarded)
	{
		OffsetTable t = new OffsetTable();
		OffsetTable.Walls walls = new CollisionTerrain(flags).walls(0);
		t.setTarget(ID, offsetX, offsetZ);
		for (int i = 0; i < 200; i++)
		{
			t.advance(DT);
			if (guarded)
			{
				t.keepClear(ID, x * 128 + 64, z * 128 + 64, false, DT, false, walls);
			}
		}
		Assert.assertEquals("in their spot to start with", offsetX, t.dx(ID));
		// They set off: next tick their target is the middle and they ease back gently (they're off it).
		t.clearTargets();
		t.setWalkingOff(ID, true);
		Run run = new Run();
		int px = x * 128 + 64;
		int pz = z * 128 + 64;
		int next = 0;
		int speed = running ? 8 : 4;
		double lastX = px + t.dx(ID);
		double lastZ = pz + t.dz(ID);
		boolean walkedLastFrame = false;
		for (int frame = 0; frame < 2000; frame++)
		{
			int fromX = px;
			int fromZ = pz;
			boolean moving = next < path.length;
			if (moving)
			{
				int tx = path[next][0] * 128 + 64;
				int tz = path[next][1] * 128 + 64;
				px += Math.max(-speed, Math.min(speed, tx - px));
				pz += Math.max(-speed, Math.min(speed, tz - pz));
				if (px == tx && pz == tz)
				{
					next++;
				}
			}
			if (frame % 30 == 29)
			{
				// A game tick: whether they're off the middle of a tile is looked at once a tick.
				t.setWalkingOff(ID, !StillnessTracker.isCentred(px, pz));
			}
			t.advance(DT);
			if (guarded && t.isOffset(ID))
			{
				t.keepClear(ID, px, pz, moving, DT, true, walls);
			}
			double dx = px + t.dx(ID);
			double dz = pz + t.dz(ID);
			if (throughSomething(px, pz, dx, dz) && !t.isFollowing(ID) || throughSomething(lastX, lastZ, dx, dz))
			{
				run.framesThrough++;
			}
			if (blocked((int) Math.floor(dx / 128), (int) Math.floor(dz / 128)))
			{
				run.framesOnBlocked++;
			}
			double step = Math.hypot(dx - lastX, dz - lastZ);
			run.biggestStep = Math.max(run.biggestStep, step);
			run.biggestExcess = Math.max(run.biggestExcess, step - Math.hypot(px - fromX, pz - fromZ)
				- (moving ? OffsetTable.CATCH_UP : OffsetTable.WALK_SPEED) * DT);
			// (The last stride of a walk lands them where they are, as the walk ends: not a slide.)
			if (!moving && step >= 2 && !t.isWalking(ID) && !walkedLastFrame)
			{
				run.walkingWhileDrawnMovingStill = false;
			}
			walkedLastFrame = t.isWalking(ID);
			run.drawn.add(new double[]{dx, dz});
			lastX = dx;
			lastZ = dz;
			if (!t.isOffset(ID) && !moving)
			{
				run.framesUntilGone = frame;
				break;
			}
		}
		return run;
	}

	/** West along the inside of the north wall to the door in the room's north-west corner, out through it, and on. */
	private static final int[][] OUT_OF_THE_DOOR = {{13, 14}, {12, 14}, {11, 14}, {10, 14}, {10, 15}, {10, 16}, {10, 17}, {10, 18}, {11, 19}, {12, 20}};

	@Test
	public void runningOutOfTheDoorNeverCrossesTheWall()
	{
		// A room 10..20 by 8..14, the door in the north wall's west end; they stood at (14, 14) with
		// their spot most of two tiles east along the wall, and run west and out.
		room(10, 8, 20, 14, 10);
		Run base = walkOff(14, 14, 230, -20, OUT_OF_THE_DOOR, true, false);
		Assert.assertTrue("unguarded, they're drawn through the wall by the door", base.framesThrough > 0);

		Run run = walkOff(14, 14, 230, -20, OUT_OF_THE_DOOR, true, true);
		Assert.assertEquals("never drawn through the wall", 0, run.framesThrough);
		Assert.assertEquals("never on anything that can't be stood on", 0, run.framesOnBlocked);
		Assert.assertTrue("their offset runs out", run.framesUntilGone > 0);
	}

	@Test
	public void walkingOutOfTheDoorNeverCrossesTheWallEither()
	{
		// From a tile beside the door, every way their spot might be.
		room(10, 8, 20, 14, 10);
		int[][] path = {{10, 14}, {10, 15}, {10, 16}, {10, 17}, {11, 18}};
		Assert.assertTrue("unguarded, through the wall", walkOff(11, 14, 230, -20, path, false, false).framesThrough > 0);
		for (int[] spot : new int[][]{{230, -20}, {180, -120}, {-40, -150}, {150, 0}, {60, -200}})
		{
			Run run = walkOff(11, 14, spot[0], spot[1], path, false, true);
			Assert.assertEquals("spot " + spot[0] + "," + spot[1], 0, run.framesThrough);
			Assert.assertEquals(0, run.framesOnBlocked);
			Assert.assertTrue(run.framesUntilGone > 0);
		}
	}

	@Test
	public void runningAtAWallWithTheirSpotAheadStopsThemShortOfIt()
	{
		// Their spot is most of two tiles west of their tile, and they run west to the room's west wall
		// (tile 10), then north along it: unguarded they were drawn out through the wall.
		room(10, 8, 20, 14, 10);
		int[][] path = {{12, 11}, {11, 11}, {10, 11}, {10, 12}, {10, 13}, {10, 14}};
		Run base = walkOff(13, 11, -230, 30, path, true, false);
		Assert.assertTrue(base.framesOnBlocked > 0 || base.framesThrough > 0);

		Run run = walkOff(13, 11, -230, 30, path, true, true);
		Assert.assertEquals(0, run.framesThrough);
		Assert.assertEquals(0, run.framesOnBlocked);
		for (double[] d : run.drawn)
		{
			Assert.assertTrue("kept clear of the west wall", d[0] >= 10 * 128 + CollisionTerrain.EDGE_MARGIN - 1);
		}
	}

	@Test
	public void nobodyJumpsAndLegsKeepPace()
	{
		room(10, 8, 20, 14, 10);
		for (boolean running : new boolean[]{false, true})
		{
			Run run = walkOff(14, 14, 230, -20, OUT_OF_THE_DOOR, running, true);
			// No faster than their real self and the pace an offset runs out at: a walk, never a jump.
			Assert.assertTrue("faster by " + run.biggestExcess, run.biggestExcess <= 1.5);
			Assert.assertTrue("drawn walking whenever they move while their real self stands", run.walkingWhileDrawnMovingStill);
		}
	}

	@Test
	public void stoppingJustOutsideTheDoorTheyWalkTheRestOfTheWayRound()
	{
		// Out of the door and stop on the next tile: their real self stands outside while they are
		// still drawn inside; they walk round through the door rather than through the wall.
		room(10, 8, 20, 14, 10);
		int[][] path = {{13, 14}, {12, 14}, {11, 14}, {10, 14}, {10, 15}};
		Run run = walkOff(14, 14, 230, -20, path, true, true);
		Assert.assertEquals(0, run.framesThrough);
		Assert.assertEquals(0, run.framesOnBlocked);
		Assert.assertTrue(run.walkingWhileDrawnMovingStill);
		Assert.assertTrue(run.framesUntilGone > 0);
	}

	@Test
	public void standingOnTheFarSideOfAFenceTheyComeBackWithoutAJump()
	{
		// A fence along the east edge of column 15. Their spot is across it (it shouldn't be, but a
		// crowd's spot has been): there's no way round to follow, and they used to jump back over it.
		flags = new int[4][][];
		flags[0] = new int[SIZE][SIZE];
		for (int z = 10; z <= 20; z++)
		{
			wallEast(15, z);
		}
		int[][] path = {{14, 15}, {13, 15}, {12, 15}, {11, 15}, {10, 15}};
		for (boolean running : new boolean[]{false, true})
		{
			Run run = walkOff(15, 15, 120, 10, path, running, true);
			// No faster than following would take them (give or take a unit's rounding either frame), not most of a tile at once.
			Assert.assertTrue("faster by " + run.biggestExcess, run.biggestExcess <= 2.5);
			Assert.assertEquals(0, run.framesOnBlocked);
			Assert.assertTrue("their offset runs out", run.framesUntilGone > 0);
			double[] last = run.drawn.get(run.drawn.size() - 1);
			Assert.assertTrue("back on their side of it", last[0] < 16 * 128);
		}
	}

	@Test
	public void inTheOpenTheirOffsetRunsOutJustAsBefore()
	{
		flags = new int[4][][];
		flags[0] = new int[SIZE][SIZE];
		int[][] path = {{14, 15}, {13, 16}, {12, 17}, {12, 18}, {12, 19}};
		Run base = walkOff(15, 15, 200, -90, path, true, false);
		Run run = walkOff(15, 15, 200, -90, path, true, true);
		Assert.assertEquals(base.drawn.size(), run.drawn.size());
		for (int i = 0; i < base.drawn.size(); i++)
		{
			Assert.assertEquals(base.drawn.get(i)[0], run.drawn.get(i)[0], 0.0);
			Assert.assertEquals(base.drawn.get(i)[1], run.drawn.get(i)[1], 0.0);
		}
	}

	@Test
	public void aTeleportTakesTheOffsetAway()
	{
		flags = new int[4][][];
		flags[0] = new int[SIZE][SIZE];
		OffsetTable t = new OffsetTable();
		OffsetTable.Walls walls = new CollisionTerrain(flags).walls(0);
		t.setTarget(ID, 150, 0);
		for (int i = 0; i < 100; i++)
		{
			t.advance(DT);
			t.keepClear(ID, 1000, 1000, false, DT, false, walls);
		}
		t.clearTargets();
		t.advance(DT);
		t.keepClear(ID, 3000, 3000, false, DT, true, walls);
		Assert.assertFalse(t.isOffset(ID));
	}
}

package com.grant9008.personalspace;

import java.lang.reflect.Proxy;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.PlayerComposition;
import net.runelite.api.kit.KitType;
import org.junit.Assert;
import org.junit.Test;

/** Who counts as wearing a cape: anything at all in the cape slot, and nothing anywhere else. */
public class WearsCapeTest
{
	/** A player's look, wearing these items (item ids) in these slots and nothing else. */
	private static PlayerComposition wearing(Map<KitType, Integer> items)
	{
		return (PlayerComposition) Proxy.newProxyInstance(PlayerComposition.class.getClassLoader(), new Class<?>[]{PlayerComposition.class},
			(proxy, method, args) ->
			{
				if (method.getName().equals("getEquipmentId"))
				{
					return items.getOrDefault((KitType) args[0], -1);
				}
				Class<?> type = method.getReturnType();
				return type == boolean.class ? false : type == int.class ? 0 : null;
			});
	}

	@Test
	public void anythingInTheCapeSlotIsACape()
	{
		Map<KitType, Integer> items = new EnumMap<>(KitType.class);
		Assert.assertFalse("nothing on", PersonalSpacePlugin.wearsCape(wearing(items)));
		items.put(KitType.TORSO, 1121);
		items.put(KitType.AMULET, 1704);
		Assert.assertFalse("a body and an amulet, no cape", PersonalSpacePlugin.wearsCape(wearing(items)));
		items.put(KitType.CAPE, 9795);
		Assert.assertTrue("a smithing cape", PersonalSpacePlugin.wearsCape(wearing(items)));
		items.put(KitType.CAPE, 10499);
		Assert.assertTrue("an Ava's accumulator", PersonalSpacePlugin.wearsCape(wearing(items)));
		Assert.assertFalse("a look the game hasn't sent yet", PersonalSpacePlugin.wearsCape(null));
	}

	@Test
	public void anEntryWearsNoCapeUnlessItSaysSo()
	{
		Assert.assertFalse(new StackSpreader.Entry(1, 2L, false, 0, true).cape);
		Assert.assertFalse(new StackSpreader.Entry(1, 2L, false).cape);
		Assert.assertTrue(new StackSpreader.Entry(1, 2L, false, 0, true, true).cape);
	}
}
